    pub fn set_game_event_quest_complete_sender_like_cpp(
        &mut self,
        sender: flume::Sender<GameEventQuestCompleteCommandLikeCpp>,
    ) {
        self.game_event_quest_complete_tx = Some(sender);
    }

    pub async fn notify_game_event_quest_complete_like_cpp(
        &self,
        quest_id: u32,
    ) -> GameEventQuestCompleteClientOutcomeLikeCpp {
        let Some(sender) = self.game_event_quest_complete_tx.as_ref() else {
            return GameEventQuestCompleteClientOutcomeLikeCpp::SenderMissing { quest_id };
        };

        let (response_tx, response_rx) = flume::bounded(1);
        let command = GameEventQuestCompleteCommandLikeCpp {
            quest_id,
            response_tx,
        };
        if sender.try_send(command).is_err() {
            return GameEventQuestCompleteClientOutcomeLikeCpp::SendFailed { quest_id };
        }

        match tokio::time::timeout(Duration::from_millis(250), response_rx.recv_async()).await {
            Ok(Ok(response)) => GameEventQuestCompleteClientOutcomeLikeCpp::Ok(response),
            Ok(Err(_)) => {
                GameEventQuestCompleteClientOutcomeLikeCpp::ResponseChannelClosed { quest_id }
            }
            Err(_) => GameEventQuestCompleteClientOutcomeLikeCpp::ResponseTimeout { quest_id },
        }
    }

    fn canonical_player_entity_snapshot_like_cpp(&self) -> Option<Player> {
        self.canonical_player_entity_snapshot_for_map_like_cpp(wow_map::MapKey::new(
            u32::from(self.player_map_id_like_cpp()),
            0,
        ))
    }

    fn canonical_player_entity_snapshot_for_map_like_cpp(
        &self,
        key: wow_map::MapKey,
    ) -> Option<Player> {
        let guid = self.player_guid()?;
        let position = self.player_position_like_cpp()?;
        let name = self.player_name_like_cpp()?;
        let mut player = Player::new(Some(u64::from(self.account_id)), false);
        player.unit_mut().world_mut().object_mut().create(guid);
        player.unit_mut().world_mut().set_name(name);
        player
            .unit_mut()
            .world_mut()
            .set_map(key.map_id, key.instance_id)
            .ok()?;
        player.unit_mut().world_mut().relocate(position);
        *player.unit_mut().world_mut().phase_shift_mut() =
            self.represented_player_phase_shift.clone();
        player.unit_mut().world_mut().object_mut().add_to_world();
        player.set_race_class_gender(
            self.player_race_like_cpp(),
            self.player_class_like_cpp(),
            gender_from_u8(self.player_gender_like_cpp()),
        );
        player.unit_mut().set_level(self.player_level_like_cpp());
        player
            .unit_mut()
            .set_max_health(u64::from(self.player_max_health_like_cpp));
        player
            .unit_mut()
            .set_health(u64::from(self.player_health_like_cpp));
        self.apply_represented_player_powers_to_canonical_like_cpp(&mut player);
        player.set_xp(self.player_xp_like_cpp() as i32);
        player.set_next_level_xp(self.player_next_level_xp_like_cpp() as i32);
        player.set_money(self.player_gold_like_cpp());
        player.set_bank_bag_slot_count(self.player_bank_bag_slot_count_like_cpp());
        for (category, party_type) in self
            .party_member_party_type_like_cpp()
            .into_iter()
            .enumerate()
        {
            let _ = player.set_party_type_like_cpp(category as u8, party_type);
        }
        for (index, value) in self
            .represented_bank_bag_slot_flags_like_cpp
            .iter()
            .copied()
            .enumerate()
        {
            player.set_bank_bag_slot_flag_value_like_cpp(index, value);
        }
        player.set_watched_faction_index_like_cpp(self.watched_faction_index_like_cpp);
        for quest_bit in &self.represented_quest_completed_bits_like_cpp {
            player.set_quest_completed_bit_like_cpp(*quest_bit, true);
        }
        player.set_explored_zones_blocks_like_cpp(&self.represented_explored_zones_like_cpp);
        player.set_game_master_like_cpp(self.player_game_master_like_cpp);
        player
            .unit_mut()
            .set_base_attack_time_like_cpp(WeaponAttackType::BaseAttack, 2_000);
        player
            .unit_mut()
            .set_unit_flags_like_cpp(self.player_unit_flags_like_cpp);
        if let Some(selection) = self.selection_guid_like_cpp() {
            player.set_selection(selection);
        }
        self.apply_represented_player_unit_shape_to_canonical_like_cpp(&mut player);
        Some(player)
    }

    fn apply_represented_player_powers_to_canonical_like_cpp(&self, player: &mut Player) {
        let Some(current) = self.represented_player_powers_like_cpp[0] else {
            return;
        };
        let primary_power_type =
            primary_power_type_for_player_class_like_cpp(self.player_class_like_cpp());
        for raw_power in 0..=25 {
            player.set_power_index(power_type_from_u8_like_cpp(raw_power), None);
        }
        player.set_power_index(primary_power_type, Some(0));
        player.unit_mut().set_display_power(primary_power_type);
        player
            .unit_mut()
            .set_create_mana_like_cpp(self.represented_player_base_mana_like_cpp.max(0));
        if let Some(max) = self.represented_player_max_powers_like_cpp[0] {
            player.unit_mut().set_max_power(primary_power_type, max);
            player.unit_mut().set_power(primary_power_type, current);
        }
    }

    fn apply_represented_player_unit_shape_to_canonical_like_cpp(&self, player: &mut Player) {
        let display_id = crate::handlers::character::default_display_id(
            self.player_race_like_cpp(),
            self.player_gender_like_cpp(),
        );
        let mount_display_id = u32::try_from(self.player_mount_display_id_like_cpp).unwrap_or(0);
        let unit = player.unit_mut();
        unit.set_display_id(display_id, true);
        unit.set_mount_display_id(mount_display_id);
        unit.set_collision_height_like_cpp(self.player_collision_height_like_cpp);
        unit.world_mut()
            .object_mut()
            .set_scale(self.player_object_scale_like_cpp);
    }

    fn player_session_never_visible_for_seer_like_cpp(&self, guid: ObjectGuid) -> bool {
        self.player_logout_like_cpp || self.player_loading == Some(guid)
    }

    fn player_can_never_see_target_like_cpp(&self) -> bool {
        self.active_player_local_flags_like_cpp
            & PLAYER_LOCAL_FLAG_OVERRIDE_TRANSPORT_SERVER_TIME_LIKE_CPP
            == 0
    }

    fn apply_player_session_visibility_detection_like_cpp(
        player: &mut Player,
        never_visible_for_seer: bool,
        seer_can_never_see_target: bool,
    ) {
        player
            .unit_mut()
            .set_never_visible_for_seer_like_cpp(never_visible_for_seer);
        player
            .unit_mut()
            .set_seer_can_never_see_target_like_cpp(seer_can_never_see_target);
    }

    pub(crate) fn sync_current_player_session_visibility_detection_like_cpp(&mut self) {
        let Some(guid) = self.player_guid() else {
            return;
        };
        let never_visible_for_seer = self.player_session_never_visible_for_seer_like_cpp(guid);
        let seer_can_never_see_target = self.player_can_never_see_target_like_cpp();
        let _ = self.mutate_canonical_player_by_guid_like_cpp(guid, |player| {
            Self::apply_player_session_visibility_detection_like_cpp(
                player,
                never_visible_for_seer,
                seer_can_never_see_target,
            );
        });
    }

    pub(crate) fn current_player_save_to_db_snapshot_like_cpp(
        &self,
    ) -> Option<PlayerSaveToDbSnapshotLikeCpp> {
        let guid = self.player_guid()?;
        let pending_teleport_destination = self.pending_teleport_save_destination_like_cpp();
        if let Some(manager) = self.canonical_map_manager.as_ref()
            && let Ok(manager) = manager.lock()
        {
            let mut snapshot = None;
            manager.do_for_all_maps(|managed| {
                if snapshot.is_some() {
                    return;
                }
                let Some(player) = managed.map().get_typed_player(guid) else {
                    return;
                };
                // C++ has one live Player object, and Player::SaveToDB reads a
                // coherent snapshot from that object. Rust still has split
                // session/canonical state: accepted client movement updates the
                // session immediately, while gameplay fields may be fresher on
                // the canonical typed Player. Keep canonical gameplay fields,
                // but prefer the latest accepted session map/position for
                // logout/disconnect persistence.
                let (map_id, instance_id, position) =
                    if let Some((map_id, position)) = pending_teleport_destination {
                        (map_id, 0, position)
                    } else {
                        (
                            self.player_map_id_like_cpp(),
                            managed.instance_id(),
                            self.player_position_like_cpp()
                                .unwrap_or_else(|| player.unit().world().position()),
                        )
                    };

                let mut powers = self.represented_player_powers_like_cpp;
                let primary_power_type =
                    primary_power_type_for_player_class_like_cpp(self.player_class_like_cpp());
                if let Some(primary_slot) = player.unit().get_power_index(primary_power_type)
                    && primary_slot < MAX_POWERS_PER_CLASS
                {
                    powers[primary_slot] = Some(player.unit().get_power(primary_power_type).max(0));
                }

                let canonical_max_health = player
                    .unit()
                    .data()
                    .max_health
                    .max(1)
                    .min(u64::from(u32::MAX)) as u32;
                let canonical_health = player.unit().data().health.min(u64::from(u32::MAX)) as u32;
                let health = if !self.player_alive_like_cpp || self.player_health_like_cpp == 0 {
                    0
                } else {
                    canonical_health
                };

                snapshot = Some(PlayerSaveToDbSnapshotLikeCpp {
                    guid,
                    map_id,
                    instance_id,
                    position,
                    level: self.player_level_like_cpp(),
                    xp: self.player_xp_like_cpp(),
                    money: self.player_gold_like_cpp(),
                    health,
                    max_health: canonical_max_health,
                    powers,
                });
            });
            if snapshot.is_some() {
                return snapshot;
            }
        }

        let (map_id, instance_id, position) =
            if let Some((map_id, position)) = pending_teleport_destination {
                (map_id, 0, position)
            } else {
                (
                    self.player_map_id_like_cpp(),
                    self.current_canonical_player_map_key_like_cpp()
                        .map(|key| key.instance_id)
                        .unwrap_or(0),
                    self.player_position_like_cpp()?,
                )
            };

        Some(PlayerSaveToDbSnapshotLikeCpp {
            guid,
            map_id,
            instance_id,
            position,
            level: self.player_level_like_cpp(),
            xp: self.player_xp_like_cpp(),
            money: self.player_gold_like_cpp(),
            health: self.player_health_like_cpp,
            max_health: self.player_max_health_like_cpp.max(1),
            powers: self.represented_player_powers_like_cpp,
        })
    }

    fn pending_teleport_save_destination_like_cpp(&self) -> Option<(u16, Position)> {
        if let Some((map_id, position)) = self.pending_teleport {
            return Some((u16::try_from(map_id).unwrap_or(u16::MAX), position));
        }
        if self.near_teleport_pending_like_cpp {
            return self.near_teleport_destination_like_cpp;
        }
        None
    }

    pub(crate) fn sync_session_from_save_to_db_snapshot_like_cpp(
        &mut self,
    ) -> Option<PlayerSaveToDbSnapshotLikeCpp> {
        let snapshot = self.current_player_save_to_db_snapshot_like_cpp()?;
        self.set_player_map_position_like_cpp(snapshot.map_id, snapshot.position);
        self.set_player_level_like_cpp(snapshot.level);
        self.set_player_xp_like_cpp(snapshot.xp);
        self.set_player_gold_like_cpp(snapshot.money);
        self.set_player_health_like_cpp(snapshot.health, snapshot.max_health);
        self.represented_player_powers_like_cpp = snapshot.powers;
        Some(snapshot)
    }

    fn sync_canonical_player_entity_like_cpp(
        &self,
        managed: &mut wow_map::ManagedMap,
        mut player: Player,
    ) {
        let guid = player.guid();
        let never_visible_for_seer = self.player_session_never_visible_for_seer_like_cpp(guid);
        let seer_can_never_see_target = self.player_can_never_see_target_like_cpp();
        Self::apply_player_session_visibility_detection_like_cpp(
            &mut player,
            never_visible_for_seer,
            seer_can_never_see_target,
        );
        let map = managed.map_mut();
        if let Some(existing) = map.get_typed_player_mut(guid) {
            let attacking = existing.unit().attacking();
            let target = existing.unit().data().target;
            let unit_state = existing.unit().unit_state();
            let pvp_flags = existing.unit().pvp_flags_like_cpp();
            let player_flags = existing.data().player_flags;
            let player_flags_ex = existing.data().player_flags_ex;
            let farsight_object = existing.active_data().farsight_object;
            let duel = existing.duel_info_like_cpp();
            let gameplay_state = existing.gameplay_state().clone();
            let visibility_detection = existing.unit().visibility_detection_like_cpp().clone();
            let forced_reaction_faction_ids =
                existing.forced_reputation_faction_ids_like_cpp().clone();
            player.replace_all_player_flags(player_flags);
            player.replace_all_player_flags_ex(player_flags_ex);
            player.set_duel_info_like_cpp(duel);
            *player.gameplay_state_mut() = gameplay_state;
            player.replace_forced_reputation_faction_ids_like_cpp(forced_reaction_faction_ids);
            *existing = player;
            existing.unit_mut().set_attacking(attacking);
            existing.unit_mut().set_target(target);
            existing.unit_mut().add_unit_state(unit_state);
            existing
                .unit_mut()
                .replace_all_pvp_flags_like_cpp(pvp_flags);
            existing
                .unit_mut()
                .replace_visibility_detection_like_cpp(visibility_detection);
            existing.set_farsight_object_like_cpp(farsight_object);
            Self::apply_player_session_visibility_detection_like_cpp(
                existing,
                never_visible_for_seer,
                seer_can_never_see_target,
            );
            return;
        }

        let Ok(record) = wow_entities::MapObjectRecord::new_player(player) else {
            return;
        };
        let _ = map.insert_map_object_record(record);
    }

    fn sync_canonical_player_entity_for_map_like_cpp(
        &self,
        manager: &mut wow_map::MapManager,
        key: wow_map::MapKey,
        player: Player,
    ) {
        let guid = player.guid();
        manager.do_for_all_maps_mut(|managed| {
            if managed.map_id() == key.map_id && managed.instance_id() == key.instance_id {
                return;
            }

            match managed.map_mut().remove_from_map_like_cpp(guid, false) {
                Ok(_) | Err(wow_map::RemoveFromMapError::ObjectNotFound { .. }) => {}
                Err(_) => {}
            }
        });

        if let Some(managed) = manager.find_map_mut(key.map_id, key.instance_id) {
            self.sync_canonical_player_entity_like_cpp(managed, player);
        }
    }

    fn remove_current_player_from_canonical_current_map_like_cpp(&mut self) -> bool {
        let Some(guid) = self.player_guid() else {
            return false;
        };
        let Some(manager) = self.canonical_map_manager.as_ref().map(Arc::clone) else {
            return false;
        };
        let Ok(mut manager) = manager.lock() else {
            return false;
        };
        let map_id = u32::from(self.player_map_id_like_cpp());
        let mut removed = false;
        manager.do_for_all_maps_mut(|managed| {
            if managed.map_id() != map_id {
                return;
            }
            match managed.map_mut().remove_from_map_like_cpp(guid, false) {
                Ok(_) => removed = true,
                Err(wow_map::RemoveFromMapError::ObjectNotFound { .. }) => {}
                Err(_) => {}
            }
        });
        removed
    }

    pub(crate) fn mutate_canonical_player_like_cpp<R>(
        &mut self,
        f: impl FnOnce(&mut Player) -> R,
    ) -> Option<R> {
        let guid = self.player_guid()?;
        self.mutate_canonical_player_by_guid_like_cpp(guid, f)
    }

    pub(crate) fn sync_canonical_player_primary_power_like_cpp(
        &mut self,
        power_type: PowerType,
        current: i32,
        max: i32,
        base_mana: i32,
    ) -> bool {
        let synced = self
            .mutate_canonical_player_like_cpp(|player| {
                for raw_power in 0..=25 {
                    player.set_power_index(power_type_from_u8_like_cpp(raw_power), None);
                }
                player.set_power_index(power_type, Some(0));
                player.unit_mut().set_display_power(power_type);
                player.unit_mut().set_create_mana_like_cpp(base_mana.max(0));
                player.unit_mut().set_max_power(power_type, max.max(0));
                player.unit_mut().set_power(power_type, current.max(0));
            })
            .is_some();
        if synced {
            self.represented_player_base_mana_like_cpp = base_mana.max(0);
            self.set_represented_player_power_slot_like_cpp(0, current, Some(max));
        }
        synced
    }

    pub(crate) fn sync_canonical_player_primary_power_max_like_cpp(
        &mut self,
        power_type: PowerType,
        max: i32,
        base_mana: i32,
    ) -> Option<(i32, i32)> {
        let result = self.mutate_canonical_player_like_cpp(|player| {
            if player.unit().get_power_index(power_type).is_none() {
                player.set_power_index(power_type, Some(0));
            }
            player.unit_mut().set_display_power(power_type);
            player.unit_mut().set_create_mana_like_cpp(base_mana.max(0));
            // C++ `Unit::SetMaxPower` updates max and clamps current if needed.
            player.unit_mut().set_max_power(power_type, max.max(0));
            (
                player.unit().get_power(power_type),
                player.unit().get_max_power(power_type),
            )
        });
        if let Some((current, max)) = result {
            self.represented_player_base_mana_like_cpp = base_mana.max(0);
            self.set_represented_player_power_slot_like_cpp(0, current, Some(max));
        }
        result
    }

    pub(crate) fn sync_canonical_player_max_health_like_cpp(
        &mut self,
        max_health: u32,
    ) -> Option<(u32, u32)> {
        let max_health = max_health.max(1);
        let result = self.mutate_canonical_player_like_cpp(|player| {
            // C++ `Unit::SetMaxHealth` updates max and clamps current only if needed.
            player.unit_mut().set_max_health(u64::from(max_health));
            (
                player.unit().data().health.min(u64::from(u32::MAX)) as u32,
                player.unit().data().max_health.min(u64::from(u32::MAX)) as u32,
            )
        });
        if let Some((current, max)) = result {
            self.set_player_health_like_cpp(current, max);
        }
        result
    }

    pub(crate) fn sync_canonical_player_health_like_cpp(
        &mut self,
        health: u32,
        max_health: u32,
    ) -> Option<(u32, u32)> {
        let max_health = max_health.max(1);
        let health = health.min(max_health);
        let result = self.mutate_canonical_player_like_cpp(|player| {
            if health == 0 {
                player
                    .unit_mut()
                    .set_death_state(wow_constants::DeathState::Corpse);
            } else if matches!(
                player.unit().death_state(),
                wow_constants::DeathState::JustDied | wow_constants::DeathState::Corpse
            ) {
                player
                    .unit_mut()
                    .set_death_state(wow_constants::DeathState::Alive);
            }
            player.unit_mut().set_max_health(u64::from(max_health));
            player.unit_mut().set_health(u64::from(health));
            (
                player.unit().data().health.min(u64::from(u32::MAX)) as u32,
                player.unit().data().max_health.min(u64::from(u32::MAX)) as u32,
            )
        });
        if let Some((current, max)) = result {
            self.set_player_health_like_cpp(current, max);
        } else {
            self.set_player_health_like_cpp(health, max_health);
        }
        result
    }

