    pub(crate) fn player_is_possessing_like_cpp(&self) -> bool {
        let Some(player_guid) = self.player_guid else {
            return false;
        };
        let map_id = u32::from(self.player_map_id_like_cpp());
        let Some(manager) = self.canonical_map_manager.as_ref() else {
            return false;
        };
        let Ok(manager) = manager.lock() else {
            return false;
        };

        let mut result = None;
        manager.do_for_all_maps_with_map_id(map_id, |managed| {
            if result.is_some() {
                return;
            }

            let map = managed.map();
            let Some(player) = map.get_typed_player(player_guid) else {
                return;
            };
            let Some(charmed_guid) = player.unit().subsystems().control.charmed_guid else {
                result = Some(false);
                return;
            };

            let target_possessed_by_player = map
                .get_typed_player(charmed_guid)
                .map(|target| {
                    let control = &target.unit().subsystems().control;
                    control.charmer_guid == Some(player_guid) && control.is_possessed()
                })
                .or_else(|| {
                    map.get_typed_creature(charmed_guid).map(|target| {
                        let control = &target.unit().subsystems().control;
                        control.charmer_guid == Some(player_guid) && control.is_possessed()
                    })
                })
                .unwrap_or(false);

            result = Some(target_possessed_by_player);
        });

        result.unwrap_or(false)
    }

    pub(crate) fn represented_player_charmed_guid_like_cpp(&self) -> ObjectGuid {
        let Some(player_guid) = self.player_guid else {
            return ObjectGuid::EMPTY;
        };
        let map_id = u32::from(self.player_map_id_like_cpp());
        let Some(manager) = self.canonical_map_manager.as_ref() else {
            return ObjectGuid::EMPTY;
        };
        let Ok(manager) = manager.lock() else {
            return ObjectGuid::EMPTY;
        };

        let mut result = None;
        manager.do_for_all_maps_with_map_id(map_id, |managed| {
            if result.is_some() {
                return;
            }

            let Some(player) = managed.map().get_typed_player(player_guid) else {
                return;
            };
            result = Some(
                player
                    .unit()
                    .subsystems()
                    .control
                    .charmed_guid
                    .unwrap_or(ObjectGuid::EMPTY),
            );
        });

        result.unwrap_or(ObjectGuid::EMPTY)
    }

    pub(crate) fn represented_move_dismiss_vehicle_like_cpp(
        &mut self,
        status: &mut wow_packet::packets::movement::MovementInfo,
    ) -> bool {
        let vehicle_guid = self.represented_player_charmed_guid_like_cpp();
        if vehicle_guid.is_empty() {
            return false;
        }

        self.sanitize_movement_info_represented_like_cpp(status);
        self.set_player_movement_time_like_cpp(status.time);
        self.set_player_movement_flags_like_cpp(status.flags);
        self.set_player_position_like_cpp(status.position);
        self.update_registry_position();
        self.represented_vehicle_dismiss_movements_like_cpp.push(
            RepresentedVehicleDismissMovementLikeCpp {
                vehicle_guid,
                sanitized_flags: status.flags,
                position: status.position,
                time: status.time,
            },
        );

        self.player_vehicle_seat_flags_like_cpp = None;
        self.player_vehicle_seat_id_like_cpp = None;
        self.sync_player_registry_state_like_cpp();
        true
    }

    fn attack_reputation_faction_snapshot_like_cpp(
        &self,
        creature: &wow_entities::Creature,
    ) -> Option<AttackReputationFactionSnapshotLikeCpp> {
        let faction_template_id = u32::try_from(creature.unit().data().faction_template).ok()?;
        self.faction_template_store
            .as_ref()
            .and_then(|store| store.get(faction_template_id))
            .map(|entry| {
                let faction_id = u32::from(entry.faction);
                AttackReputationFactionSnapshotLikeCpp {
                    faction_id,
                    contested_guard: entry.is_contested_guard_faction_like_cpp(),
                    can_have_reputation: self.faction_store.as_ref().and_then(|store| {
                        store
                            .get(faction_id)
                            .map(|faction| faction.can_have_reputation_like_cpp())
                    }),
                }
            })
            .or_else(|| {
                creature
                    .attack_reputation_faction_id_like_cpp()
                    .map(|faction_id| AttackReputationFactionSnapshotLikeCpp {
                        faction_id,
                        contested_guard: creature.is_contested_guard_like_cpp(),
                        can_have_reputation: None,
                    })
            })
    }

    pub(crate) fn creature_faction_template_is_neutral_to_all_like_cpp(
        &self,
        faction_template_id: u32,
    ) -> bool {
        let Some(faction_template_store) = self.faction_template_store.as_ref() else {
            // Transitional compatibility for legacy DB-only creature loading.
            // C++ uses FactionTemplate.db2; when the store is absent, keep the
            // previous Rust no-aggro behavior for the canonical neutral faction.
            return faction_template_id == 35;
        };
        let Some(faction_template) = faction_template_store.get(faction_template_id) else {
            return false;
        };

        if faction_template.faction == 0 {
            return true;
        }

        if let Some(faction_store) = self.faction_store.as_ref()
            && let Some(raw_faction) = faction_store.get(u32::from(faction_template.faction))
            && raw_faction.can_have_reputation_like_cpp()
        {
            return false;
        }

        faction_template.is_neutral_to_all_like_cpp()
    }

    pub(crate) fn creature_aggro_radius_for_faction_template_like_cpp(
        &self,
        faction_template_id: u32,
        default_radius: f32,
    ) -> f32 {
        if self.creature_faction_template_is_neutral_to_all_like_cpp(faction_template_id) {
            0.0
        } else {
            default_radius
        }
    }

    fn is_within_melee_range_like_cpp(
        attacker_position: Position,
        attacker_combat_reach: f32,
        target_position: Position,
        target_combat_reach: f32,
    ) -> bool {
        let melee_range =
            (attacker_combat_reach.max(0.0) + target_combat_reach.max(0.0) + 4.0 / 3.0)
                .max(NOMINAL_MELEE_RANGE_LIKE_CPP);
        attacker_position.distance(&target_position) <= melee_range
    }

    fn is_within_target_boundary_radius_like_cpp(
        attacker_position: Position,
        attacker_combat_reach: f32,
        target_position: Position,
        target_combat_reach: f32,
        target_bounding_radius: f32,
    ) -> bool {
        let boundary_radius = target_bounding_radius.max(MIN_MELEE_REACH_LIKE_CPP)
            + attacker_combat_reach.max(0.0)
            + target_combat_reach.max(0.0);
        attacker_position.distance(&target_position) < boundary_radius
    }

    fn is_unit_facing_target_for_melee_like_cpp(
        unit_position: Position,
        target_position: Position,
    ) -> bool {
        let dx = target_position.x - unit_position.x;
        let dy = target_position.y - unit_position.y;
        if dx.abs() <= f32::EPSILON && dy.abs() <= f32::EPSILON {
            return true;
        }

        let target_angle = dy.atan2(dx);
        let mut diff = (target_angle - unit_position.orientation).rem_euclid(std::f32::consts::TAU);
        if diff > std::f32::consts::PI {
            diff = std::f32::consts::TAU - diff;
        }
        diff <= std::f32::consts::PI / 3.0
    }

    fn set_player_attack_swing_error_like_cpp(&mut self, error: Option<u8>) {
        use wow_packet::ServerPacket;
        use wow_packet::packets::combat::AttackSwingError;

        if let Some(reason) = error {
            if self.player_swing_error_msg_like_cpp != Some(reason) {
                let _ = self.send_tx.send(AttackSwingError { reason }.to_bytes());
            }
        }
        self.player_swing_error_msg_like_cpp = error;
    }

    fn take_canonical_player_attack_swings_like_cpp(
        &mut self,
        diff_ms: u32,
        in_melee_range: bool,
        facing_target: bool,
        within_los: bool,
    ) -> Option<(Vec<u32>, Option<Option<u8>>)> {
        self.mutate_canonical_player_like_cpp(|player| {
            let unit = player.unit_mut();
            let spell_pauses_combat_timer = [
                wow_entities::CurrentSpellSlot::Generic,
                wow_entities::CurrentSpellSlot::Channeled,
            ]
            .into_iter()
            .any(|slot| {
                unit.current_spell(slot)
                    .is_some_and(|spell| spell.delay_combat_timer_during_cast)
            });
            if !spell_pauses_combat_timer {
                unit.update_attack_timers_like_cpp(diff_ms);
            }
            let mut swings = Vec::new();
            let mut processed_ready_attack = false;
            let mut base_attack_error_update = None;
            // C++: Unit::DoMeleeAttackIfReady, Unit.cpp:2087 exits before
            // processing swings unless UNIT_STATE_MELEE_ATTACKING is present.
            if !unit.has_unit_state(UnitState::MELEE_ATTACKING.bits()) {
                return None;
            }
            // C++: Unit::DoMeleeAttackIfReady, Unit.cpp:2090 exits while charging.
            if unit.has_unit_state(UnitState::CHARGING.bits()) {
                return None;
            }
            // C++: Unit::DoMeleeAttackIfReady returns while casting unless
            // the active channeled spell explicitly allows actions.
            if unit.has_unit_state(UnitState::CASTING.bits()) {
                let channeled = unit.current_spell(wow_entities::CurrentSpellSlot::Channeled);
                if !channeled.is_some_and(|spell| spell.allow_actions_during_channel) {
                    return None;
                }
            }
            let has_auto_attack_error = !in_melee_range || !facing_target;
            let melee_state_update_allowed =
                within_los && unit.can_attacker_state_update_melee_like_cpp(false);

            if unit.is_attack_ready_like_cpp(WeaponAttackType::BaseAttack) {
                processed_ready_attack = true;
                if has_auto_attack_error {
                    base_attack_error_update = Some(Some(if !in_melee_range { 0 } else { 1 }));
                    unit.set_attack_timer(WeaponAttackType::BaseAttack, 100);
                } else {
                    base_attack_error_update = Some(None);
                    if unit.can_dual_wield_like_cpp()
                        && unit.attack_timer(WeaponAttackType::OffAttack)
                            < ATTACK_DISPLAY_DELAY_LIKE_CPP_MS
                    {
                        unit.set_attack_timer(
                            WeaponAttackType::OffAttack,
                            ATTACK_DISPLAY_DELAY_LIKE_CPP_MS,
                        );
                    }
                    if melee_state_update_allowed {
                        unit.remove_attacking_interrupt_auras_like_cpp();
                        if unit
                            .current_spell(wow_entities::CurrentSpellSlot::Melee)
                            .is_some()
                        {
                            let _ = unit.finish_spell(wow_entities::CurrentSpellSlot::Melee);
                        } else {
                            let [min_damage, max_damage] =
                                unit.weapon_damage(WeaponAttackType::BaseAttack);
                            swings
                                .push(min_damage.max(1.0).min(max_damage.max(1.0)).round() as u32);
                        }
                    }
                    unit.reset_attack_timer_like_cpp(WeaponAttackType::BaseAttack);
                }
            }

            if unit.can_dual_wield_like_cpp()
                && unit.is_attack_ready_like_cpp(WeaponAttackType::OffAttack)
            {
                processed_ready_attack = true;
                if has_auto_attack_error {
                    unit.set_attack_timer(WeaponAttackType::OffAttack, 100);
                } else {
                    if unit.attack_timer(WeaponAttackType::BaseAttack)
                        < ATTACK_DISPLAY_DELAY_LIKE_CPP_MS
                    {
                        unit.set_attack_timer(
                            WeaponAttackType::BaseAttack,
                            ATTACK_DISPLAY_DELAY_LIKE_CPP_MS,
                        );
                    }
                    if melee_state_update_allowed {
                        unit.remove_attacking_interrupt_auras_like_cpp();
                        let [min_damage, max_damage] =
                            unit.weapon_damage(WeaponAttackType::OffAttack);
                        swings.push(min_damage.max(1.0).min(max_damage.max(1.0)).round() as u32);
                    }
                    unit.reset_attack_timer_like_cpp(WeaponAttackType::OffAttack);
                }
            }

            processed_ready_attack.then_some((swings, base_attack_error_update))
        })
        .flatten()
    }

    pub(crate) fn mutate_canonical_creature_by_guid_like_cpp<R>(
        &mut self,
        guid: ObjectGuid,
        f: impl FnOnce(&mut wow_entities::Creature) -> R,
    ) -> Option<R> {
        let map_id = u32::from(self.player_map_id_like_cpp());
        let manager = Arc::clone(self.canonical_map_manager.as_ref()?);
        let mut manager = manager.lock().ok()?;
        let managed = manager.find_map_mut(map_id, 0)?;
        let creature = managed.map_mut().get_typed_creature_mut(guid)?;
        Some(f(creature))
    }

    pub(crate) fn mutate_canonical_gameobject_by_guid_like_cpp<R>(
        &mut self,
        guid: ObjectGuid,
        f: impl FnOnce(&mut wow_entities::GameObject) -> R,
    ) -> Option<R> {
        let map_id = u32::from(self.player_map_id_like_cpp());
        let manager = Arc::clone(self.canonical_map_manager.as_ref()?);
        let mut manager = manager.lock().ok()?;
        let managed = manager.find_map_mut(map_id, 0)?;
        let gameobject = managed.map_mut().get_typed_game_object_mut(guid)?;
        Some(f(gameobject))
    }

    pub(crate) fn canonical_gameobject_linked_trap_guid_like_cpp(
        &self,
        guid: ObjectGuid,
    ) -> Option<ObjectGuid> {
        if guid.is_empty() || !guid.is_game_object() {
            return None;
        }
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = manager.find_map(u32::from(self.player_map_id_like_cpp()), 0)?;
        let gameobject = map.map().get_typed_game_object(guid)?;
        let linked_trap_guid = gameobject.linked_trap_guid_like_cpp();
        (!linked_trap_guid.is_empty()).then_some(linked_trap_guid)
    }

    pub(crate) fn canonical_gameobject_is_fully_looted_like_cpp(
        &mut self,
        guid: ObjectGuid,
    ) -> Option<bool> {
        self.mutate_canonical_gameobject_by_guid_like_cpp(guid, |gameobject| {
            gameobject.is_fully_looted_like_cpp()
        })
    }

    pub(crate) fn set_canonical_gameobject_loot_state_like_cpp(
        &mut self,
        guid: ObjectGuid,
        state: wow_entities::LootState,
        unit_guid: Option<ObjectGuid>,
        chest_restock_time_secs: u32,
        shared_loot_is_changed_like_cpp: bool,
    ) -> Option<wow_map::map::GameObjectSetLootStateOutcomeLikeCpp> {
        let map_id = u32::from(self.player_map_id_like_cpp());
        let game_time_secs = i64::try_from(wow_core::GameTime::now().as_secs()).unwrap_or(i64::MAX);
        let manager = Arc::clone(self.canonical_map_manager.as_ref()?);
        let mut manager = manager.lock().ok()?;
        let managed = manager.find_map_mut(map_id, 0)?;
        Some(managed.map_mut().set_gameobject_loot_state_like_cpp(
            guid,
            state,
            unit_guid,
            game_time_secs,
            chest_restock_time_secs,
            shared_loot_is_changed_like_cpp,
        ))
    }

    pub(crate) fn add_use_and_get_canonical_gameobject_use_count_like_cpp(
        &mut self,
        guid: ObjectGuid,
    ) -> Option<u32> {
        self.mutate_canonical_gameobject_by_guid_like_cpp(guid, |gameobject| {
            gameobject.add_use_like_cpp();
            gameobject.use_times()
        })
    }

    fn object_id_visibility_conditions_met_like_cpp(
        &self,
        target: &WorldObject,
        seer: &WorldObject,
    ) -> bool {
        let Some(condition_store) = self.condition_store.as_ref() else {
            return true;
        };

        let area_table_store = self.area_table_store.as_ref().map(Arc::clone);
        crate::conditions::is_object_meeting_visibility_by_object_id_conditions_like_cpp(
            condition_store,
            target.object().type_id() as u32,
            target.object().entry(),
            Some(seer),
            |condition, source_info| {
                crate::conditions::condition_meets_basic_like_cpp(
                    condition,
                    source_info,
                    |area_id, required_area_id| {
                        area_table_store.as_ref().is_some_and(|store| {
                            store.is_in_area_like_cpp(area_id, required_area_id)
                        })
                    },
                )
                .value()
                .unwrap_or(false)
            },
        )
    }

    fn current_player_is_in_group_guid_like_cpp(&self, group_owner: ObjectGuid) -> bool {
        let Some(group_guid) = self.group_guid else {
            return false;
        };
        if ObjectGuid::create_group(group_guid) != group_owner {
            return false;
        }
        let Some(group_registry) = self.group_registry.as_ref() else {
            return false;
        };
        let Some(player_guid) = self.player_guid() else {
            return false;
        };
        group_registry
            .get(&group_guid)
            .is_some_and(|group| group.members.contains(&player_guid))
    }

    fn current_player_is_group_visible_for_owner_like_cpp(&self, owner_guid: ObjectGuid) -> bool {
        let (Some(group_guid), Some(group_registry), Some(player_guid)) = (
            self.group_guid,
            self.group_registry.as_ref(),
            self.player_guid(),
        ) else {
            return false;
        };
        group_registry.get(&group_guid).is_some_and(|group| {
            group.members.contains(&player_guid) && group.members.contains(&owner_guid)
        })
    }

    fn current_player_is_in_raid_group_like_cpp(&self) -> bool {
        let (Some(group_guid), Some(group_registry), Some(player_guid)) = (
            self.group_guid,
            self.group_registry.as_ref(),
            self.player_guid(),
        ) else {
            return false;
        };

        group_registry
            .get(&group_guid)
            .is_some_and(|group| group.is_raid_group() && group.members.contains(&player_guid))
    }

    fn represented_player_is_same_raid_with_like_cpp(
        &self,
        player_guid: ObjectGuid,
        owner_guid: ObjectGuid,
    ) -> bool {
        let (Some(group_guid), Some(group_registry)) =
            (self.group_guid, self.group_registry.as_ref())
        else {
            return false;
        };
        group_registry.get(&group_guid).is_some_and(|group| {
            group.members.contains(&player_guid) && group.members.contains(&owner_guid)
        })
    }

    fn current_group_member_guids_for_tap_like_cpp(
        &self,
        player_guid: ObjectGuid,
    ) -> Vec<ObjectGuid> {
        let (Some(group_guid), Some(group_registry)) =
            (self.group_guid, self.group_registry.as_ref())
        else {
            return Vec::new();
        };
        group_registry
            .get(&group_guid)
            .map(|group| {
                group
                    .members
                    .iter()
                    .copied()
                    .filter(|member| *member != player_guid)
                    .collect()
            })
            .unwrap_or_default()
    }

    pub fn summon_private_object_owner_like_cpp(
        &self,
        caster_guid: ObjectGuid,
        caster_private_object_owner: ObjectGuid,
        properties: &SummonPropertiesEntry,
    ) -> ObjectGuid {
        let flags = u32::try_from(properties.flags[0]).unwrap_or(0);
        let only_visible_to_summoner =
            flags & SUMMON_PROPERTIES_ONLY_VISIBLE_TO_SUMMONER_LIKE_CPP != 0;
        let only_visible_to_summoner_group =
            flags & SUMMON_PROPERTIES_ONLY_VISIBLE_TO_SUMMONER_GROUP_LIKE_CPP != 0;
        if !only_visible_to_summoner && !only_visible_to_summoner_group {
            return ObjectGuid::EMPTY;
        }

        if !caster_private_object_owner.is_empty() {
            return caster_private_object_owner;
        }

        if only_visible_to_summoner_group && caster_guid.is_player() {
            if let Some(group_guid) = self.group_guid {
                return ObjectGuid::create_group(group_guid);
            }
        }

        caster_guid
    }

    pub fn set_canonical_creature_private_object_owner_like_cpp(
        &mut self,
        guid: ObjectGuid,
        owner: ObjectGuid,
    ) -> bool {
        let mut updated = self
            .mutate_canonical_creature_by_guid_like_cpp(guid, |creature| {
                creature.unit_mut().set_private_object_owner_like_cpp(owner);
            })
            .is_some();

        if let Some(manager) = self.map_manager.as_ref() {
            let mut manager = manager
                .write()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            if let Some(creature) =
                manager.find_creature_mut(self.player_map_id_like_cpp(), 0, guid)
            {
                creature
                    .creature
                    .unit_mut()
                    .set_private_object_owner_like_cpp(owner);
                updated = true;
            }
        }

        updated
    }

    fn apply_target_visibility_context_for_current_player_like_cpp(
        &self,
        target_unit: &mut wow_entities::Unit,
        seer_unit: &mut wow_entities::Unit,
    ) {
        target_unit.set_object_id_visibility_conditions_met_like_cpp(
            self.object_id_visibility_conditions_met_like_cpp(
                target_unit.world(),
                seer_unit.world(),
            ),
        );

        let target_guid = target_unit.world().object().guid();
        let moved_unit_guid = self.player_moved_unit_guid_like_cpp();
        if !moved_unit_guid.is_empty() && moved_unit_guid == target_guid {
            seer_unit.set_seer_can_always_see_target_like_cpp(true);
        }

        let private_owner = target_unit.private_object_owner_like_cpp();
        if !private_owner.is_empty() {
            seer_unit.set_seer_group_visible_for_private_owner_like_cpp(
                self.current_player_is_in_group_guid_like_cpp(private_owner),
            );
        }

        let owner_group_visible = target_unit
            .subsystems()
            .control
            .charmer_or_owner_guid()
            .is_some_and(|owner_guid| {
                self.current_player_is_group_visible_for_owner_like_cpp(owner_guid)
            });
        target_unit.set_target_owner_group_visible_for_seer_like_cpp(owner_group_visible);
    }

    fn canonical_unit_attack_target_state_like_cpp(
        &self,
        guid: ObjectGuid,
    ) -> (bool, bool, wow_entities::UnitAttackContextLikeCpp) {
        let Some(manager) = self.canonical_map_manager.as_ref() else {
            return (
                true,
                true,
                wow_entities::UnitAttackContextLikeCpp::default(),
            );
        };
        let Ok(manager) = manager.lock() else {
            return (
                true,
                true,
                wow_entities::UnitAttackContextLikeCpp::default(),
            );
        };
        let Some(map) = manager.find_map(u32::from(self.player_map_id_like_cpp()), 0) else {
            return (
                true,
                true,
                wow_entities::UnitAttackContextLikeCpp::default(),
            );
        };
        if let Some(player) = map.map().get_typed_player(guid) {
            let pvp_flags = player.unit().pvp_flags_like_cpp();
            let attacker_can_see_or_detect_target = self
                .can_see_phase_shift_like_cpp(player.unit().world().phase_shift())
                && self
                    .player_guid()
                    .and_then(|attacker_guid| map.map().get_typed_player(attacker_guid))
                    .map(|attacker| {
                        let mut target_unit = player.unit().clone();
                        let mut seer_unit = attacker.unit().clone();
                        self.apply_target_visibility_context_for_current_player_like_cpp(
                            &mut target_unit,
                            &mut seer_unit,
                        );
                        seer_unit.can_see_or_detect_unit_like_cpp(&target_unit, false, true, false)
                    })
                    .unwrap_or(true);
            return (
                player.unit().is_alive(),
                player.unit().world().object().is_in_world(),
                wow_entities::UnitAttackContextLikeCpp {
                    victim_is_game_master_player: player.is_game_master_like_cpp(),
                    victim_unit_state: player.unit().unit_state(),
                    victim_unit_flags: player.unit().unit_flags_like_cpp().bits(),
                    victim_has_affecting_player: true,
                    visibility_represented: true,
                    attacker_can_see_or_detect_target,
                    victim_in_sanctuary: pvp_flags.contains(UnitPvpFlags::SANCTUARY),
                    victim_is_pvp: pvp_flags.contains(UnitPvpFlags::PVP),
                    victim_is_ffa_pvp: pvp_flags.contains(UnitPvpFlags::FFA_PVP),
                    victim_has_pvp_unk1_flag: pvp_flags.contains(UnitPvpFlags::UNK1),
                    ..Default::default()
                },
            );
        }
        if let Some(creature) = map.map().get_typed_creature(guid) {
            let attacker_can_see_or_detect_target = self
                .can_see_phase_shift_like_cpp(creature.unit().world().phase_shift())
                && self
                    .player_guid()
                    .and_then(|attacker_guid| map.map().get_typed_player(attacker_guid))
                    .map(|attacker| {
                        let mut target_unit = creature.unit().clone();
                        let mut seer_unit = attacker.unit().clone();
                        self.apply_target_visibility_context_for_current_player_like_cpp(
                            &mut target_unit,
                            &mut seer_unit,
                        );
                        seer_unit.can_see_or_detect_unit_like_cpp(&target_unit, false, true, false)
                    })
                    .unwrap_or(true);
            let mut context = wow_entities::UnitAttackContextLikeCpp {
                victim_is_evading_creature: creature.is_evading_attacks_like_cpp(),
                victim_unit_state: creature.unit().unit_state(),
                victim_unit_flags: creature.unit().unit_flags_like_cpp().bits(),
                visibility_represented: true,
                attacker_can_see_or_detect_target,
                ..Default::default()
            };
            if let Some(reputation_snapshot) =
                self.attack_reputation_faction_snapshot_like_cpp(creature)
                && let Some(attacker_guid) = self.player_guid()
                && let Some(attacker) = map.map().get_typed_player(attacker_guid)
            {
                let player_has_contested_pvp_flag =
                    attacker.has_player_flag(PLAYER_FLAGS_CONTESTED_PVP_LIKE_CPP);
                let creature_has_forced_reputation_rank =
                    attacker.has_forced_reputation_rank_like_cpp(reputation_snapshot.faction_id);
                let player_has_reputation_state = match reputation_snapshot.can_have_reputation {
                    Some(false) => false,
                    Some(true) => {
                        attacker.has_reputation_state_like_cpp(reputation_snapshot.faction_id)
                    }
                    None => true,
                };
                if (reputation_snapshot.contested_guard && player_has_contested_pvp_flag)
                    || creature_has_forced_reputation_rank
                    || player_has_reputation_state
                {
                    context.player_creature_reputation_represented = true;
                    context.creature_is_contested_guard = reputation_snapshot.contested_guard;
                    context.player_has_contested_pvp_flag = player_has_contested_pvp_flag;
                    context.creature_has_forced_reputation_rank =
                        creature_has_forced_reputation_rank;
                    context.player_at_war_with_creature_faction = player_has_reputation_state
                        && attacker.is_at_war_with_faction_like_cpp(reputation_snapshot.faction_id);
                }
            }
            return (
                creature.is_alive(),
                creature.unit().world().object().is_in_world(),
                context,
            );
        }
        (
            true,
            true,
            wow_entities::UnitAttackContextLikeCpp::default(),
        )
    }

    fn player_vehicle_seat_allows_attack_like_cpp(&self) -> bool {
        match self.player_vehicle_seat_flags_like_cpp {
            Some(flags) => flags & VEHICLE_SEAT_FLAG_CAN_ATTACK != 0,
            None => true,
        }
    }

    fn add_canonical_attacker_like_cpp(&mut self, victim: ObjectGuid, attacker: ObjectGuid) {
        if self
            .mutate_canonical_player_by_guid_like_cpp(victim, |victim| {
                victim.unit_mut().add_attacker_like_cpp(attacker)
            })
            .is_some()
        {
            return;
        }
        let _ = self.mutate_canonical_creature_by_guid_like_cpp(victim, |victim| {
            victim.unit_mut().add_attacker_like_cpp(attacker)
        });
    }

    fn remove_canonical_attacker_like_cpp(&mut self, victim: ObjectGuid, attacker: ObjectGuid) {
        if self
            .mutate_canonical_player_by_guid_like_cpp(victim, |victim| {
                victim.unit_mut().remove_attacker_like_cpp(attacker)
            })
            .is_some()
        {
            return;
        }
        let _ = self.mutate_canonical_creature_by_guid_like_cpp(victim, |victim| {
            victim.unit_mut().remove_attacker_like_cpp(attacker)
        });
    }

    fn begin_canonical_player_combat_ref_like_cpp(
        &mut self,
        attacker_guid: ObjectGuid,
        victim_guid: ObjectGuid,
        relation_represented: bool,
        attacker_is_friendly_to_victim: bool,
        victim_is_friendly_to_attacker: bool,
    ) -> bool {
        let Some(manager) = self.canonical_map_manager.as_ref().cloned() else {
            return false;
        };
        let Ok(mut manager) = manager.lock() else {
            return false;
        };
        let Some(managed) = manager.find_map_mut(u32::from(self.player_map_id_like_cpp()), 0)
        else {
            return false;
        };
        let map = managed.map_mut();
        let Some(attacker) = map.get_typed_player(attacker_guid) else {
            return false;
        };
        let attacker_unit = attacker.unit();
        let attacker_world = attacker_unit.world();
        let attacker_combat = &attacker_unit.subsystems().combat;

        let (context, both_player_controlled) =
            if let Some(victim) = map.get_typed_player(victim_guid) {
                let victim_unit = victim.unit();
                let victim_world = victim_unit.world();
                let victim_combat = &victim_unit.subsystems().combat;
                (
                    wow_entities::CombatBeginContextLikeCpp {
                        same_unit: attacker_guid == victim_guid,
                        attacker_in_world: attacker_world.object().is_in_world(),
                        victim_in_world: victim_world.object().is_in_world(),
                        attacker_alive: attacker_unit.is_alive(),
                        victim_alive: victim_unit.is_alive(),
                        same_map: attacker_world.is_in_map(victim_world),
                        same_phase: attacker_world.in_same_phase(victim_world),
                        attacker_unit_state: attacker_unit.unit_state(),
                        victim_unit_state: victim_unit.unit_state(),
                        attacker_combat_disallowed: attacker_combat.combat_disallowed,
                        victim_combat_disallowed: victim_combat.combat_disallowed,
                        relation_represented,
                        attacker_is_friendly_to_victim,
                        victim_is_friendly_to_attacker,
                        attacker_or_owner_player_is_game_master: attacker.is_game_master_like_cpp(),
                        victim_or_owner_player_is_game_master: victim.is_game_master_like_cpp(),
                    },
                    true,
                )
            } else if let Some(victim) = map.get_typed_creature(victim_guid) {
                let victim_unit = victim.unit();
                let victim_world = victim_unit.world();
                let victim_combat = &victim_unit.subsystems().combat;
                (
                    wow_entities::CombatBeginContextLikeCpp {
                        same_unit: false,
                        attacker_in_world: attacker_world.object().is_in_world(),
                        victim_in_world: victim_world.object().is_in_world(),
                        attacker_alive: attacker_unit.is_alive(),
                        victim_alive: victim_unit.is_alive(),
                        same_map: attacker_world.is_in_map(victim_world),
                        same_phase: attacker_world.in_same_phase(victim_world),
                        attacker_unit_state: attacker_unit.unit_state(),
                        victim_unit_state: victim_unit.unit_state(),
                        attacker_combat_disallowed: attacker_combat.combat_disallowed,
                        victim_combat_disallowed: victim_combat.combat_disallowed,
                        relation_represented,
                        attacker_is_friendly_to_victim,
                        victim_is_friendly_to_attacker,
                        attacker_or_owner_player_is_game_master: attacker.is_game_master_like_cpp(),
                        victim_or_owner_player_is_game_master: false,
                    },
                    false,
                )
            } else {
                return false;
            };

        if !wow_entities::CombatSubsystem::can_begin_combat_like_cpp(context) {
            return false;
        }

        let Some(attacker) = map.get_typed_player_mut(attacker_guid) else {
            return false;
        };
        let attacker_started = attacker
            .unit_mut()
            .subsystems_mut()
            .combat
            .set_in_combat_with(victim_guid, both_player_controlled, false);

        let victim_started = if let Some(victim) = map.get_typed_player_mut(victim_guid) {
            victim
                .unit_mut()
                .subsystems_mut()
                .combat
                .set_in_combat_with(attacker_guid, both_player_controlled, false)
        } else if let Some(victim) = map.get_typed_creature_mut(victim_guid) {
            victim
                .unit_mut()
                .subsystems_mut()
                .combat
                .set_in_combat_with(attacker_guid, both_player_controlled, false)
        } else {
            false
        };

        attacker_started && victim_started
    }

    fn canonical_creature_threat_value_like_cpp(
        &self,
        creature_guid: ObjectGuid,
        attacker_guid: ObjectGuid,
    ) -> Option<f32> {
        let manager = self.canonical_map_manager.as_ref()?.clone();
        let manager = manager.lock().ok()?;
        let managed = manager.find_map(u32::from(self.player_map_id_like_cpp()), 0)?;
        let creature = managed.map().get_typed_creature(creature_guid)?;
        creature
            .unit()
            .subsystems()
            .combat
            .threat_value(attacker_guid)
    }

    fn mirror_canonical_creature_threat_from_attacker_like_cpp(
        &mut self,
        creature_guid: ObjectGuid,
        attacker_guid: ObjectGuid,
        threat_value: f32,
    ) -> bool {
        if threat_value <= 0.0 {
            return false;
        }
        if !self.begin_canonical_player_combat_ref_like_cpp(
            attacker_guid,
            creature_guid,
            false,
            false,
            false,
        ) {
            return false;
        }

        let Some(manager) = self.canonical_map_manager.as_ref().cloned() else {
            return false;
        };
        let Ok(mut manager) = manager.lock() else {
            return false;
        };
        let Some(managed) = manager.find_map_mut(u32::from(self.player_map_id_like_cpp()), 0)
        else {
            return false;
        };
        let map = managed.map_mut();

        let threat_ref = {
            let Some(creature) = map.get_typed_creature_mut(creature_guid) else {
                return false;
            };
            creature
                .unit_mut()
                .subsystems_mut()
                .combat
                .set_threat(attacker_guid, threat_value);
            creature
                .unit()
                .subsystems()
                .combat
                .threat_ref(attacker_guid)
                .copied()
        };

        let Some(threat_ref) = threat_ref else {
            return false;
        };
        let Some(attacker) = map.get_typed_player_mut(attacker_guid) else {
            return false;
        };
        attacker
            .unit_mut()
            .subsystems_mut()
            .combat
            .put_threatened_by_me_ref(creature_guid, threat_ref);
        true
    }

    fn revalidate_canonical_player_combat_refs_like_cpp(&mut self, player_guid: ObjectGuid) {
        let Some(manager) = self.canonical_map_manager.as_ref().cloned() else {
            return;
        };
        let Ok(mut manager) = manager.lock() else {
            return;
        };
        let Some(managed) = manager.find_map_mut(u32::from(self.player_map_id_like_cpp()), 0)
        else {
            return;
        };
        if managed.map().get_typed_player(player_guid).is_some() {
            managed.map_mut().revalidate_all_combat_refs_like_cpp();
        }
    }

    pub(crate) fn start_player_attack_like_cpp(
        &mut self,
        victim: ObjectGuid,
    ) -> PlayerAttackStartLikeCppResult {
        let _ = self.ensure_canonical_world_map_for_current_player_like_cpp();
        let player_guid = self.player_guid();
        let attacker_is_mounted_player = self.player_mounted_like_cpp;
        let (victim_alive, victim_in_world, mut attack_context) =
            self.canonical_unit_attack_target_state_like_cpp(victim);
        if !self.player_vehicle_seat_allows_attack_like_cpp() {
            self.combat_target = None;
            self.in_combat = false;
            if self.selection_guid_like_cpp() == Some(victim) {
                self.set_selection_guid_like_cpp(None);
            }
            return PlayerAttackStartLikeCppResult::Rejected;
        }
        attack_context.attacker_is_mounted_player = attacker_is_mounted_player;
        attack_context.attacker_unit_flags = self.player_unit_flags_like_cpp.bits();
        attack_context.attacker_has_affecting_player = true;
        let attacker_pvp_flags = player_guid
            .and_then(|guid| self.canonical_player_pvp_flags_like_cpp(guid))
            .unwrap_or_default();
        attack_context.attacker_in_sanctuary = attacker_pvp_flags.contains(UnitPvpFlags::SANCTUARY);
        attack_context.attacker_is_ffa_pvp = attacker_pvp_flags.contains(UnitPvpFlags::FFA_PVP);
        attack_context.attacker_has_pvp_unk1_flag = attacker_pvp_flags.contains(UnitPvpFlags::UNK1);
        if attack_context.victim_has_affecting_player {
            attack_context.sanctuary_represented = true;
            attack_context.pvp_represented = true;
            attack_context.player_player_duel_in_progress = player_guid
                .and_then(|guid| self.canonical_player_duel_in_progress_like_cpp(guid, victim))
                .unwrap_or(false);
        }
        attack_context.attacker_is_player_uber = player_guid
            .and_then(|guid| {
                self.canonical_player_has_player_flag_like_cpp(guid, PLAYER_FLAGS_UBER_LIKE_CPP)
            })
            .unwrap_or(false);
        let combat_relation_represented = attack_context.relation_represented;
        let combat_attacker_is_friendly_to_victim = attack_context.attacker_is_friendly_to_victim;
        let combat_victim_is_friendly_to_attacker = attack_context.victim_is_friendly_to_attacker;
        self.combat_target = Some(victim);
        self.in_combat = true;
        self.set_selection_guid_like_cpp(Some(victim));
        let outcome = self.mutate_canonical_player_like_cpp(|player| {
            player.unit_mut().attack_with_context_like_cpp(
                victim,
                victim_alive,
                victim_in_world,
                true,
                attack_context,
            )
        });
        let previous = match outcome {
            Some(wow_entities::UnitAttackStartOutcome::NewTarget { previous }) => previous,
            Some(
                wow_entities::UnitAttackStartOutcome::MeleeStartedSameTarget
                | wow_entities::UnitAttackStartOutcome::MeleeStoppedSameTarget
                | wow_entities::UnitAttackStartOutcome::NoChangeSameTarget,
            ) => None,
            Some(
                wow_entities::UnitAttackStartOutcome::InvalidSelfTarget
                | wow_entities::UnitAttackStartOutcome::InvalidDeadAttacker
                | wow_entities::UnitAttackStartOutcome::InvalidDeadVictim
                | wow_entities::UnitAttackStartOutcome::InvalidVictimNotInWorld
                | wow_entities::UnitAttackStartOutcome::InvalidMountedAttacker
                | wow_entities::UnitAttackStartOutcome::InvalidAttackerEvading
                | wow_entities::UnitAttackStartOutcome::InvalidVictimGameMaster
                | wow_entities::UnitAttackStartOutcome::InvalidVictimEvading
                | wow_entities::UnitAttackStartOutcome::InvalidAttackTarget,
            )
            | None => {
                self.combat_target = None;
                self.in_combat = false;
                if self.selection_guid_like_cpp() == Some(victim) {
                    self.set_selection_guid_like_cpp(None);
                }
                return PlayerAttackStartLikeCppResult::Rejected;
            }
        };
        if let Some(player_guid) = player_guid {
            if let Some(previous) = previous {
                self.remove_canonical_attacker_like_cpp(previous, player_guid);
            }
            self.add_canonical_attacker_like_cpp(victim, player_guid);
            let _ = self.mutate_world_creature(victim, |victim| {
                victim
                    .creature
                    .unit_mut()
                    .add_attacker_like_cpp(player_guid);
            });
            let _ = self.begin_canonical_player_combat_ref_like_cpp(
                player_guid,
                victim,
                combat_relation_represented,
                combat_attacker_is_friendly_to_victim,
                combat_victim_is_friendly_to_attacker,
            );
        }
        let send_attack_start = matches!(
            outcome,
            Some(
                wow_entities::UnitAttackStartOutcome::NewTarget { .. }
                    | wow_entities::UnitAttackStartOutcome::MeleeStartedSameTarget
            )
        );
        PlayerAttackStartLikeCppResult::Accepted { send_attack_start }
    }

    pub(crate) fn stop_player_attack_like_cpp(&mut self) -> Option<ObjectGuid> {
        let player_guid = self.player_guid()?;
        let target = match self.mutate_canonical_player_like_cpp(|player| {
            match player.unit_mut().attack_stop_like_cpp() {
                wow_entities::UnitAttackStopOutcome::Stopped { victim } => Some(victim),
                wow_entities::UnitAttackStopOutcome::NoVictim => None,
            }
        }) {
            Some(Some(victim)) => victim,
            // C++ Unit::AttackStop returns false when m_attacking is null; a
            // stale session mirror must not invent a victim when canonical
            // player state exists and says there is none.
            Some(None) => {
                self.combat_target = None;
                self.in_combat = false;
                return None;
            }
            None => self.combat_target.take()?,
        };
        self.combat_target = None;
        self.in_combat = false;
        if self.selection_guid_like_cpp() == Some(target) {
            self.set_selection_guid_like_cpp(None);
        }
        self.remove_canonical_attacker_like_cpp(target, player_guid);
        let _ = self.mutate_world_creature(target, |victim| {
            victim
                .creature
                .unit_mut()
                .remove_attacker_like_cpp(player_guid);
        });
        Some(target)
    }

    fn combat_stop_like_cpp(&mut self) {
        let Some(player_guid) = self.player_guid() else {
            self.combat_target = None;
            self.in_combat = false;
            return;
        };

        let stopped_target = self.stop_player_attack_like_cpp();
        let owner_guids = {
            let Some(manager) = self.canonical_map_manager.as_ref().cloned() else {
                return self.finish_combat_stop_like_cpp(player_guid, stopped_target, Vec::new());
            };
            let Ok(mut manager) = manager.lock() else {
                return self.finish_combat_stop_like_cpp(player_guid, stopped_target, Vec::new());
            };
            let Some(managed) = manager.find_map_mut(u32::from(self.player_map_id_like_cpp()), 0)
            else {
                return self.finish_combat_stop_like_cpp(player_guid, stopped_target, Vec::new());
            };
            let map = managed.map_mut();
            let Some(player) = map.get_typed_player_mut(player_guid) else {
                return self.finish_combat_stop_like_cpp(player_guid, stopped_target, Vec::new());
            };

            let mut owner_guids: Vec<ObjectGuid> = player
                .unit()
                .subsystems()
                .combat
                .pve_refs
                .keys()
                .chain(player.unit().subsystems().combat.pvp_refs.keys())
                .chain(player.unit().subsystems().combat.attackers.iter())
                .copied()
                .collect();
            owner_guids.sort_unstable();
            owner_guids.dedup();

            player.unit_mut().subsystems_mut().combat.end_all_combat();
            player.unit_mut().subsystems_mut().combat.clear_attackers();

            for owner_guid in &owner_guids {
                if let Some(owner) = map.get_typed_player_mut(*owner_guid) {
                    if owner.unit().attacking() == Some(player_guid) {
                        let _ = owner.unit_mut().attack_stop_like_cpp();
                    }
                    owner
                        .unit_mut()
                        .subsystems_mut()
                        .combat
                        .purge_combat_ref_like_cpp(player_guid);
                    owner.unit_mut().remove_attacker_like_cpp(player_guid);
                } else if let Some(owner) = map.get_typed_creature_mut(*owner_guid) {
                    if owner.unit().attacking() == Some(player_guid) {
                        let _ = owner.unit_mut().attack_stop_like_cpp();
                    }
                    owner
                        .unit_mut()
                        .subsystems_mut()
                        .combat
                        .purge_combat_ref_like_cpp(player_guid);
                    owner.unit_mut().remove_attacker_like_cpp(player_guid);
                }
            }

            owner_guids
        };

        self.finish_combat_stop_like_cpp(player_guid, stopped_target, owner_guids);
    }

    fn finish_combat_stop_like_cpp(
        &mut self,
        player_guid: ObjectGuid,
        stopped_target: Option<ObjectGuid>,
        owner_guids: Vec<ObjectGuid>,
    ) {
        self.combat_target = None;
        self.in_combat = false;
        for owner_guid in owner_guids {
            let _ = self.mutate_world_creature(owner_guid, |owner| {
                if owner.creature.unit().attacking() == Some(player_guid) {
                    let _ = owner.creature.unit_mut().attack_stop_like_cpp();
                }
                owner
                    .creature
                    .unit_mut()
                    .subsystems_mut()
                    .combat
                    .purge_combat_ref_like_cpp(player_guid);
                owner
                    .creature
                    .unit_mut()
                    .subsystems_mut()
                    .combat
                    .scale_threat(player_guid, 0.0);
                owner
                    .creature
                    .unit_mut()
                    .remove_attacker_like_cpp(player_guid);
                if owner.creature.ai_ownership().combat_target == Some(player_guid) {
                    owner.creature.ai_ownership_mut().combat_target = None;
                }
            });
        }

        if let Some(target) = stopped_target {
            self.send_packet(&wow_packet::packets::combat::SAttackStop {
                attacker: player_guid,
                victim: target,
                now_dead: false,
            });
        }
        self.send_packet(&wow_packet::packets::combat::CancelCombat);
        self.sync_player_registry_state_like_cpp();
    }

    pub(crate) fn ensure_canonical_world_map_for_current_player_like_cpp(
        &mut self,
    ) -> Option<wow_map::CreateMapDecision> {
        let map_id = u32::from(self.player_map_id_like_cpp());
        let map_entry = self.map_store.as_ref()?.get(map_id).copied()?;
        if map_entry.is_battleground_or_arena() {
            return None;
        }
        // C++ `Player::LoadFromDB` rejects a saved map requiring a newer
        // client expansion before calling `MapManager::CreateMap`
        // (Player.cpp:17577-17587). The login handler observes the missing
        // canonical key and performs the same homebind recovery.
        if self.expansion < map_entry.expansion_like_cpp() {
            warn!(
                account = self.account_id,
                map_id,
                session_expansion = self.expansion,
                required_expansion = map_entry.expansion_like_cpp(),
                "Login map rejected by C++ client expansion gate"
            );
            return Some(wow_map::CreateMapDecision::Reject {
                side_effects: Vec::new(),
            });
        }

        let player_guid = self.player_guid?;
        let player = self.create_map_player_context_like_cpp(map_id, map_entry, player_guid);
        let is_dungeon = map_entry.is_dungeon();
        let requested_difficulty = player
            .group
            .map(|group| group.difficulty_id)
            .unwrap_or(player.player_difficulty_id);
        if is_dungeon
            && self
                .create_map_db2_entries_like_cpp(map_id, requested_difficulty)
                .is_none()
        {
            self.send_transfer_aborted_like_cpp(map_id, TRANSFER_ABORT_DIFFICULTY_LIKE_CPP);
            return Some(wow_map::CreateMapDecision::Reject {
                side_effects: Vec::new(),
            });
        }
        let bypass_player_cannot_enter_like_cpp =
            is_dungeon && self.player_is_game_master_like_cpp();
        if is_dungeon
            && !bypass_player_cannot_enter_like_cpp
            && let Some((transfer_abort, arg, map_difficulty_x_condition_id)) =
                self.access_requirement_abort_like_cpp(map_id, requested_difficulty as u8)
        {
            self.send_transfer_aborted_with_params_like_cpp(
                map_id,
                transfer_abort,
                arg,
                map_difficulty_x_condition_id,
            );
            return Some(wow_map::CreateMapDecision::Reject {
                side_effects: Vec::new(),
            });
        }
        if is_dungeon
            && !bypass_player_cannot_enter_like_cpp
            && map_entry.instance_type == wow_data::map::MAP_RAID
            && map_entry.expansion_like_cpp() >= self.server_expansion_like_cpp
            && !self.instance_ignore_raid_like_cpp
            && !self.current_player_is_in_raid_group_like_cpp()
        {
            self.send_transfer_aborted_like_cpp(map_id, TRANSFER_ABORT_NEED_GROUP_LIKE_CPP);
            return Some(wow_map::CreateMapDecision::Reject {
                side_effects: Vec::new(),
            });
        }
        // Login follows C++ `MapManager::CreateMap` (MapManager.cpp:139-231),
        // whose final world-map branch includes garrisons and selects only
        // instance 0 / team split. Do not use Rust's represented
        // `CreateMapEntryKind::Garrison` here: that mirrors the distinct
        // `FindInstanceIdForPlayer` branch (MapManager.cpp:247-288), which is
        // not the map-creation path called by `Player::LoadFromDB`.
        let entry = wow_map::CreateMapEntryContext {
            map_id,
            kind: if is_dungeon {
                wow_map::CreateMapEntryKind::Dungeon
            } else {
                wow_map::CreateMapEntryKind::World
            },
            split_by_faction: map_entry.is_split_by_faction(),
            flex_locking: map_entry.is_flex_locking(),
        };
        let active_instance_lock = is_dungeon
            .then(|| {
                self.create_map_active_instance_lock_context_like_cpp(map_id, requested_difficulty)
            })
            .flatten();

        let manager = Arc::clone(self.canonical_map_manager.as_ref()?);
        let mut manager = manager.lock().ok()?;
        let decision = manager.create_map_decision_like_cpp(
            Some(entry),
            Some(player),
            |map_id, difficulty_id| {
                self.create_map_difficulty_context_like_cpp(map_id, difficulty_id)
            },
            active_instance_lock,
            |_, _| None,
        );

        if let wow_map::CreateMapDecision::Create {
            key,
            difficulty_id,
            kind,
            ..
        } = &decision
        {
            let map = manager.create_map_entry(key.map_id, key.instance_id, *difficulty_id, *kind);
            if is_dungeon {
                map.set_instance_lock_context(active_instance_lock);
            }
        }

        let key = match &decision {
            wow_map::CreateMapDecision::Existing { key, .. }
            | wow_map::CreateMapDecision::Create { key, .. } => Some(*key),
            wow_map::CreateMapDecision::Reject { .. } => None,
        };
        let existing_instance_lock_context = match &decision {
            wow_map::CreateMapDecision::Existing { key, .. } if is_dungeon => manager
                .find_map(key.map_id, key.instance_id)
                .and_then(|map| map.instance_lock_context()),
            _ => None,
        };
        let existing_instance_player_count = match &decision {
            wow_map::CreateMapDecision::Existing { key, .. } if is_dungeon => manager
                .find_map(key.map_id, key.instance_id)
                .map(|map| map.players_count_except_gms_like_cpp()),
            _ => None,
        };
        let existing_instance_encounter_in_progress = match &decision {
            wow_map::CreateMapDecision::Existing { key, .. } if is_dungeon => manager
                .find_map(key.map_id, key.instance_id)
                .map(|map| map.instance_encounter_in_progress_like_cpp()),
            _ => None,
        };
        drop(manager);

        if is_dungeon
            && !bypass_player_cannot_enter_like_cpp
            && let wow_map::CreateMapDecision::Existing {
                key, difficulty_id, ..
            } = &decision
            && let Some(player_count) = existing_instance_player_count
            && let Some(entries) = self.create_map_db2_entries_like_cpp(key.map_id, *difficulty_id)
            && player_count >= entries.max_players
        {
            self.send_transfer_aborted_like_cpp(key.map_id, TRANSFER_ABORT_MAX_PLAYERS_LIKE_CPP);
            return Some(wow_map::CreateMapDecision::Reject {
                side_effects: Vec::new(),
            });
        }

        if is_dungeon
            && !bypass_player_cannot_enter_like_cpp
            && map_entry.instance_type == wow_data::map::MAP_RAID
            && self.player_loading() != Some(player_guid)
            && let wow_map::CreateMapDecision::Existing { key, .. } = &decision
            && existing_instance_encounter_in_progress == Some(true)
        {
            self.send_transfer_aborted_like_cpp(key.map_id, TRANSFER_ABORT_ZONE_IN_COMBAT_LIKE_CPP);
            return Some(wow_map::CreateMapDecision::Reject {
                side_effects: Vec::new(),
            });
        }

        if is_dungeon
            && !bypass_player_cannot_enter_like_cpp
            && let wow_map::CreateMapDecision::Existing {
                key, difficulty_id, ..
            } = &decision
            && let Some(lock_context) = existing_instance_lock_context
        {
            let deny_reason = self
                .cannot_enter_existing_instance_lock_like_cpp(
                    key.map_id,
                    *difficulty_id,
                    lock_context,
                )
                .unwrap_or(wow_instances::TransferAbortReason::None);
            if deny_reason != wow_instances::TransferAbortReason::None {
                self.send_transfer_aborted_like_cpp(key.map_id, deny_reason as u32);
                return Some(wow_map::CreateMapDecision::Reject {
                    side_effects: Vec::new(),
                });
            }
        }

        if is_dungeon
            && !bypass_player_cannot_enter_like_cpp
            && !map_entry.ignores_instance_farm_limit_like_cpp()
            && let Some(key) = key
            && !self.check_instance_count_like_cpp(key.instance_id)
            && self.player_is_alive_like_cpp()
        {
            self.send_transfer_aborted_like_cpp(
                key.map_id,
                TRANSFER_ABORT_TOO_MANY_INSTANCES_LIKE_CPP,
            );
            return Some(wow_map::CreateMapDecision::Reject {
                side_effects: Vec::new(),
            });
        }

        if is_dungeon && let Some(key) = key {
            let now_secs = u64::try_from(unix_now()).unwrap_or(0);
            self.add_instance_enter_time_like_cpp(key.instance_id, now_secs);
        }

        let _ = self.apply_create_map_side_effects_like_cpp(map_id, &decision);

        if is_dungeon
            && let Some(key) = key
            && let Some(difficulty_id) = create_map_decision_difficulty_id_like_cpp(&decision)
            && let Some(lock) =
                self.create_map_active_instance_lock_context_like_cpp(map_id, difficulty_id)
        {
            let manager = Arc::clone(self.canonical_map_manager.as_ref()?);
            if let Ok(mut manager) = manager.lock()
                && let Some(map) = manager.find_map_mut(key.map_id, key.instance_id)
            {
                map.set_instance_lock_context(Some(lock));
            }
        }

        if let Some(key) = key
            && let Some(player) = self.canonical_player_entity_snapshot_for_map_like_cpp(key)
        {
            let manager = Arc::clone(self.canonical_map_manager.as_ref()?);
            if let Ok(mut manager) = manager.lock() {
                self.sync_canonical_player_entity_for_map_like_cpp(&mut manager, key, player);
            }
        }

        Some(decision)
    }

    fn send_transfer_aborted_like_cpp(&self, map_id: u32, transfer_abort: u32) {
        self.send_transfer_aborted_with_params_like_cpp(map_id, transfer_abort, 0, 0);
    }

    fn send_transfer_aborted_with_params_like_cpp(
        &self,
        map_id: u32,
        transfer_abort: u32,
        arg: u8,
        map_difficulty_x_condition_id: i32,
    ) {
        self.send_packet(&wow_packet::packets::misc::TransferAborted {
            map_id,
            arg,
            map_difficulty_x_condition_id,
            transfer_abort,
        });
    }

    fn prune_expired_instance_reset_times_like_cpp(&mut self, now_secs: u64) {
        self.represented_instance_reset_times_like_cpp
            .retain(|_, release_time| *release_time > now_secs);
    }

    fn check_instance_count_like_cpp(&mut self, instance_id: u32) -> bool {
        let now_secs = u64::try_from(unix_now()).unwrap_or(0);
        self.check_instance_count_at_like_cpp(instance_id, now_secs)
    }

    fn check_instance_count_probe_like_cpp(&self, instance_id: u32) -> bool {
        let now_secs = u64::try_from(unix_now()).unwrap_or(0);
        let active_count = self
            .represented_instance_reset_times_like_cpp
            .values()
            .filter(|release_time| **release_time > now_secs)
            .count();
        if active_count < self.max_instances_per_hour_like_cpp as usize {
            return true;
        }

        self.represented_instance_reset_times_like_cpp
            .get(&instance_id)
            .is_some_and(|release_time| *release_time > now_secs)
    }

    fn check_instance_count_at_like_cpp(&mut self, instance_id: u32, now_secs: u64) -> bool {
        self.prune_expired_instance_reset_times_like_cpp(now_secs);
        if self.represented_instance_reset_times_like_cpp.len()
            < self.max_instances_per_hour_like_cpp as usize
        {
            return true;
        }

        self.represented_instance_reset_times_like_cpp
            .contains_key(&instance_id)
    }

    pub(crate) fn add_instance_enter_time_like_cpp(&mut self, instance_id: u32, enter_time: u64) {
        self.represented_instance_reset_times_like_cpp
            .entry(instance_id)
            .or_insert(enter_time.saturating_add(HOUR_SECS_LIKE_CPP));
    }

    #[cfg(test)]
    fn load_instance_time_restriction_rows_like_cpp(
        &mut self,
        rows: impl IntoIterator<Item = (u32, u64)>,
    ) {
        self.represented_instance_reset_times_like_cpp.clear();
        for (instance_id, release_time) in rows {
            self.represented_instance_reset_times_like_cpp
                .entry(instance_id)
                .or_insert(release_time);
        }
    }

    #[cfg(test)]
    fn load_completed_achievement_rows_like_cpp(&mut self, rows: impl IntoIterator<Item = u32>) {
        self.represented_completed_achievements_like_cpp.clear();
        self.represented_completed_achievements_like_cpp.extend(
            rows.into_iter()
                .filter(|achievement_id| *achievement_id != 0),
        );
    }

    pub async fn load_completed_achievements_like_cpp(&mut self) {
        self.represented_completed_achievements_like_cpp.clear();

        let Some(player_guid) = self.player_guid() else {
            warn!(
                account = self.account_id,
                "LoadCompletedAchievements skipped: player guid unavailable"
            );
            return;
        };
        let Some(char_db) = self.char_db().map(Arc::clone) else {
            warn!(
                account = self.account_id,
                guid = player_guid.counter(),
                "LoadCompletedAchievements skipped: character database unavailable"
            );
            return;
        };

        let mut stmt = char_db.prepare(CharStatements::SEL_CHARACTER_ACHIEVEMENTS);
        stmt.set_u64(0, player_guid.counter() as u64);

        let result = match char_db.query(&stmt).await {
            Ok(result) => result,
            Err(error) => {
                warn!(
                    account = self.account_id,
                    guid = player_guid.counter(),
                    "LoadCompletedAchievements query failed: {error}"
                );
                return;
            }
        };

        if result.is_empty() {
            return;
        }

        let mut result = result;
        loop {
            let achievement_id = result.try_read::<u32>(0).unwrap_or(0);
            if achievement_id != 0 {
                self.represented_completed_achievements_like_cpp
                    .insert(achievement_id);
            }

            if !result.next_row() {
                break;
            }
        }
    }

    pub async fn load_instance_time_restrictions_like_cpp(&mut self) {
        self.represented_instance_reset_times_like_cpp.clear();

        let Some(char_db) = self.char_db().map(Arc::clone) else {
            warn!(
                account = self.account_id,
                "LoadInstanceTimeRestrictions skipped: character database unavailable"
            );
            return;
        };

        let mut stmt = char_db.prepare(CharStatements::SEL_ACCOUNT_INSTANCELOCKTIMES);
        stmt.set_u32(0, self.account_id);

        let result = match char_db.query(&stmt).await {
            Ok(result) => result,
            Err(error) => {
                warn!(
                    account = self.account_id,
                    "LoadInstanceTimeRestrictions query failed: {error}"
                );
                return;
            }
        };

        if result.is_empty() {
            return;
        }

        let mut result = result;
        loop {
            let instance_id = result.try_read::<u32>(0).unwrap_or(0);
            let release_time = result.try_read::<u64>(1).unwrap_or(0);
            self.represented_instance_reset_times_like_cpp
                .entry(instance_id)
                .or_insert(release_time);

            if !result.next_row() {
                break;
            }
        }
    }

    fn instance_time_restriction_save_statements_like_cpp(&self) -> Vec<PreparedStatement> {
        if self.represented_instance_reset_times_like_cpp.is_empty() {
            return Vec::new();
        }

        let mut statements =
            Vec::with_capacity(self.represented_instance_reset_times_like_cpp.len() + 1);
        statements.push(
            wow_instances::InstanceLockMgr::delete_account_instance_lock_times_statement(
                self.account_id,
            ),
        );
        for (&instance_id, &release_time) in &self.represented_instance_reset_times_like_cpp {
            statements.push(
                wow_instances::InstanceLockMgr::insert_account_instance_lock_time_statement(
                    self.account_id,
                    instance_id,
                    release_time,
                ),
            );
        }
        statements
    }

    fn access_requirement_abort_like_cpp(
        &self,
        map_id: u32,
        requested_difficulty: u8,
    ) -> Option<(u32, u8, i32)> {
        let downscaled_entries = self
            .create_map_db2_entries_like_cpp(map_id, requested_difficulty as wow_map::Difficulty)?;
        let map_difficulty_id = self
            .map_difficulty_store
            .as_ref()
            .and_then(|store| store.get(map_id, downscaled_entries.difficulty_id))
            .map(|entry| entry.id)
            .unwrap_or(0);
        let map_difficulty_has_message = self
            .map_difficulty_store
            .as_ref()
            .and_then(|store| store.get(map_id, downscaled_entries.difficulty_id))
            .map(|entry| !entry.message.is_empty())
            .unwrap_or(false);

        let failed_map_difficulty_x_condition =
            if self.instance_ignore_level_like_cpp || map_difficulty_id == 0 {
                0
            } else {
                self.map_difficulty_x_condition_store
                    .as_ref()
                    .zip(self.player_condition_store.as_ref())
                    .and_then(|(difficulty_conditions, player_conditions)| {
                        difficulty_conditions.failed_condition_like_cpp(
                            map_difficulty_id,
                            player_conditions,
                            |condition| {
                                let context = self.represented_player_condition_context_like_cpp();
                                is_player_meeting_condition_like_cpp(
                                    condition,
                                    &context.as_context(self),
                                )
                            },
                        )
                    })
                    .unwrap_or(0)
            };

        let access_requirement = self
            .access_requirement_store
            .as_ref()
            .and_then(|store| store.get(map_id, requested_difficulty));

        let mut level_min = 0;
        let mut level_max = 0;
        let mut missing_item = 0;
        let mut missing_quest = 0;
        let mut missing_achievement = 0;

        if let Some(access_requirement) = access_requirement {
            if !self.instance_ignore_level_like_cpp {
                if access_requirement.level_min != 0
                    && self.player_level_like_cpp() < access_requirement.level_min
                {
                    level_min = access_requirement.level_min;
                }
                if access_requirement.level_max != 0
                    && self.player_level_like_cpp() > access_requirement.level_max
                {
                    level_max = access_requirement.level_max;
                }
            }

            let item_counts = self.represented_inventory_item_counts_like_cpp();
            if access_requirement.item != 0 {
                if item_counts
                    .get(&access_requirement.item)
                    .copied()
                    .unwrap_or(0)
                    == 0
                    && (access_requirement.item2 == 0
                        || item_counts
                            .get(&access_requirement.item2)
                            .copied()
                            .unwrap_or(0)
                            == 0)
                {
                    missing_item = access_requirement.item;
                }
            } else if access_requirement.item2 != 0
                && item_counts
                    .get(&access_requirement.item2)
                    .copied()
                    .unwrap_or(0)
                    == 0
            {
                missing_item = access_requirement.item2;
            }

            match player_team_for_race_cpp(self.player_race_like_cpp()) {
                Team::Alliance
                    if access_requirement.quest_done_a != 0
                        && !self
                            .rewarded_quests
                            .contains(&access_requirement.quest_done_a) =>
                {
                    missing_quest = access_requirement.quest_done_a;
                }
                Team::Horde
                    if access_requirement.quest_done_h != 0
                        && !self
                            .rewarded_quests
                            .contains(&access_requirement.quest_done_h) =>
                {
                    missing_quest = access_requirement.quest_done_h;
                }
                _ => {}
            }

            if access_requirement.completed_achievement != 0
                && !self.access_requirement_leader_has_achievement_like_cpp(
                    access_requirement.completed_achievement,
                )
            {
                missing_achievement = access_requirement.completed_achievement;
            }
        }

        if level_min != 0
            || level_max != 0
            || failed_map_difficulty_x_condition != 0
            || missing_item != 0
            || missing_quest != 0
            || missing_achievement != 0
        {
            if missing_quest != 0
                && let Some(access_requirement) = access_requirement
                && !access_requirement.quest_failed_text.is_empty()
            {
                self.send_system_message_like_cpp(&access_requirement.quest_failed_text);
            } else if map_difficulty_has_message || failed_map_difficulty_x_condition != 0 {
                return Some((
                    TRANSFER_ABORT_DIFFICULTY_LIKE_CPP,
                    requested_difficulty,
                    failed_map_difficulty_x_condition as i32,
                ));
            } else if missing_item != 0 {
                let level_min_text = level_min.to_string();
                let item_name = self.item_template_name_like_cpp(missing_item);
                let notify_text = trinity_sprintf_like_cpp(
                    self.trinity_string_like_cpp(
                        wow_data::LANG_LEVEL_MINREQUIRED_AND_ITEM_LIKE_CPP,
                    ),
                    &[level_min_text.as_str(), item_name],
                );
                self.send_notification_like_cpp(notify_text);
            } else if level_min != 0 {
                let level_min_text = level_min.to_string();
                let notify_text = trinity_sprintf_like_cpp(
                    self.trinity_string_like_cpp(wow_data::LANG_LEVEL_MINREQUIRED_LIKE_CPP),
                    &[level_min_text.as_str()],
                );
                self.send_notification_like_cpp(notify_text);
            }
            return Some((TRANSFER_ABORT_ERROR_LIKE_CPP, 0, 0));
        }

        None
    }

    pub(crate) fn access_requirement_leader_has_achievement_like_cpp(
        &self,
        achievement_id: u32,
    ) -> bool {
        if achievement_id == 0 {
            return true;
        }

        let Some(player_guid) = self.player_guid else {
            return false;
        };
        let leader_guid = self
            .group_guid
            .and_then(|group_guid| self.group_registry.as_ref()?.get(&group_guid))
            .map(|group| group.leader_guid)
            .unwrap_or(player_guid);
        if leader_guid == player_guid {
            return self
                .represented_completed_achievements_like_cpp
                .contains(&achievement_id);
        }

        self.player_registry
            .as_ref()
            .and_then(|registry| registry.get(&leader_guid))
            .is_some_and(|leader| leader.completed_achievements.contains(&achievement_id))
    }

    fn cannot_enter_existing_instance_lock_like_cpp(
        &self,
        map_id: u32,
        difficulty_id: wow_map::Difficulty,
        target_lock_context: wow_map::CreateMapInstanceLockContext,
    ) -> Option<wow_instances::TransferAbortReason> {
        let player_guid = self.player_guid?;
        let owner_guid_counter = i64::try_from(target_lock_context.owner_guid_counter).ok()?;
        let owner_guid = ObjectGuid::create_player(1, owner_guid_counter);
        let entries = self.create_map_db2_entries_like_cpp(map_id, difficulty_id)?;
        let now = u64::try_from(unix_now()).unwrap_or(0);
        let mgr = self.instance_lock_mgr.as_ref()?;
        let mgr = mgr.read().ok()?;
        let target_lock = mgr.find_active_instance_lock_at(owner_guid, &entries, now)?;
        Some(mgr.can_join_instance_lock_at(player_guid, &entries, target_lock, now))
    }

    pub(crate) fn apply_create_map_side_effects_like_cpp(
        &mut self,
        map_id: u32,
        decision: &wow_map::CreateMapDecision,
    ) -> CreateMapSideEffectApplySummaryLikeCpp {
        let side_effects = match decision {
            wow_map::CreateMapDecision::Existing { side_effects, .. }
            | wow_map::CreateMapDecision::Create { side_effects, .. }
            | wow_map::CreateMapDecision::Reject { side_effects } => side_effects,
        };
        let decision_difficulty_id = match decision {
            wow_map::CreateMapDecision::Existing { difficulty_id, .. }
            | wow_map::CreateMapDecision::Create { difficulty_id, .. } => Some(*difficulty_id),
            wow_map::CreateMapDecision::Reject { .. } => None,
        };

        let mut summary = CreateMapSideEffectApplySummaryLikeCpp::default();
        for side_effect in side_effects {
            match *side_effect {
                wow_map::CreateMapSideEffect::SetPlayerRecentInstance { instance_id } => {
                    self.set_represented_player_recent_instance_like_cpp(map_id, instance_id);
                    summary.player_recent_instance_sets += 1;
                }
                wow_map::CreateMapSideEffect::SetGroupRecentInstance {
                    owner_guid_counter,
                    instance_id,
                } => {
                    let owner_guid = i64::try_from(owner_guid_counter)
                        .ok()
                        .map(|counter| ObjectGuid::create_player(1, counter));
                    let updated = self
                        .group_guid
                        .and_then(|group_guid| self.group_registry.as_ref()?.get_mut(&group_guid))
                        .zip(owner_guid)
                        .map(|(mut group, owner_guid)| {
                            group.set_recent_instance_like_cpp(map_id, owner_guid, instance_id);
                        })
                        .is_some();
                    if updated {
                        summary.group_recent_instance_sets += 1;
                    } else {
                        summary.skipped_group_recent_instance_sets += 1;
                    }
                }
                wow_map::CreateMapSideEffect::CreateInstanceLockForNewInstance {
                    owner_guid_counter,
                    instance_id,
                } => {
                    let owner_guid = i64::try_from(owner_guid_counter)
                        .ok()
                        .map(|counter| ObjectGuid::create_player(1, counter));
                    let created = decision_difficulty_id
                        .zip(owner_guid)
                        .and_then(|(difficulty_id, owner_guid)| {
                            self.create_instance_lock_for_new_instance_side_effect_like_cpp(
                                map_id,
                                difficulty_id,
                                owner_guid,
                                instance_id,
                            )
                        })
                        .is_some();
                    if created {
                        summary.instance_lock_creates += 1;
                    } else {
                        summary.skipped_instance_lock_creates += 1;
                    }
                }
                wow_map::CreateMapSideEffect::SetInstanceLockInstanceId { instance_id } => {
                    let updated = decision_difficulty_id
                        .and_then(|difficulty_id| {
                            self.set_active_instance_lock_instance_id_side_effect_like_cpp(
                                map_id,
                                difficulty_id,
                                instance_id,
                            )
                        })
                        .is_some();
                    if updated {
                        summary.instance_lock_instance_id_updates += 1;
                    } else {
                        summary.skipped_instance_lock_instance_id_updates += 1;
                    }
                }
                wow_map::CreateMapSideEffect::TeleportToBattlegroundEntryPoint => {
                    summary.pending_battleground_entry_teleports += 1;
                }
            }
        }

        summary
    }

    fn create_instance_lock_for_new_instance_side_effect_like_cpp(
        &self,
        map_id: u32,
        difficulty_id: wow_map::Difficulty,
        owner_guid: ObjectGuid,
        instance_id: u32,
    ) -> Option<()> {
        let entries = self.create_map_db2_entries_like_cpp(map_id, difficulty_id)?;
        let now = u64::try_from(unix_now()).unwrap_or(0);
        let mgr = self.instance_lock_mgr.as_ref()?;
        let mut mgr = mgr.write().ok()?;
        mgr.create_instance_lock_for_new_instance_at(
            owner_guid,
            &entries,
            instance_id,
            self.reset_schedule_like_cpp,
            now,
        )?;
        Some(())
    }

    fn set_active_instance_lock_instance_id_side_effect_like_cpp(
        &self,
        map_id: u32,
        difficulty_id: wow_map::Difficulty,
        instance_id: u32,
    ) -> Option<()> {
        let entries = self.create_map_db2_entries_like_cpp(map_id, difficulty_id)?;
        let owner_guid = self.create_map_instance_owner_guid_like_cpp(map_id)?;
        let now = u64::try_from(unix_now()).unwrap_or(0);
        let mgr = self.instance_lock_mgr.as_ref()?;
        let mut mgr = mgr.write().ok()?;
        mgr.set_active_instance_lock_instance_id_at(owner_guid, &entries, now, instance_id)
            .then_some(())
    }

    pub(crate) fn create_map_player_context_like_cpp(
        &self,
        map_id: u32,
        map_entry: wow_data::map::MapEntry,
        player_guid: ObjectGuid,
    ) -> wow_map::CreateMapPlayerContext {
        let player_difficulty_id =
            self.represented_player_difficulty_id_for_map_entry_like_cpp(map_id, map_entry);

        let group = self
            .group_guid
            .and_then(|group_guid| self.group_registry.as_ref()?.get(&group_guid))
            .map(|group| {
                let difficulty_id = self.represented_group_difficulty_id_for_map_entry_like_cpp(
                    map_id, map_entry, &group,
                );
                wow_map::CreateMapGroupContext {
                    difficulty_id,
                    recent_instance_owner_guid_counter: group
                        .recent_instance_owner_like_cpp(map_id)
                        .counter() as u64,
                    recent_instance_id: group.recent_instance_id_like_cpp(map_id),
                }
            });

        wow_map::CreateMapPlayerContext {
            guid_counter: player_guid.counter() as u64,
            team_id: player_team_id_for_race_cpp(self.player_race_like_cpp()),
            battleground_id: 0,
            has_battleground: false,
            player_difficulty_id,
            player_recent_instance_id: self.represented_player_recent_instance_id_like_cpp(map_id),
            group,
        }
    }

    pub(crate) fn create_map_difficulty_context_like_cpp(
        &self,
        map_id: u32,
        difficulty_id: wow_map::Difficulty,
    ) -> Option<wow_map::CreateMapDifficultyContext> {
        let entries = self.create_map_db2_entries_like_cpp(map_id, difficulty_id)?;

        Some(wow_map::CreateMapDifficultyContext {
            difficulty_id: entries.difficulty_id,
            has_reset_schedule: entries.has_reset_schedule(),
            is_instance_id_bound: entries.is_instance_id_bound(),
        })
    }

    pub(crate) fn create_map_active_instance_lock_context_like_cpp(
        &self,
        map_id: u32,
        difficulty_id: wow_map::Difficulty,
    ) -> Option<wow_map::CreateMapInstanceLockContext> {
        let entries = self.create_map_db2_entries_like_cpp(map_id, difficulty_id)?;
        let owner_guid = self.create_map_instance_owner_guid_like_cpp(map_id)?;
        let now = u64::try_from(unix_now()).unwrap_or(0);
        let mgr = self.instance_lock_mgr.as_ref()?;
        let mgr = mgr.read().ok()?;
        let lock = mgr.find_active_instance_lock_at(owner_guid, &entries, now)?;

        Some(wow_map::CreateMapInstanceLockContext {
            instance_id: lock.instance_id,
            difficulty_id: lock.difficulty_id,
            token: create_map_instance_lock_token_like_cpp(owner_guid, &entries, lock),
            owner_guid_counter: owner_guid.counter() as u64,
        })
    }

    pub(crate) fn create_map_db2_entries_like_cpp(
        &self,
        map_id: u32,
        difficulty_id: wow_map::Difficulty,
    ) -> Option<wow_instances::MapDb2Entries> {
        wow_instances::MapDb2Entries::from_downscaled_stores_like_cpp(
            self.map_store()?.as_ref(),
            self.map_difficulty_store()?.as_ref(),
            self.difficulty_store()?.as_ref(),
            map_id,
            difficulty_id,
        )
    }

    pub(crate) fn lfg_has_active_instance_lock_like_cpp(
        &self,
        map_id: u32,
        difficulty_id: wow_map::Difficulty,
    ) -> bool {
        let Some(player_guid) = self.player_guid else {
            return false;
        };
        let Some(entries) = self.create_map_db2_entries_like_cpp(map_id, difficulty_id) else {
            return false;
        };
        let Some(mgr) = self.instance_lock_mgr.as_ref() else {
            return false;
        };
        let Ok(mgr) = mgr.read() else {
            return false;
        };
        let now = u64::try_from(unix_now()).unwrap_or(0);
        mgr.find_active_instance_lock_at(player_guid, &entries, now)
            .is_some()
    }

    fn create_map_instance_owner_guid_like_cpp(&self, map_id: u32) -> Option<ObjectGuid> {
        self.group_guid
            .and_then(|group_guid| self.group_registry.as_ref()?.get(&group_guid))
            .map(|group| group.recent_instance_owner_like_cpp(map_id))
            .or(self.player_guid)
    }

    fn represented_player_difficulty_id_for_map_entry_like_cpp(
        &self,
        map_id: u32,
        map_entry: wow_data::map::MapEntry,
    ) -> wow_map::Difficulty {
        (match map_entry.instance_type {
            wow_data::map::MAP_INSTANCE => self.represented_dungeon_difficulty_id_like_cpp,
            wow_data::map::MAP_RAID => {
                if self.map_uses_legacy_raid_difficulty_like_cpp(map_id) {
                    self.represented_legacy_raid_difficulty_id_like_cpp
                } else {
                    self.represented_raid_difficulty_id_like_cpp
                }
            }
            _ => 0,
        }) as wow_map::Difficulty
    }

    fn represented_group_difficulty_id_for_map_entry_like_cpp(
        &self,
        map_id: u32,
        map_entry: wow_data::map::MapEntry,
        group: &GroupInfo,
    ) -> wow_map::Difficulty {
        (match map_entry.instance_type {
            wow_data::map::MAP_INSTANCE => group.dungeon_difficulty_id,
            wow_data::map::MAP_RAID => {
                if self.map_uses_legacy_raid_difficulty_like_cpp(map_id) {
                    group.legacy_raid_difficulty_id
                } else {
                    group.raid_difficulty_id
                }
            }
            _ => u32::from(
                self.represented_player_difficulty_id_for_map_entry_like_cpp(map_id, map_entry),
            ),
        }) as wow_map::Difficulty
    }

    fn map_uses_legacy_raid_difficulty_like_cpp(&self, map_id: u32) -> bool {
        let Some(default_difficulty) = self.map_difficulty_store().and_then(|store| {
            self.difficulty_store().and_then(|difficulty_store| {
                store.default_for_map_like_cpp(map_id, difficulty_store)
            })
        }) else {
            return true;
        };

        let Some(difficulty) = self
            .difficulty_store()
            .and_then(|store| store.get(u32::from(default_difficulty.difficulty_id)))
        else {
            return true;
        };

        DifficultyFlags::from_bits_truncate(difficulty.flags).contains(DifficultyFlags::LEGACY)
    }

    /// Inject the dedicated Detour worker handle. The session only sends
    /// path requests; it never owns raw mmap/navmesh state.
    pub fn set_mmap_pathfinder_like_cpp(
        &mut self,
        pathfinder: Arc<WorldMMapPathfinderWorkerLikeCpp>,
    ) {
        self.mmap_pathfinder_like_cpp = Some(pathfinder);
    }

    /// Inject the shared C++ `InstanceLockMgr` analogue.
