    pub(crate) fn canonical_gameobject_access_like_cpp(
        &self,
        guid: ObjectGuid,
    ) -> Option<RepresentedGameObjectAccessLikeCpp> {
        if guid.is_empty() || !guid.is_game_object() {
            return None;
        }
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = manager.find_map(u32::from(self.player_map_id_like_cpp()), 0)?;
        let game_object = map.map().get_typed_game_object(guid)?;
        Some(RepresentedGameObjectAccessLikeCpp {
            entry: game_object.world().object().entry(),
            position: game_object.world().position(),
        })
    }

    pub(crate) fn search_spell_focus_like_cpp(
        &self,
        focus_id: u32,
    ) -> Option<RepresentedSpellFocusObjectLikeCpp> {
        if focus_id == 0 {
            return None;
        }
        let caster_position = self.player_position_like_cpp()?;
        let player_map_key = self.current_canonical_player_map_key_like_cpp()?;
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let managed = manager.find_map(player_map_key.map_id, player_map_key.instance_id)?;
        let map = managed.map();
        let nearby = map.nearby_cell_guids_like_cpp(
            caster_position.x,
            caster_position.y,
            map.visibility_range(),
        );
        for guid in nearby.grid.gameobjects {
            let Some(gameobject) = map.get_typed_game_object(guid) else {
                continue;
            };
            let world = gameobject.world();
            if !world.object().is_in_world() {
                continue;
            }
            let Some(source) = gameobject.represented_spell_focus_use_source_like_cpp() else {
                continue;
            };
            if source.focus_type != focus_id {
                continue;
            }
            if !world
                .position()
                .is_within_dist(&caster_position, source.radius as f32)
            {
                continue;
            }
            return Some(RepresentedSpellFocusObjectLikeCpp {
                guid,
                map_key: player_map_key,
                position: world.position(),
                source,
            });
        }
        None
    }

    pub(crate) fn represented_gameobject_can_interact_with_like_cpp(
        &self,
        guid: ObjectGuid,
        interaction_distance: f32,
    ) -> Option<RepresentedGameObjectAccessLikeCpp> {
        let access = self.canonical_gameobject_access_like_cpp(guid)?;
        let player_position = self.player_position_like_cpp()?;
        if access
            .position
            .is_within_dist(&player_position, interaction_distance)
        {
            Some(access)
        } else {
            None
        }
    }

    pub(crate) fn represented_gameobject_questgiver_can_interact_with_like_cpp(
        &self,
        guid: ObjectGuid,
    ) -> Option<RepresentedGameObjectAccessLikeCpp> {
        // C++ anchor: Player::CanInteractWithQuestGiver(TYPEID_GAMEOBJECT)
        // delegates to GetGameObjectIfCanInteractWith(guid, GAMEOBJECT_TYPE_QUESTGIVER).
        // This represented guard consumes canonical map access plus locally recorded
        // template type/radius from the GO-use path. The C++ IconName == "Point"
        // rejection is represented earlier in handle_game_obj_use before runtime state
        // is registered/consumed here; standalone paths without represented type state
        // fail closed instead of treating canonical existence as interactability.
        let access = self.canonical_gameobject_access_like_cpp(guid)?;
        let state = self.represented_gameobject_use_states.get(&guid)?;
        if state.go_type.map(u32::from) != Some(wow_entities::GAMEOBJECT_TYPE_QUESTGIVER) {
            return None;
        }
        let player_position = self.player_position_like_cpp()?;
        let interaction_distance = state
            .interact_radius_override
            .filter(|value| *value != 0)
            .map_or(5.5555553, |override_hundredths| {
                override_hundredths as f32 / 100.0
            });
        access
            .position
            .is_within_dist(&player_position, interaction_distance)
            .then_some(access)
    }

    pub(crate) fn has_canonical_map_manager_like_cpp(&self) -> bool {
        self.canonical_map_manager.is_some()
    }

    #[allow(dead_code)]
    pub(crate) fn canonical_creature_access_like_cpp(
        &self,
        guid: ObjectGuid,
    ) -> Option<RepresentedCreatureAccessLikeCpp> {
        if guid.is_empty() || !guid.is_any_type_creature() {
            return None;
        }
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = manager.find_map(u32::from(self.player_map_id_like_cpp()), 0)?;
        let record = map.map().map_object_record(guid)?;
        let creature = if guid.is_pet() {
            record.pet()?.creature()
        } else {
            record.creature()?
        };
        Some(RepresentedCreatureAccessLikeCpp {
            entry: creature.entry(),
            position: creature.unit().world().position(),
            npc_flags: creature.ai_ownership().npc_flags,
            npc_flags2: creature.ai_ownership().npc_flags2,
            trainer_class: creature.trainer_class_like_cpp(),
            faction_template_id: creature.unit().data().faction_template.max(0) as u32,
        })
    }

    fn represented_spell_click_creature_snapshot_like_cpp(
        &self,
        guid: ObjectGuid,
    ) -> Option<RepresentedSpellClickCreatureSnapshotLikeCpp> {
        if guid.is_empty() || !guid.is_any_type_creature() {
            return None;
        }
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = manager.find_map(u32::from(self.player_map_id_like_cpp()), 0)?;
        let record = map.map().map_object_record(guid)?;
        let (creature, owner_guid) = if guid.is_pet() {
            let pet = record.pet()?;
            (pet.creature(), Some(pet.owner_guid()))
        } else {
            let creature = record.creature()?;
            (creature, creature.unit().subsystems().control.owner_guid)
        };

        Some(RepresentedSpellClickCreatureSnapshotLikeCpp {
            guid: creature.guid(),
            entry: creature.entry(),
            map_id: creature.unit().world().map_id(),
            instance_id: creature.unit().world().instance_id(),
            position: creature.position(),
            phase_shift: creature.unit().world().phase_shift().clone(),
            npc_flags: creature.ai_ownership().npc_flags,
            faction_template_id: creature.unit().data().faction_template.max(0) as u32,
            level: u32::from(creature.level()),
            health: creature.current_health(),
            max_health: creature.max_health(),
            is_alive: creature.is_alive(),
            is_in_world: creature.unit().world().object().is_in_world(),
            is_summon: creature.is_summon_like_cpp(),
            owner_guid,
        })
    }

    pub(crate) fn represented_can_see_spell_click_on_creature_like_cpp(
        &self,
        creature_guid: ObjectGuid,
    ) -> RepresentedCanSeeSpellClickOutcomeLikeCpp {
        let Some(spell_click_store) = self.npc_spell_click_store.as_ref() else {
            return RepresentedCanSeeSpellClickOutcomeLikeCpp::ExactContextUnrepresented;
        };
        let Some(condition_store) = self.condition_store.as_ref() else {
            return RepresentedCanSeeSpellClickOutcomeLikeCpp::ExactContextUnrepresented;
        };
        let Some(creature) = self.represented_spell_click_creature_snapshot_like_cpp(creature_guid)
        else {
            return RepresentedCanSeeSpellClickOutcomeLikeCpp::ExactContextUnrepresented;
        };
        if !creature.is_in_world {
            return RepresentedCanSeeSpellClickOutcomeLikeCpp::Hidden;
        }

        if (u64::from(creature.npc_flags) & UNIT_NPC_FLAG_SPELLCLICK_LIKE_CPP) == 0 {
            return RepresentedCanSeeSpellClickOutcomeLikeCpp::Hidden;
        }

        let click_bounds = spell_click_store.spell_click_info_map_bounds_like_cpp(creature.entry);
        if click_bounds.is_empty() {
            return RepresentedCanSeeSpellClickOutcomeLikeCpp::Hidden;
        }

        let Some(clicker_object) = self.build_condition_player_object_like_cpp() else {
            return RepresentedCanSeeSpellClickOutcomeLikeCpp::ExactContextUnrepresented;
        };
        let mut target_object = WorldObject::new(
            false,
            TypeId::Unit,
            wow_constants::TypeMask::OBJECT | wow_constants::TypeMask::UNIT,
        );
        target_object.object_mut().create(creature.guid);
        target_object.object_mut().set_entry(creature.entry);
        let _ = target_object.set_map(creature.map_id, creature.instance_id);
        target_object.relocate(creature.position);
        *target_object.phase_shift_mut() = creature.phase_shift.clone();

        let player_unit_snapshot = self.condition_player_unit_snapshot_like_cpp();
        let player_snapshot = self.condition_player_snapshot_like_cpp();
        let creature_unit_snapshot = crate::conditions::ConditionUnitSnapshot {
            level: creature.level,
            health: creature.health,
            max_health: creature.max_health,
            class_mask: 0,
            race: 0,
            creature_type: None,
            is_alive: creature.is_alive,
            is_charmed: false,
            in_water: false,
            unit_state: 0,
            stand_state: UnitStandStateType::Stand as u32,
        };
        let player_condition_store = self.player_condition_store().cloned();
        let player_condition_context = self.represented_player_condition_context_like_cpp();
        let area_table_store = self.area_table_store.as_ref().cloned();

        for click_info in click_bounds {
            match click_info.user_type {
                SPELL_CLICK_USER_FRIEND_LIKE_CPP => {
                    if creature.is_summon
                        || self.faction_template_store.is_none()
                        || self.player_faction_template_like_cpp.is_none()
                    {
                        return RepresentedCanSeeSpellClickOutcomeLikeCpp::ExactContextUnrepresented;
                    }
                    let reaction = self.represented_get_reaction_to_like_cpp(
                        RepresentedGetReactionInputLikeCpp {
                            self_faction_template_id: self
                                .player_faction_template_like_cpp
                                .unwrap_or(0),
                            target_faction_template_id: creature.faction_template_id,
                            same_object: false,
                            attackable_by_summoner: false,
                            same_charmer_or_owner_or_self: false,
                            self_has_player_owner: true,
                            target_has_player_owner: false,
                            target_player_owner_is_current_session: false,
                            target_owner_forced_rank_for_self: None,
                            same_player_owner: false,
                            duel_in_progress: false,
                            same_raid: false,
                            self_unit_player_controlled: true,
                            target_unit_player_controlled: false,
                            self_ffa_pvp: false,
                            target_ffa_pvp: false,
                            self_ignores_reputation: false,
                            target_ignores_reputation: false,
                            target_is_unit: true,
                            target_player_contested_pvp: false,
                        },
                    );
                    if reaction < wow_data::reputation::ReputationRankLikeCpp::Friendly {
                        return RepresentedCanSeeSpellClickOutcomeLikeCpp::Hidden;
                    }
                }
                SPELL_CLICK_USER_PARTY_LIKE_CPP | SPELL_CLICK_USER_RAID_LIKE_CPP => {
                    return RepresentedCanSeeSpellClickOutcomeLikeCpp::ExactContextUnrepresented;
                }
                _ => {}
            }

            if crate::conditions::is_object_meeting_spell_click_conditions_like_cpp(
                condition_store,
                creature.entry,
                click_info.spell_id,
                Some(&clicker_object),
                Some(&target_object),
                |condition, source_info| {
                    source_info.set_unit_target_snapshot(0, player_unit_snapshot);
                    source_info.set_player_target_snapshot(0, player_snapshot);
                    source_info.set_unit_target_snapshot(1, creature_unit_snapshot);
                    if let Some(store) = player_condition_store.as_ref() {
                        source_info.set_player_condition_store(store.as_ref());
                        source_info.set_player_condition_context(
                            0,
                            player_condition_context.as_context(self),
                        );
                    }
                    crate::conditions::condition_meets_basic_like_cpp(
                        condition,
                        source_info,
                        |area_id, required_area_id| {
                            area_table_store.as_ref().is_some_and(|store| {
                                store.is_in_area_like_cpp(area_id, required_area_id)
                            })
                        },
                    )
                    .value()
                    .unwrap_or(false)
                },
            ) {
                return RepresentedCanSeeSpellClickOutcomeLikeCpp::Visible;
            }
        }

        RepresentedCanSeeSpellClickOutcomeLikeCpp::Hidden
    }

    pub(crate) fn represented_handle_spell_click_plan_like_cpp(
        &self,
        creature_guid: ObjectGuid,
    ) -> RepresentedSpellClickPlanLikeCpp {
        self.represented_handle_spell_click_plan_with_seat_like_cpp(creature_guid, None)
    }

    pub(crate) fn represented_handle_spell_click_plan_with_seat_like_cpp(
        &self,
        creature_guid: ObjectGuid,
        seat_id: Option<i8>,
    ) -> RepresentedSpellClickPlanLikeCpp {
        let mut plan = RepresentedSpellClickPlanLikeCpp::default();

        let Some(spell_click_store) = self.npc_spell_click_store.as_ref() else {
            plan.exact_context_unrepresented = true;
            return plan;
        };
        let Some(condition_store) = self.condition_store.as_ref() else {
            plan.exact_context_unrepresented = true;
            return plan;
        };
        let Some(creature) = self.represented_spell_click_creature_snapshot_like_cpp(creature_guid)
        else {
            return plan;
        };
        if !creature.is_in_world {
            return plan;
        }

        let click_bounds = spell_click_store.spell_click_info_map_bounds_like_cpp(creature.entry);
        if click_bounds.is_empty() {
            return plan;
        }

        let Some(clicker_object) = self.build_condition_player_object_like_cpp() else {
            plan.exact_context_unrepresented = true;
            return plan;
        };
        let mut target_object = WorldObject::new(
            false,
            TypeId::Unit,
            wow_constants::TypeMask::OBJECT | wow_constants::TypeMask::UNIT,
        );
        target_object.object_mut().create(creature.guid);
        target_object.object_mut().set_entry(creature.entry);
        let _ = target_object.set_map(creature.map_id, creature.instance_id);
        target_object.relocate(creature.position);
        *target_object.phase_shift_mut() = creature.phase_shift.clone();

        let player_unit_snapshot = self.condition_player_unit_snapshot_like_cpp();
        let player_snapshot = self.condition_player_snapshot_like_cpp();
        let creature_unit_snapshot = crate::conditions::ConditionUnitSnapshot {
            level: creature.level,
            health: creature.health,
            max_health: creature.max_health,
            class_mask: 0,
            race: 0,
            creature_type: None,
            is_alive: creature.is_alive,
            is_charmed: false,
            in_water: false,
            unit_state: 0,
            stand_state: UnitStandStateType::Stand as u32,
        };
        let player_condition_store = self.player_condition_store().cloned();
        let player_condition_context = self.represented_player_condition_context_like_cpp();
        let area_table_store = self.area_table_store.as_ref().cloned();

        for click_info in click_bounds {
            let requirements_fit = match click_info.user_type {
                SPELL_CLICK_USER_FRIEND_LIKE_CPP => {
                    if creature.is_summon
                        || self.faction_template_store.is_none()
                        || self.player_faction_template_like_cpp.is_none()
                    {
                        plan.exact_context_unrepresented = true;
                        continue;
                    }
                    let reaction = self.represented_get_reaction_to_like_cpp(
                        RepresentedGetReactionInputLikeCpp {
                            self_faction_template_id: self
                                .player_faction_template_like_cpp
                                .unwrap_or(0),
                            target_faction_template_id: creature.faction_template_id,
                            same_object: false,
                            attackable_by_summoner: false,
                            same_charmer_or_owner_or_self: false,
                            self_has_player_owner: true,
                            target_has_player_owner: false,
                            target_player_owner_is_current_session: false,
                            target_owner_forced_rank_for_self: None,
                            same_player_owner: false,
                            duel_in_progress: false,
                            same_raid: false,
                            self_unit_player_controlled: true,
                            target_unit_player_controlled: false,
                            self_ffa_pvp: false,
                            target_ffa_pvp: false,
                            self_ignores_reputation: false,
                            target_ignores_reputation: false,
                            target_is_unit: true,
                            target_player_contested_pvp: false,
                        },
                    );
                    reaction >= wow_data::reputation::ReputationRankLikeCpp::Friendly
                }
                SPELL_CLICK_USER_PARTY_LIKE_CPP | SPELL_CLICK_USER_RAID_LIKE_CPP => {
                    plan.exact_context_unrepresented = true;
                    continue;
                }
                _ => true,
            };
            if !requirements_fit {
                continue;
            }

            let conditions_match =
                crate::conditions::is_object_meeting_spell_click_conditions_like_cpp(
                    condition_store,
                    creature.entry,
                    click_info.spell_id,
                    Some(&clicker_object),
                    Some(&target_object),
                    |condition, source_info| {
                        source_info.set_unit_target_snapshot(0, player_unit_snapshot);
                        source_info.set_player_target_snapshot(0, player_snapshot);
                        source_info.set_unit_target_snapshot(1, creature_unit_snapshot);
                        if let Some(store) = player_condition_store.as_ref() {
                            source_info.set_player_condition_store(store.as_ref());
                            source_info.set_player_condition_context(
                                0,
                                player_condition_context.as_context(self),
                            );
                        }
                        crate::conditions::condition_meets_basic_like_cpp(
                            condition,
                            source_info,
                            |area_id, required_area_id| {
                                area_table_store.as_ref().is_some_and(|store| {
                                    store.is_in_area_like_cpp(area_id, required_area_id)
                                })
                            },
                        )
                        .value()
                        .unwrap_or(false)
                    },
                );
            if !conditions_match {
                continue;
            }

            let vehicle_seat_data = if let Some(seat_id) = seat_id {
                let Ok(spell_id) = i32::try_from(click_info.spell_id) else {
                    plan.exact_context_unrepresented = true;
                    continue;
                };
                let Some(spell_info) = self.spell_store().and_then(|store| store.get(spell_id))
                else {
                    plan.exact_context_unrepresented = true;
                    continue;
                };
                let Some(control_effect) = spell_info.effects().iter().find(|effect| {
                    effect.effect == wow_data::spell::spell_effect_types::SPELL_EFFECT_APPLY_AURA
                        && effect.effect_aura
                            == wow_data::spell::aura_types::SPELL_AURA_CONTROL_VEHICLE
                }) else {
                    continue;
                };
                Some((
                    control_effect.effect_index,
                    i32::from(seat_id) + 1,
                    i32::from(seat_id),
                ))
            } else {
                None
            };

            plan.casts.push(RepresentedSpellClickCastLikeCpp {
                spell_id: click_info.spell_id,
                caster: if (click_info.cast_flags & NPC_CLICK_CAST_CASTER_CLICKER_LIKE_CPP) != 0 {
                    RepresentedSpellClickUnitRefLikeCpp::Clicker
                } else {
                    RepresentedSpellClickUnitRefLikeCpp::Clickee
                },
                target: if (click_info.cast_flags & NPC_CLICK_CAST_TARGET_CLICKER_LIKE_CPP) != 0 {
                    RepresentedSpellClickUnitRefLikeCpp::Clicker
                } else {
                    RepresentedSpellClickUnitRefLikeCpp::Clickee
                },
                original_caster: if (click_info.cast_flags
                    & NPC_CLICK_CAST_ORIG_CASTER_OWNER_LIKE_CPP)
                    != 0
                {
                    RepresentedSpellClickUnitRefLikeCpp::Owner
                } else {
                    RepresentedSpellClickUnitRefLikeCpp::Clicker
                },
                cast_flags: click_info.cast_flags,
                vehicle_seat_id: seat_id,
                vehicle_control_effect_index: vehicle_seat_data
                    .map(|(effect_index, _, _)| effect_index),
                vehicle_spellmod_basepoint_value: vehicle_seat_data
                    .map(|(_, spellmod_value, _)| spellmod_value),
                vehicle_aura_fallback_basepoint_value: vehicle_seat_data
                    .map(|(_, _, fallback_value)| fallback_value),
            });
        }

        if creature.guid.is_any_type_creature() {
            plan.ai_on_spell_click_unrepresented = true;
        }
        plan
    }

    pub(crate) async fn execute_represented_spell_click_plan_like_cpp(
        &mut self,
        creature_guid: ObjectGuid,
        plan: &RepresentedSpellClickPlanLikeCpp,
    ) -> RepresentedSpellClickExecutionOutcomeLikeCpp {
        let Some(player_guid) = self.player_guid() else {
            return RepresentedSpellClickExecutionOutcomeLikeCpp {
                planned_casts: plan.casts.len(),
                failed_casts: plan.casts.len(),
                ..Default::default()
            };
        };
        let clickee_owner_guid = self
            .represented_spell_click_creature_snapshot_like_cpp(creature_guid)
            .and_then(|creature| creature.owner_guid);

        let mut outcome = RepresentedSpellClickExecutionOutcomeLikeCpp {
            planned_casts: plan.casts.len(),
            ..Default::default()
        };

        for cast in &plan.casts {
            if cast.vehicle_seat_id.is_some() {
                outcome.skipped_unrepresented_caster += 1;
                continue;
            }
            if cast.caster == RepresentedSpellClickUnitRefLikeCpp::Clickee {
                match self
                    .execute_represented_spell_click_clickee_caster_like_cpp(
                        creature_guid,
                        cast,
                        player_guid,
                        clickee_owner_guid,
                    )
                    .await
                {
                    RepresentedSpellClickClickeeCasterOutcomeLikeCpp::Executed => {
                        outcome.executed_casts += 1;
                    }
                    RepresentedSpellClickClickeeCasterOutcomeLikeCpp::UnsupportedCaster => {
                        outcome.skipped_unrepresented_caster += 1;
                    }
                    RepresentedSpellClickClickeeCasterOutcomeLikeCpp::UnsupportedTarget => {
                        outcome.skipped_unrepresented_target += 1;
                    }
                    RepresentedSpellClickClickeeCasterOutcomeLikeCpp::UnsupportedOriginalCaster => {
                        outcome.skipped_unrepresented_original_caster += 1;
                    }
                    RepresentedSpellClickClickeeCasterOutcomeLikeCpp::Failed => {
                        outcome.failed_casts += 1;
                    }
                }
                continue;
            }
            if cast.caster != RepresentedSpellClickUnitRefLikeCpp::Clicker {
                outcome.skipped_unrepresented_caster += 1;
                continue;
            }
            match cast.original_caster {
                RepresentedSpellClickUnitRefLikeCpp::Clicker => {}
                RepresentedSpellClickUnitRefLikeCpp::Owner
                    if clickee_owner_guid == Some(player_guid) => {}
                _ => {
                    outcome.skipped_unrepresented_original_caster += 1;
                    continue;
                }
            }

            let target_guid = match cast.target {
                RepresentedSpellClickUnitRefLikeCpp::Clicker => player_guid,
                RepresentedSpellClickUnitRefLikeCpp::Clickee => creature_guid,
                RepresentedSpellClickUnitRefLikeCpp::Owner => {
                    outcome.skipped_unrepresented_target += 1;
                    continue;
                }
            };
            let Ok(spell_id) = i32::try_from(cast.spell_id) else {
                outcome.failed_casts += 1;
                continue;
            };
            let cast_id = self.next_represented_spell_cast_guid_like_cpp(spell_id);

            let result = self
                .execute_spell_with_visual_and_target_data(
                    spell_id,
                    target_guid,
                    cast_id,
                    wow_packet::packets::spell::SpellCastVisual::default(),
                    SpellTargetData {
                        flags: 0x2,
                        unit: target_guid,
                        item: ObjectGuid::EMPTY,
                        ..SpellTargetData::default()
                    },
                )
                .await;
            if result.is_ok() {
                outcome.executed_casts += 1;
            } else {
                outcome.failed_casts += 1;
            }
        }

        if plan.ai_on_spell_click_unrepresented {
            let has_unrepresented_or_failed_casts = outcome.skipped_unrepresented_caster > 0
                || outcome.skipped_unrepresented_target > 0
                || outcome.skipped_unrepresented_original_caster > 0
                || outcome.failed_casts > 0;
            if outcome.executed_casts > 0 {
                let represented = if self
                    .mutate_world_creature(creature_guid, |creature| {
                        creature
                            .creature
                            .record_ai_spell_click_inform(player_guid, true);
                    })
                    .is_some()
                {
                    true
                } else {
                    self.mutate_canonical_creature_by_guid_like_cpp(creature_guid, |creature| {
                        creature.record_ai_spell_click_inform(player_guid, true);
                    })
                    .is_some()
                };
                outcome.ai_on_spell_click_represented = represented;
                outcome.ai_on_spell_click_unrepresented =
                    !represented || has_unrepresented_or_failed_casts;
            } else {
                outcome.ai_on_spell_click_unrepresented = true;
            }
        }

        outcome
    }

    async fn execute_represented_spell_click_clickee_caster_like_cpp(
        &mut self,
        creature_guid: ObjectGuid,
        cast: &RepresentedSpellClickCastLikeCpp,
        player_guid: ObjectGuid,
        clickee_owner_guid: Option<ObjectGuid>,
    ) -> RepresentedSpellClickClickeeCasterOutcomeLikeCpp {
        use wow_packet::packets::spell::{SpellCastVisual, SpellGoPkt, SpellTargetData};

        if cast.caster != RepresentedSpellClickUnitRefLikeCpp::Clickee {
            return RepresentedSpellClickClickeeCasterOutcomeLikeCpp::UnsupportedCaster;
        }
        let target_guid = match cast.target {
            RepresentedSpellClickUnitRefLikeCpp::Clicker => player_guid,
            RepresentedSpellClickUnitRefLikeCpp::Clickee => creature_guid,
            RepresentedSpellClickUnitRefLikeCpp::Owner => {
                return RepresentedSpellClickClickeeCasterOutcomeLikeCpp::UnsupportedTarget;
            }
        };
        match cast.original_caster {
            RepresentedSpellClickUnitRefLikeCpp::Clicker => {}
            RepresentedSpellClickUnitRefLikeCpp::Owner
                if clickee_owner_guid == Some(player_guid) => {}
            _ => {
                return RepresentedSpellClickClickeeCasterOutcomeLikeCpp::UnsupportedOriginalCaster;
            }
        }

        let Ok(spell_id) = i32::try_from(cast.spell_id) else {
            return RepresentedSpellClickClickeeCasterOutcomeLikeCpp::Failed;
        };
        let Some(spell_info) = self
            .spell_store()
            .and_then(|store| store.get(spell_id))
            .cloned()
        else {
            return RepresentedSpellClickClickeeCasterOutcomeLikeCpp::Failed;
        };
        let Some(damage_amount) =
            represented_spell_click_school_damage_amount_like_cpp(&spell_info)
        else {
            return RepresentedSpellClickClickeeCasterOutcomeLikeCpp::UnsupportedCaster;
        };

        let cast_id = self.next_represented_spell_cast_guid_like_cpp(spell_id);
        self.send_packet(&SpellGoPkt {
            caster: creature_guid,
            cast_id,
            original_cast_id: cast_id,
            spell_id,
            visual: SpellCastVisual::default(),
            cast_flags_ex: 0,
            target: SpellTargetData {
                flags: 0x2,
                unit: target_guid,
                item: ObjectGuid::EMPTY,
                ..SpellTargetData::default()
            },
            hit_targets: vec![target_guid],
        });

        let result = if target_guid == player_guid {
            self.apply_represented_spell_click_creature_damage_to_clicker_like_cpp(
                spell_id,
                player_guid,
                damage_amount,
            )
            .await
        } else {
            self.apply_represented_spell_click_creature_damage_to_clickee_like_cpp(
                spell_id,
                creature_guid,
                damage_amount,
            )
            .await
        };
        match result {
            Ok(()) => RepresentedSpellClickClickeeCasterOutcomeLikeCpp::Executed,
            Err(_) => RepresentedSpellClickClickeeCasterOutcomeLikeCpp::Failed,
        }
    }

    async fn apply_represented_spell_click_creature_damage_to_clicker_like_cpp(
        &mut self,
        spell_id: i32,
        player_guid: ObjectGuid,
        damage_amount: u32,
    ) -> Result<(), &'static str> {
        if self.player_guid() != Some(player_guid) {
            return Err("Target player not current session");
        }
        if !self.player_alive_like_cpp {
            debug!(
                account = self.account_id,
                player = ?player_guid,
                spell_id,
                damage = damage_amount,
                "Skipping spellclick creature-caster damage because C++ EffectSchoolDMG requires alive target"
            );
            return Ok(());
        }

        let original_health = self.player_health_like_cpp;
        let final_damage = damage_amount.min(original_health);
        self.player_health_like_cpp = self.player_health_like_cpp.saturating_sub(final_damage);
        if self.player_health_like_cpp == 0 {
            self.player_alive_like_cpp = false;
        }
        let health_after = self.player_health_like_cpp;
        let _ = self
            .sync_canonical_player_health_like_cpp(health_after, self.player_max_health_like_cpp);
        self.sync_player_registry_state_like_cpp();
        if self.player_health_like_cpp != original_health {
            self.send_player_health_update_like_cpp(
                player_guid,
                u64::from(self.player_health_like_cpp),
            );
        }

        Ok(())
    }

    async fn apply_represented_spell_click_creature_damage_to_clickee_like_cpp(
        &mut self,
        spell_id: i32,
        creature_guid: ObjectGuid,
        damage_amount: u32,
    ) -> Result<(), &'static str> {
        let account_id = self.account_id;
        let values_update = self
            .mutate_world_creature(creature_guid, |creature| {
                if !creature.is_alive() {
                    debug!(
                        account = account_id,
                        creature = ?creature_guid,
                        spell_id,
                        damage = damage_amount,
                        "Skipping spellclick creature-caster damage because C++ EffectSchoolDMG requires alive target"
                    );
                    return None;
                }
                let _died = creature.take_damage_before_death_state_like_cpp(damage_amount);
                Some(creature.creature.unit().values_update())
            })
            .ok_or("Target creature not found")?;
        let Some(values_update) = values_update else {
            return Ok(());
        };

        if self.client_visible_guids_like_cpp.contains(&creature_guid)
            && let Some(update) = self.represented_unit_values_update_to_update_object_like_cpp(
                creature_guid,
                self.player_map_id_like_cpp(),
                &values_update,
            )
        {
            self.send_packet(&update);
        }

        Ok(())
    }

    pub(crate) fn represented_viewer_dependent_creature_npc_flags_like_cpp(
        &self,
        creature_guid: ObjectGuid,
        npc_flags: u64,
    ) -> u64 {
        if (npc_flags & UNIT_NPC_FLAG_SPELLCLICK_LIKE_CPP) == 0 {
            return npc_flags;
        }

        match self.represented_can_see_spell_click_on_creature_like_cpp(creature_guid) {
            RepresentedCanSeeSpellClickOutcomeLikeCpp::Hidden => {
                npc_flags & !UNIT_NPC_FLAG_SPELLCLICK_LIKE_CPP
            }
            RepresentedCanSeeSpellClickOutcomeLikeCpp::Visible
            | RepresentedCanSeeSpellClickOutcomeLikeCpp::ExactContextUnrepresented => npc_flags,
        }
    }

    pub(crate) fn represented_unit_values_update_to_update_object_like_cpp(
        &self,
        unit_guid: ObjectGuid,
        map_id: u16,
        values_update: &wow_entities::UnitValuesUpdate,
    ) -> Option<wow_packet::packets::update::UpdateObject> {
        let packet_update = unit_values_update_to_packet(values_update)?;
        Some(
            self.represented_unit_packet_update_to_update_object_like_cpp(
                unit_guid,
                map_id,
                packet_update,
            ),
        )
    }

    pub(crate) fn represented_unit_packet_update_to_update_object_like_cpp(
        &self,
        unit_guid: ObjectGuid,
        map_id: u16,
        mut packet_update: wow_packet::packets::update::UnitDataValuesDeltaUpdate,
    ) -> wow_packet::packets::update::UpdateObject {
        if unit_guid.is_any_type_creature()
            && (packet_update.npc_flags[0] & UNIT_NPC_FLAG_SPELLCLICK_LIKE_CPP as u32) != 0
        {
            let npc_flags = u64::from(packet_update.npc_flags[0])
                | (u64::from(packet_update.npc_flags[1]) << 32);
            let filtered =
                self.represented_viewer_dependent_creature_npc_flags_like_cpp(unit_guid, npc_flags);
            packet_update.npc_flags[0] = filtered as u32;
            packet_update.npc_flags[1] = (filtered >> 32) as u32;
        }

        wow_packet::packets::update::UpdateObject::unit_values_update(
            unit_guid,
            map_id,
            packet_update,
        )
    }

    fn represented_has_quest_for_gameobject_like_cpp(&self, gameobject_entry: u32) -> bool {
        let Some(store) = self.quest_store.as_ref() else {
            return false;
        };
        let object_id = i32::try_from(gameobject_entry).unwrap_or(i32::MAX);
        self.player_quests.values().any(|status| {
            if status.status != crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP {
                return false;
            }
            let Some(quest) = store.get(status.quest_id) else {
                return false;
            };
            quest
                .objectives
                .iter()
                .enumerate()
                .any(|(index, objective)| {
                    objective.obj_type == 2
                        && objective.object_id == object_id
                        && Self::represented_quest_objective_completable_like_cpp(
                            status, quest, index,
                        )
                        && !Self::represented_quest_objective_complete_like_cpp(
                            status, quest, objective,
                        )
                })
        })
    }

    pub(crate) fn record_represented_gameobject_template_quest_source_like_cpp(
        &mut self,
        guid: ObjectGuid,
        template: &wow_entities::GameObjectTemplateData,
    ) {
        let state = self
            .represented_gameobject_use_states
            .entry(guid)
            .or_default();
        if let Some(source) = template.chest_loot_source_like_cpp() {
            state.chest_loot_source = Some(source);
        }
        if let Some(source) = template.gathering_node_use_source_like_cpp() {
            state.gathering_node_loot_id = Some(source.loot_id);
        }
        state.condition_id1 = (template.get_condition_id1_like_cpp() != 0)
            .then_some(template.get_condition_id1_like_cpp());
    }

    fn represented_gameobject_loot_ids_have_quest_loot_like_cpp(
        &self,
        loot_ids: impl IntoIterator<Item = u32>,
    ) -> bool {
        let Some(stores) = self.loot_stores.as_ref() else {
            return false;
        };
        let Some(store) = stores.get(&LootStoreKind::Gameobject) else {
            return false;
        };
        loot_ids
            .into_iter()
            .filter(|id| *id != 0)
            .any(|loot_id| store.have_quest_loot_for_like_cpp(loot_id, stores.as_ref()))
    }

    fn represented_gameobject_loot_ids_have_quest_loot_for_player_like_cpp(
        &self,
        loot_ids: impl IntoIterator<Item = u32>,
    ) -> bool {
        let Some(stores) = self.loot_stores.as_ref() else {
            return false;
        };
        let Some(store) = stores.get(&LootStoreKind::Gameobject) else {
            return false;
        };
        loot_ids.into_iter().filter(|id| *id != 0).any(|loot_id| {
            store.have_quest_loot_for_player_like_cpp(loot_id, stores.as_ref(), |item_id| {
                self.represented_player_has_quest_for_loot_item_like_cpp(item_id)
            })
        })
    }

    fn represented_gameobject_chest_loot_ids_like_cpp(
        source: wow_entities::GameObjectLootSource,
    ) -> [u32; 3] {
        [source.loot_id, source.personal_loot_id, source.push_loot_id]
    }

    fn represented_player_has_quest_for_loot_item_like_cpp(&self, item_id: u32) -> bool {
        self.represented_current_player_has_incomplete_quest_objective_for_item_like_cpp(item_id)
            || self
                .item_template_addon_quest_log_item_id_like_cpp(item_id)
                .is_some_and(|quest_log_item_id| {
                    quest_log_item_id != 0
                        && self
                            .represented_current_player_has_incomplete_quest_objective_for_object_id_like_cpp(
                            i32::try_from(quest_log_item_id).unwrap_or(i32::MAX),
                        )
                })
            || self.represented_current_player_has_incomplete_quest_item_drop_for_item_like_cpp(item_id)
    }

    fn represented_current_player_has_incomplete_quest_objective_for_item_like_cpp(
        &self,
        item_id: u32,
    ) -> bool {
        let Ok(item_object_id) = i32::try_from(item_id) else {
            return false;
        };
        self.represented_current_player_has_incomplete_quest_objective_for_object_id_like_cpp(
            item_object_id,
        )
    }

    fn represented_current_player_has_incomplete_quest_objective_for_object_id_like_cpp(
        &self,
        object_id: i32,
    ) -> bool {
        let Some(quest_store) = self.quest_store.as_ref() else {
            return false;
        };
        self.player_quests.values().any(|status| {
            if status.status != crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP {
                return false;
            }
            let Some(quest) = quest_store.get(status.quest_id) else {
                return false;
            };
            quest
                .objectives
                .iter()
                .enumerate()
                .any(|(fallback_index, objective)| {
                    if objective.obj_type != QUEST_OBJECTIVE_ITEM_LIKE_CPP
                        || objective.object_id != object_id
                    {
                        return false;
                    }
                    let storage_index = usize::try_from(objective.storage_index)
                        .ok()
                        .unwrap_or(fallback_index);
                    let current = status
                        .objective_counts
                        .get(storage_index)
                        .copied()
                        .unwrap_or(0);
                    current < objective.amount.max(1)
                })
        })
    }

    fn represented_current_player_has_incomplete_quest_item_drop_for_item_like_cpp(
        &self,
        item_id: u32,
    ) -> bool {
        let Some(quest_store) = self.quest_store.as_ref() else {
            return false;
        };
        self.player_quests.values().any(|status| {
            if status.status != crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP {
                return false;
            }
            let Some(quest) = quest_store.get(status.quest_id) else {
                return false;
            };
            quest
                .item_drop
                .iter()
                .enumerate()
                .any(|(index, drop_item_id)| {
                    if *drop_item_id != item_id {
                        return false;
                    }
                    let Some(template) = self.item_storage_template(item_id) else {
                        return false;
                    };
                    let quantity = quest.item_drop_quantity[index];
                    let mut max_allowed_count = if quantity != 0 {
                        quantity
                    } else {
                        template.max_stack_size
                    };
                    if template.max_count > 0 {
                        max_allowed_count = max_allowed_count.min(template.max_count as u32);
                    }
                    self.represented_inventory_item_counts_like_cpp()
                        .get(&item_id)
                        .copied()
                        .unwrap_or(0)
                        < max_allowed_count
                })
        })
    }

    fn represented_gameobject_is_for_quests_like_cpp(
        &self,
        gameobject_entry: u32,
        state: &RepresentedGameObjectUseState,
    ) -> bool {
        match state.go_type.map(u32::from) {
            Some(wow_entities::GAMEOBJECT_TYPE_QUESTGIVER) => true,
            // C++ anchor: /home/server/woltk-trinity-legacy/src/server/game/Globals/ObjectMgr.cpp:8791-8800
            Some(wow_entities::GAMEOBJECT_TYPE_CHEST) => {
                self.represented_has_quest_for_gameobject_like_cpp(gameobject_entry)
                    || state
                        .chest_loot_source
                        .is_some_and(|source| source.chest_quest_id != 0)
                    || state.chest_loot_source.is_some_and(|source| {
                        self.represented_gameobject_loot_ids_have_quest_loot_like_cpp(
                            Self::represented_gameobject_chest_loot_ids_like_cpp(source),
                        )
                    })
            }
            Some(wow_entities::GAMEOBJECT_TYPE_GENERIC) => {
                self.represented_has_quest_for_gameobject_like_cpp(gameobject_entry)
            }
            Some(wow_entities::GAMEOBJECT_TYPE_GOOBER) => state
                .goober_use_source
                .is_some_and(|source| source.quest_id != 0),
            Some(wow_entities::GAMEOBJECT_TYPE_GATHERING_NODE) => self
                .represented_gameobject_loot_ids_have_quest_loot_like_cpp(
                    state.gathering_node_loot_id,
                ),
            _ => false,
        }
    }

    fn represented_gameobject_activate_to_quest_like_cpp(
        &self,
        gameobject_entry: u32,
        state: &RepresentedGameObjectUseState,
    ) -> bool {
        if self.represented_has_quest_for_gameobject_like_cpp(gameobject_entry) {
            return true;
        }

        if !self.represented_gameobject_is_for_quests_like_cpp(gameobject_entry, state) {
            return false;
        }

        match state.go_type.map(u32::from) {
            Some(wow_entities::GAMEOBJECT_TYPE_QUESTGIVER) => {
                let status = self.get_represented_quest_giver_status_like_cpp(
                    crate::handlers::quest::RepresentedQuestGiverStatusSourceLikeCpp::GameObject {
                        entry: gameobject_entry,
                    },
                );
                status != wow_packet::packets::quest::quest_giver_status::NONE
                    && status != wow_packet::packets::quest::quest_giver_status::FUTURE
            }
            // C++ anchor: /home/server/woltk-trinity-legacy/src/server/game/Entities/GameObject/GameObject.cpp:2236-2251
            Some(wow_entities::GAMEOBJECT_TYPE_CHEST) => {
                state.loot_state != Some(wow_entities::LootState::NotReady)
                    && (state.chest_loot_source.is_some_and(|source| {
                        source.chest_quest_id != 0
                            && self
                                .player_quests
                                .get(&source.chest_quest_id)
                                .is_some_and(|s| {
                                    s.status == crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP
                                })
                    }) || state.chest_loot_source.is_some_and(|source| {
                        self.represented_gameobject_loot_ids_have_quest_loot_for_player_like_cpp(
                            Self::represented_gameobject_chest_loot_ids_like_cpp(source),
                        )
                    }))
            }
            Some(wow_entities::GAMEOBJECT_TYPE_GENERIC) => {
                self.represented_has_quest_for_gameobject_like_cpp(gameobject_entry)
            }
            Some(wow_entities::GAMEOBJECT_TYPE_GOOBER) => {
                state
                    .goober_use_source
                    .is_some_and(|source| source.quest_id != 0)
                    && state.goober_use_source.is_some_and(|source| {
                        self.player_quests
                            .get(&source.quest_id)
                            .is_some_and(|status| {
                                status.status == crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP
                            })
                    })
            }
            Some(wow_entities::GAMEOBJECT_TYPE_GATHERING_NODE) => self
                .represented_gameobject_loot_ids_have_quest_loot_for_player_like_cpp(
                    state.gathering_node_loot_id,
                ),
            _ => false,
        }
    }

    pub(crate) fn represented_gameobject_dynamic_flags_for_player_like_cpp(
        &self,
        gameobject_entry: u32,
        state: &RepresentedGameObjectUseState,
    ) -> u32 {
        let mut dyn_flags = 0_u32;
        let path_progress = (state.dynamic_flags >> 16) & 0xFFFF;
        let activate_to_quest =
            self.represented_gameobject_activate_to_quest_like_cpp(gameobject_entry, state);

        match state.go_type.map(u32::from) {
            Some(wow_entities::GAMEOBJECT_TYPE_QUESTGIVER) => {
                if activate_to_quest {
                    dyn_flags |= wow_entities::GO_DYNFLAG_LO_ACTIVATE;
                }
            }
            Some(wow_entities::GAMEOBJECT_TYPE_CHEST) => {
                if activate_to_quest {
                    dyn_flags |= wow_entities::GO_DYNFLAG_LO_ACTIVATE
                        | wow_entities::GO_DYNFLAG_LO_SPARKLE
                        | wow_entities::GO_DYNFLAG_LO_HIGHLIGHT;
                } else if self.player_game_master_like_cpp {
                    dyn_flags |= wow_entities::GO_DYNFLAG_LO_ACTIVATE;
                }
            }
            Some(wow_entities::GAMEOBJECT_TYPE_GOOBER) => {
                if activate_to_quest {
                    dyn_flags |= wow_entities::GO_DYNFLAG_LO_HIGHLIGHT;
                    let state_for_player = self
                        .represented_gameobject_go_state_for_viewer_like_cpp(state, Instant::now());
                    if state_for_player != wow_entities::GoState::Active {
                        dyn_flags |= wow_entities::GO_DYNFLAG_LO_ACTIVATE;
                    }
                } else if self.player_game_master_like_cpp {
                    dyn_flags |= wow_entities::GO_DYNFLAG_LO_ACTIVATE;
                }
            }
            Some(wow_entities::GAMEOBJECT_TYPE_GENERIC) => {
                if activate_to_quest {
                    dyn_flags |=
                        wow_entities::GO_DYNFLAG_LO_SPARKLE | wow_entities::GO_DYNFLAG_LO_HIGHLIGHT;
                }
            }
            Some(wow_entities::GAMEOBJECT_TYPE_GATHERING_NODE) => {
                if activate_to_quest {
                    dyn_flags |= wow_entities::GO_DYNFLAG_LO_ACTIVATE
                        | wow_entities::GO_DYNFLAG_LO_SPARKLE
                        | wow_entities::GO_DYNFLAG_LO_HIGHLIGHT;
                }
                let state_for_player =
                    self.represented_gameobject_go_state_for_viewer_like_cpp(state, Instant::now());
                if state_for_player == wow_entities::GoState::Active {
                    dyn_flags |= wow_entities::GO_DYNFLAG_LO_DEPLETED;
                }
            }
            _ => {
                dyn_flags = state.dynamic_flags & 0xFFFF;
            }
        }

        if state
            .condition_id1
            .is_some_and(|id| !self.represented_meets_player_condition_id_like_cpp(id))
        {
            dyn_flags |= wow_entities::GO_DYNFLAG_LO_NO_INTERACT;
        }

        (path_progress << 16) | dyn_flags
    }

    fn represented_gameobject_dynamic_flags_update_like_cpp(
        guid: ObjectGuid,
        map_id: u16,
        dynamic_flags: u32,
    ) -> Option<wow_packet::packets::update::UpdateObject> {
        let mut mask = wow_entities::UpdateMask::new(wow_entities::OBJECT_DATA_BITS);
        mask.set(wow_entities::OBJECT_DATA_PARENT_BIT);
        mask.set(wow_entities::OBJECT_DATA_DYNAMIC_FLAGS_BIT);
        let values_update = wow_entities::GameObjectValuesUpdate {
            changed_object_type_mask: 1 << wow_entities::TYPEID_OBJECT,
            object_data: Some(wow_entities::ObjectDataUpdate {
                mask,
                values: wow_entities::ObjectDataValues {
                    entry_id: 0,
                    dynamic_flags,
                    scale: 0.0,
                },
            }),
            game_object_data: None,
        };
        game_object_values_update_to_update_object(guid, map_id, &values_update)
    }

    pub(crate) fn update_visible_gameobjects_like_cpp(&mut self) -> usize {
        let mut sent = 0;
        let visible_guids = self
            .client_visible_guids_like_cpp
            .iter()
            .copied()
            .collect::<Vec<_>>();
        for guid in visible_guids {
            if !guid.is_game_object() {
                continue;
            }
            let Some(access) = self.canonical_gameobject_access_like_cpp(guid) else {
                continue;
            };
            let Some(state) = self.represented_gameobject_use_states.get(&guid).cloned() else {
                continue;
            };
            let objective_refresh =
                self.represented_has_quest_for_gameobject_like_cpp(access.entry);
            let relation_refresh =
                self.represented_gameobject_is_for_quests_like_cpp(access.entry, &state);
            if !objective_refresh && !relation_refresh {
                continue;
            }

            let dynamic_flags =
                self.represented_gameobject_dynamic_flags_for_player_like_cpp(access.entry, &state);
            let Some(update) = Self::represented_gameobject_dynamic_flags_update_like_cpp(
                guid,
                self.player_map_id_like_cpp(),
                dynamic_flags,
            ) else {
                continue;
            };
            self.send_packet(&update);
            sent += 1;
        }

        sent
    }

    pub(crate) fn update_visible_gameobjects_or_spell_clicks_like_cpp(&mut self) -> usize {
        self.update_visible_gameobjects_like_cpp() + self.update_visible_spell_clicks_like_cpp()
    }

    pub(crate) fn update_visible_spell_clicks_like_cpp(&mut self) -> usize {
        let Some(spell_click_store) = self.npc_spell_click_store.as_ref() else {
            return 0;
        };
        let Some(condition_store) = self.condition_store.as_ref() else {
            return 0;
        };

        let mut sent = 0;
        let visible_guids = self
            .client_visible_guids_like_cpp
            .iter()
            .copied()
            .collect::<Vec<_>>();
        for guid in visible_guids {
            if !guid.is_creature_or_vehicle() {
                continue;
            }
            let Some(creature) = self.represented_spell_click_creature_snapshot_like_cpp(guid)
            else {
                continue;
            };
            if (u64::from(creature.npc_flags) & UNIT_NPC_FLAG_SPELLCLICK_LIKE_CPP) == 0 {
                continue;
            }
            let click_bounds =
                spell_click_store.spell_click_info_map_bounds_like_cpp(creature.entry);
            if !click_bounds.iter().any(|click| {
                crate::conditions::has_conditions_for_spell_click_event_like_cpp(
                    condition_store,
                    creature.entry,
                    click.spell_id,
                )
            }) {
                continue;
            }

            let mut packet_update =
                wow_packet::packets::update::UnitDataValuesDeltaUpdate::default();
            packet_update.changed_object_type_mask = 1 << wow_entities::TYPEID_UNIT;
            packet_update.unit_data_mask[113 / 32] |= 1 << (113 % 32);
            packet_update.unit_data_mask[114 / 32] |= 1 << (114 % 32);
            packet_update.npc_flags = [creature.npc_flags, 0];
            let update = self.represented_unit_packet_update_to_update_object_like_cpp(
                guid,
                self.player_map_id_like_cpp(),
                packet_update,
            );
            self.send_packet(&update);
            sent += 1;
        }

        sent
    }

    pub(crate) fn represented_npc_can_interact_with_like_cpp(
        &self,
        guid: ObjectGuid,
        npc_flags: u32,
        npc_flags2: u32,
    ) -> Option<RepresentedCreatureAccessLikeCpp> {
        if guid.is_empty() || !guid.is_any_type_creature() {
            return None;
        }
        let player_guid = self.player_guid()?;
        let player_position = self.player_position_like_cpp()?;
        let target_player_contested_pvp = self
            .canonical_player_has_player_flag_like_cpp(
                player_guid,
                PLAYER_FLAGS_CONTESTED_PVP_LIKE_CPP,
            )
            .unwrap_or(false);
        let player_interaction_combat_reach = self.player_interaction_combat_reach_like_cpp();
        if self.taxi_flight_state_like_cpp.is_some() {
            return None;
        }

        let player_map_key = self
            .current_canonical_player_map_key_like_cpp()
            .unwrap_or_else(|| wow_map::MapKey::new(u32::from(self.player_map_id_like_cpp()), 0));
        let mut canonical_record_found_like_cpp = false;
        let mut canonical_fail_closed_like_cpp = false;
        let canonical_access = (|| {
            let manager = self.canonical_map_manager.as_ref()?;
            let Ok(manager) = manager.lock() else {
                return None;
            };
            let map = manager.find_map(player_map_key.map_id, player_map_key.instance_id)?;
            if map
                .map()
                .get_typed_player(player_guid)
                .is_some_and(|player| !player.unit().world().object().is_in_world())
            {
                canonical_fail_closed_like_cpp = true;
                return None;
            }
            let record = map.map().map_object_record(guid)?;
            canonical_record_found_like_cpp = true;
            let creature = if guid.is_pet() {
                record.pet()?.creature()
            } else {
                record.creature()?
            };

            let type_flags =
                CreatureTypeFlags::from_bits_retain(creature.lifecycle_metadata().type_flags);
            if !self.player_is_alive_like_cpp()
                && !type_flags.contains(CreatureTypeFlags::VISIBLE_TO_GHOSTS)
            {
                return None;
            }
            if !creature.is_alive() && !type_flags.contains(CreatureTypeFlags::INTERACT_WHILE_DEAD)
            {
                return None;
            }
            if (npc_flags != 0 || npc_flags2 != 0)
                && (creature.ai_ownership().npc_flags & npc_flags) == 0
                && (creature.ai_ownership().npc_flags2 & npc_flags2) == 0
            {
                return None;
            }
            if creature.unit().subsystems().control.charmer_guid.is_some() {
                return None;
            }
            let unit_flags2 = creature.unit().unit_flags2_like_cpp();
            if !unit_flags2.contains(UnitFlags2::INTERACT_WHILE_HOSTILE) {
                let reaction =
                    self.represented_get_reaction_to_like_cpp(RepresentedGetReactionInputLikeCpp {
                        self_faction_template_id: creature.unit().data().faction_template.max(0)
                            as u32,
                        target_faction_template_id: self
                            .player_faction_template_like_cpp
                            .unwrap_or(0),
                        same_object: false,
                        attackable_by_summoner: false,
                        same_charmer_or_owner_or_self: false,
                        self_has_player_owner: false,
                        target_has_player_owner: true,
                        target_player_owner_is_current_session: true,
                        target_owner_forced_rank_for_self: None,
                        same_player_owner: false,
                        duel_in_progress: false,
                        same_raid: false,
                        self_unit_player_controlled: false,
                        target_unit_player_controlled: true,
                        self_ffa_pvp: false,
                        target_ffa_pvp: false,
                        self_ignores_reputation: false,
                        target_ignores_reputation: false,
                        target_is_unit: true,
                        target_player_contested_pvp,
                    });
                if reaction <= wow_data::reputation::ReputationRankLikeCpp::Unfriendly {
                    return None;
                }
            }

            let interaction_distance = creature.unit().world().combat_reach() + 4.0;
            let in_range = if let Some(player) = map.map().get_typed_player(player_guid) {
                creature.unit().world().is_within_dist_in_map(
                    player.unit().world(),
                    interaction_distance,
                    true,
                )
            } else {
                let fallback_distance = interaction_distance
                    + creature.unit().world().combat_reach()
                    + player_interaction_combat_reach;
                creature
                    .unit()
                    .world()
                    .position()
                    .is_within_dist(&player_position, fallback_distance)
            };
            if !in_range {
                return None;
            }

            Some(RepresentedCreatureAccessLikeCpp {
                entry: creature.entry(),
                position: creature.unit().world().position(),
                npc_flags: creature.ai_ownership().npc_flags,
                npc_flags2: creature.ai_ownership().npc_flags2,
                trainer_class: creature.trainer_class_like_cpp(),
                faction_template_id: creature.unit().data().faction_template.max(0) as u32,
            })
        })();
        if canonical_access.is_some() {
            return canonical_access;
        }
        if canonical_record_found_like_cpp || canonical_fail_closed_like_cpp {
            return None;
        }

        self.represented_legacy_npc_can_interact_with_like_cpp(
            guid,
            npc_flags,
            npc_flags2,
            player_position,
            player_map_key.instance_id,
            player_interaction_combat_reach,
            target_player_contested_pvp,
        )
    }

    fn represented_legacy_npc_can_interact_with_like_cpp(
        &self,
        guid: ObjectGuid,
        npc_flags: u32,
        npc_flags2: u32,
        player_position: Position,
        player_instance_id: u32,
        player_interaction_combat_reach: f32,
        target_player_contested_pvp: bool,
    ) -> Option<RepresentedCreatureAccessLikeCpp> {
        let manager = self.map_manager.as_ref()?;
        let manager = manager
            .read()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let creature =
            manager.find_creature(self.player_map_id_like_cpp(), player_instance_id, guid)?;
        let type_flags =
            CreatureTypeFlags::from_bits_retain(creature.creature.lifecycle_metadata().type_flags);
        if !self.player_is_alive_like_cpp()
            && !type_flags.contains(CreatureTypeFlags::VISIBLE_TO_GHOSTS)
        {
            return None;
        }
        if !creature.is_alive() && !type_flags.contains(CreatureTypeFlags::INTERACT_WHILE_DEAD) {
            return None;
        }
        if (npc_flags != 0 || npc_flags2 != 0)
            && (creature.npc_flags() & npc_flags) == 0
            && (creature.npc_flags2() & npc_flags2) == 0
        {
            return None;
        }
        if creature
            .creature
            .unit()
            .subsystems()
            .control
            .charmer_guid
            .is_some()
        {
            return None;
        }
        if !creature
            .unit_flags2_like_cpp()
            .contains(UnitFlags2::INTERACT_WHILE_HOSTILE)
        {
            let reaction =
                self.represented_get_reaction_to_like_cpp(RepresentedGetReactionInputLikeCpp {
                    self_faction_template_id: creature.faction(),
                    target_faction_template_id: self.player_faction_template_like_cpp.unwrap_or(0),
                    same_object: false,
                    attackable_by_summoner: false,
                    same_charmer_or_owner_or_self: false,
                    self_has_player_owner: false,
                    target_has_player_owner: true,
                    target_player_owner_is_current_session: true,
                    target_owner_forced_rank_for_self: None,
                    same_player_owner: false,
                    duel_in_progress: false,
                    same_raid: false,
                    self_unit_player_controlled: false,
                    target_unit_player_controlled: true,
                    self_ffa_pvp: false,
                    target_ffa_pvp: false,
                    self_ignores_reputation: false,
                    target_ignores_reputation: false,
                    target_is_unit: true,
                    target_player_contested_pvp,
                });
            if reaction <= wow_data::reputation::ReputationRankLikeCpp::Unfriendly {
                return None;
            }
        }
        let interaction_distance = creature.creature.unit().world().combat_reach() + 4.0;
        let interaction_distance_with_radii = interaction_distance
            + creature.creature.unit().world().combat_reach()
            + player_interaction_combat_reach;
        if !creature
            .position()
            .is_within_dist(&player_position, interaction_distance_with_radii)
        {
            return None;
        }

        Some(RepresentedCreatureAccessLikeCpp {
            entry: creature.entry(),
            position: creature.position(),
            npc_flags: creature.npc_flags(),
            npc_flags2: creature.npc_flags2(),
            trainer_class: creature.trainer_class_like_cpp(),
            faction_template_id: creature.faction(),
        })
    }

    pub(crate) fn represented_gameobject_is_per_player_despawned_like_cpp(
        &mut self,
        guid: ObjectGuid,
    ) -> bool {
        let Some(state) = self.represented_gameobject_use_states.get_mut(&guid) else {
            return false;
        };
        match state.per_player_despawn_until {
            Some(until) if until > Instant::now() => true,
            Some(_) => {
                state.per_player_despawn_until = None;
                state.per_player_despawn_secs = None;
                state.per_player_state_player_guid = None;
                false
            }
            None => false,
        }
    }

    #[allow(dead_code)]
    pub(crate) fn record_represented_gameobject_owner_guid_like_cpp(
        &mut self,
        guid: ObjectGuid,
        owner_guid: ObjectGuid,
    ) {
        let owner_guid = (!owner_guid.is_empty()).then_some(owner_guid);
        self.represented_gameobject_use_states
            .entry(guid)
            .or_default()
            .owner_guid = owner_guid;

        let Some(owner_guid) = owner_guid else {
            return;
        };
        let Some(manager) = self.canonical_map_manager.as_ref() else {
            return;
        };
        let Ok(mut manager) = manager.lock() else {
            return;
        };
        let Some(map) = manager.find_map_mut(u32::from(self.player_map_id_like_cpp()), 0) else {
            return;
        };
        if let Some(game_object) = map.map_mut().get_typed_game_object_mut(guid) {
            game_object.set_created_by(owner_guid);
        }
    }

    fn set_canonical_gameobject_spell_id_like_cpp(&mut self, guid: ObjectGuid, spell_id: u32) {
        let Some(manager) = self.canonical_map_manager.as_ref() else {
            return;
        };
        let Ok(mut manager) = manager.lock() else {
            return;
        };
        let Some(map) = manager.find_map_mut(u32::from(self.player_map_id_like_cpp()), 0) else {
            return;
        };
        if let Some(game_object) = map.map_mut().get_typed_game_object_mut(guid) {
            game_object.set_spell_id(spell_id);
        }
    }

    fn represented_or_canonical_gameobject_owner_guid_like_cpp(
        &self,
        guid: ObjectGuid,
    ) -> Option<ObjectGuid> {
        let canonical_owner = self
            .canonical_map_manager
            .as_ref()
            .and_then(|manager| manager.lock().ok())
            .and_then(|manager| {
                manager
                    .find_map(u32::from(self.player_map_id_like_cpp()), 0)
                    .and_then(|map| map.map().get_typed_game_object(guid))
                    .map(|game_object| game_object.owner_guid())
            })
            .filter(|owner_guid| !owner_guid.is_empty());
        canonical_owner.or_else(|| {
            self.represented_gameobject_use_states
                .get(&guid)
                .and_then(|state| state.owner_guid)
        })
    }

    #[allow(dead_code)]
    pub(crate) fn record_represented_gameobject_spell_id_like_cpp(
        &mut self,
        guid: ObjectGuid,
        spell_id: u32,
    ) {
        self.set_canonical_gameobject_spell_id_like_cpp(guid, spell_id);
    }

