    fn represented_can_receive_creature_message_to_set_like_cpp(
        &self,
        guid: ObjectGuid,
        creature: &crate::map_manager::WorldCreature,
        required_3d: bool,
    ) -> bool {
        if !self.client_visible_guids_like_cpp.contains(&guid) {
            return false;
        }

        let Some(player_position) = self.player_position_like_cpp() else {
            return false;
        };
        let player_map_id = u32::from(self.player_map_id_like_cpp());
        let player_instance_id = self
            .current_canonical_player_map_key_like_cpp()
            .map(|key| key.instance_id)
            .unwrap_or(0);

        Self::creature_message_to_set_target_allows_like_cpp(
            guid,
            creature,
            &self.client_visible_guids_like_cpp,
            player_map_id,
            player_instance_id,
            &player_position,
            self.represented_player_phase_shift_like_cpp(),
            required_3d,
        )
    }

    fn creature_message_to_set_target_allows_like_cpp(
        guid: ObjectGuid,
        creature: &crate::map_manager::WorldCreature,
        visible_guids: &std::collections::HashSet<ObjectGuid>,
        player_map_id: u32,
        player_instance_id: u32,
        player_position: &Position,
        player_phase_shift: &PhaseShift,
        required_3d: bool,
    ) -> bool {
        if !visible_guids.contains(&guid) {
            return false;
        }
        if creature.map_id() != player_map_id || creature.instance_id() != player_instance_id {
            return false;
        }
        if !player_phase_shift.can_see(creature.phase_shift()) {
            return false;
        }

        let range = creature.visibility_range_like_cpp();
        if required_3d {
            position_is_in_dist_strict_3d_like_cpp(&creature.position(), player_position, range)
        } else {
            position_is_in_dist_strict_2d_like_cpp(&creature.position(), player_position, range)
        }
    }

    pub(crate) fn represented_can_receive_creature_message_to_set_by_guid_like_cpp(
        &self,
        guid: ObjectGuid,
        map_id: u16,
        instance_id: u32,
        required_3d: bool,
    ) -> Option<bool> {
        if let Some(manager) = &self.canonical_map_manager {
            let creature = {
                let manager = manager.lock().ok()?;
                let map = manager.find_map(u32::from(map_id), instance_id)?;
                let creature = map.map().get_typed_creature(guid)?;
                let world = creature.unit().world();
                if world.map_id() != u32::from(map_id) || world.instance_id() != instance_id {
                    return Some(false);
                }
                let create_data =
                    crate::map_manager::WorldCreature::create_data_from_canonical_like_cpp(
                        creature,
                    );
                crate::map_manager::WorldCreature::from_canonical(creature.clone(), create_data)
            };
            return Some(
                self.represented_can_receive_creature_message_to_set_like_cpp(
                    guid,
                    &creature,
                    required_3d,
                ),
            );
        }

        let creature = {
            let manager = self.map_manager.as_ref()?;
            manager
                .read()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .find_creature(map_id, instance_id, guid)
                .cloned()
        }?;
        Some(
            self.represented_can_receive_creature_message_to_set_like_cpp(
                guid,
                &creature,
                required_3d,
            ),
        )
    }

    pub(crate) fn visible_gameobjects_from_canonical_map_like_cpp(
        &self,
        map_id: u16,
        position: &wow_core::Position,
        visibility_radius: f32,
    ) -> Option<Vec<wow_packet::packets::update::GameObjectCreateData>> {
        let requested_map_id = u32::from(map_id);
        let player_map_key = self.current_canonical_player_map_key_like_cpp();
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = match player_map_key {
            Some(key) if key.map_id == requested_map_id => {
                manager.find_map(key.map_id, key.instance_id)?
            }
            Some(_) => return None,
            None => manager.find_map(requested_map_id, 0)?,
        };
        let nearby =
            map.map()
                .nearby_cell_guids_like_cpp(position.x, position.y, visibility_radius);
        let now = Instant::now();
        let mut gameobjects = Vec::new();

        for guid in nearby.grid.gameobjects {
            let Some(gameobject) = map.map().get_typed_game_object(guid) else {
                continue;
            };
            let object = gameobject.world();
            if !object.object().is_in_world()
                || object.map_id() != u32::from(map_id)
                || !object
                    .position()
                    .is_within_dist_2d(position, visibility_radius)
            {
                continue;
            }
            if let Some(phase_shift) = self.represented_gameobject_phase_shifts.get(&guid)
                && !self.can_see_phase_shift_like_cpp(phase_shift)
            {
                continue;
            }
            let state = self.represented_gameobject_use_states.get(&guid);
            if state.is_some_and(|state| {
                state
                    .per_player_despawn_until
                    .is_some_and(|until| until > now)
            }) {
                continue;
            }

            let create_data = if let Some(state) = state {
                let Some(display_id) = state.display_id else {
                    continue;
                };
                let Some(go_type) = state.go_type else {
                    continue;
                };
                let state_for_viewer =
                    self.represented_gameobject_go_state_for_viewer_like_cpp(state, now);

                wow_packet::packets::update::GameObjectCreateData {
                    guid,
                    entry: object.object().entry(),
                    dynamic_flags: self.represented_gameobject_dynamic_flags_for_player_like_cpp(
                        object.object().entry(),
                        state,
                    ),
                    display_id,
                    go_type,
                    position: object.position(),
                    rotation: state.rotation,
                    anim_progress: 255,
                    state: state_for_viewer as i8,
                    created_by: state.owner_guid.unwrap_or(ObjectGuid::EMPTY),
                    faction_template: state.faction_template.unwrap_or(0) as i32,
                    gameobject_flags: state.gameobject_flags,
                    world_effect_id: 0,
                    scale: state.scale,
                    level: 0, // non-transport GameObject: Level unused (period via AnimationData)
                    // Canonical state path does not yet record per-spawn ParentRotation;
                    // identity until state population is added (#NEXT.R8.ENTITIES.1216 follow-up).
                    parent_rotation: [0.0, 0.0, 0.0, 1.0],
                }
            } else {
                let Some(create_data) =
                    self.gameobject_create_data_from_canonical_like_cpp(guid, gameobject)
                else {
                    continue;
                };
                create_data
            };

            gameobjects.push(create_data);
        }

        Some(gameobjects)
    }

    fn represented_gameobject_go_state_for_viewer_like_cpp(
        &self,
        state: &RepresentedGameObjectUseState,
        now: Instant,
    ) -> wow_entities::GoState {
        if state.per_player_state_player_guid == self.player_guid()
            && state
                .per_player_go_state_until
                .is_none_or(|until| until > now)
            && let Some(per_player_go_state) = state.per_player_go_state
        {
            return per_player_go_state;
        }

        state.go_state.unwrap_or(wow_entities::GoState::Ready)
    }

    fn gameobject_create_data_from_canonical_like_cpp(
        &self,
        guid: ObjectGuid,
        gameobject: &wow_entities::GameObject,
    ) -> Option<wow_packet::packets::update::GameObjectCreateData> {
        let object = gameobject.world();
        let data = gameobject.data();
        let display_id = u32::try_from(data.display_id).ok()?;
        if display_id == 0 {
            return None;
        }
        let go_type = u8::try_from(data.type_id).ok()?;
        let go_state = match data.state {
            0 => Some(wow_entities::GoState::Active),
            1 => Some(wow_entities::GoState::Ready),
            2 => Some(wow_entities::GoState::Destroyed),
            24 => Some(wow_entities::GoState::TransportActive),
            25 => Some(wow_entities::GoState::TransportStopped),
            _ => None,
        };

        Some(wow_packet::packets::update::GameObjectCreateData {
            guid,
            entry: object.object().entry(),
            dynamic_flags: self.represented_gameobject_dynamic_flags_for_player_like_cpp(
                object.object().entry(),
                &RepresentedGameObjectUseState {
                    go_type: Some(go_type),
                    go_state,
                    dynamic_flags: object.object().dynamic_flags(),
                    ..Default::default()
                },
            ),
            display_id,
            go_type,
            position: object.position(),
            rotation: gameobject.local_rotation_like_cpp(),
            anim_progress: gameobject.go_anim_progress_like_cpp(),
            state: data.state,
            created_by: data.created_by,
            faction_template: data.faction_template,
            gameobject_flags: data.flags,
            world_effect_id: 0,
            scale: object.object().scale(),
            level: 0, // non-transport GameObject: Level unused (period via AnimationData)
            // Canonical GameObject entity does not yet carry per-spawn ParentRotation;
            // identity until the entity stores it (#NEXT.R8.ENTITIES.1216 follow-up).
            parent_rotation: [0.0, 0.0, 0.0, 1.0],
        })
    }

    fn dynamic_object_create_data_from_canonical_like_cpp(
        guid: ObjectGuid,
        dynamic_object: &wow_entities::DynamicObject,
    ) -> wow_packet::packets::update::DynamicObjectCreateData {
        let object = dynamic_object.world();
        let object_data = object.object().object_data_values();
        let data = dynamic_object.data();
        wow_packet::packets::update::DynamicObjectCreateData {
            guid,
            entry_id: u32::try_from(object_data.entry_id).unwrap_or(0),
            dynamic_flags: object_data.dynamic_flags,
            scale: object_data.scale,
            position: object.position(),
            caster: data.caster,
            dynamic_object_type: data.dynamic_object_type,
            spell_visual_id: data.spell_visual_id,
            spell_id: data.spell_id,
            radius: data.radius,
            cast_time_ms: data.cast_time_ms,
        }
    }

    pub(crate) fn visible_dynamic_objects_from_canonical_map_like_cpp(
        &self,
        map_id: u16,
        position: &wow_core::Position,
        visibility_radius: f32,
    ) -> Option<Vec<wow_packet::packets::update::DynamicObjectCreateData>> {
        let requested_map_id = u32::from(map_id);
        let player_map_key = self.current_canonical_player_map_key_like_cpp();
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = match player_map_key {
            Some(key) if key.map_id == requested_map_id => {
                manager.find_map(key.map_id, key.instance_id)?
            }
            Some(_) => return None,
            None => manager.find_map(requested_map_id, 0)?,
        };
        let nearby =
            map.map()
                .nearby_cell_guids_like_cpp(position.x, position.y, visibility_radius);
        let mut dynamic_objects = Vec::new();

        for guid in nearby
            .world
            .dynamic_objects
            .into_iter()
            .chain(nearby.grid.dynamic_objects)
        {
            let Some(dynamic_object) = map.map().get_typed_dynamic_object(guid) else {
                continue;
            };
            let object = dynamic_object.world();
            if !object.object().is_in_world()
                || object.map_id() != u32::from(map_id)
                || !object
                    .position()
                    .is_within_dist_2d(position, visibility_radius)
            {
                continue;
            }
            dynamic_objects.push(Self::dynamic_object_create_data_from_canonical_like_cpp(
                guid,
                dynamic_object,
            ));
        }

        Some(dynamic_objects)
    }

    pub(crate) fn visible_area_triggers_from_canonical_map_like_cpp(
        &self,
        map_id: u16,
        position: &wow_core::Position,
        visibility_radius: f32,
    ) -> Option<Vec<wow_packet::packets::update::AreaTriggerCreateData>> {
        let requested_map_id = u32::from(map_id);
        let player_map_key = self.current_canonical_player_map_key_like_cpp();
        let manager = self.canonical_map_manager.as_ref()?;
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let map = match player_map_key {
            Some(key) if key.map_id == requested_map_id => {
                manager.find_map(key.map_id, key.instance_id)?
            }
            Some(_) => return None,
            None => manager.find_map(requested_map_id, 0)?,
        };
        let nearby =
            map.map()
                .nearby_cell_guids_like_cpp(position.x, position.y, visibility_radius);
        let mut area_triggers = Vec::new();

        for guid in nearby.grid.area_triggers {
            let Some(area_trigger) = map
                .map()
                .map_object_record(guid)
                .and_then(wow_entities::MapObjectRecord::area_trigger)
            else {
                continue;
            };
            let object = area_trigger.world();
            if !object.object().is_in_world()
                || object.map_id() != u32::from(map_id)
                || !object
                    .position()
                    .is_within_dist_2d(position, visibility_radius)
                || !self.can_see_phase_shift_like_cpp(object.phase_shift())
            {
                continue;
            }
            if area_trigger.is_server_side() || area_trigger.is_removed() {
                continue;
            }
            area_triggers.push(
                crate::entity_update_bridge::area_trigger_create_data_from_entity_like_cpp(
                    area_trigger,
                ),
            );
        }

        Some(area_triggers)
    }

