    pub(crate) fn apply_represented_player_instance_reset_result_like_cpp(
        &mut self,
        map_id: u32,
        result: GroupInstanceResetResultLikeCpp,
        method: GroupInstanceResetMethodLikeCpp,
    ) -> bool {
        match result {
            GroupInstanceResetResultLikeCpp::Success => {
                self.forget_represented_player_recent_instance_like_cpp(map_id)
            }
            GroupInstanceResetResultLikeCpp::NotEmpty
                if method == GroupInstanceResetMethodLikeCpp::OnChangeDifficulty =>
            {
                self.forget_represented_player_recent_instance_like_cpp(map_id)
            }
            GroupInstanceResetResultLikeCpp::NotEmpty
            | GroupInstanceResetResultLikeCpp::CannotReset
            | GroupInstanceResetResultLikeCpp::Other => false,
        }
    }

    pub(crate) fn represented_toggle_difficulty_target_like_cpp(&self) -> Option<u32> {
        let store = self.difficulty_store()?;
        let raid_entry = store.get(self.represented_raid_difficulty_id_like_cpp);
        let entry = match raid_entry {
            Some(entry) if entry.toggle_difficulty_id != 0 => entry,
            _ => store.get(self.represented_dungeon_difficulty_id_like_cpp)?,
        };

        (entry.toggle_difficulty_id != 0).then_some(u32::from(entry.toggle_difficulty_id))
    }

    /// C++ `Player::LoadFromDB` applies `CheckLoaded*DifficultyID` to the raw
    /// `characters` columns before any login packets are sent.
    pub(crate) fn load_represented_player_difficulties_like_cpp(
        &mut self,
        dungeon_difficulty_id: u32,
        raid_difficulty_id: u32,
        legacy_raid_difficulty_id: u32,
    ) {
        let Some(store) = self.difficulty_store() else {
            self.represented_dungeon_difficulty_id_like_cpp = DIFFICULTY_NORMAL_LIKE_CPP;
            self.represented_raid_difficulty_id_like_cpp = DIFFICULTY_NORMAL_RAID_LIKE_CPP;
            self.represented_legacy_raid_difficulty_id_like_cpp = DIFFICULTY_10_N_LIKE_CPP;
            return;
        };

        let dungeon_difficulty_id =
            store.check_loaded_dungeon_difficulty_id_like_cpp(dungeon_difficulty_id);
        let raid_difficulty_id = store.check_loaded_raid_difficulty_id_like_cpp(raid_difficulty_id);
        let legacy_raid_difficulty_id =
            store.check_loaded_legacy_raid_difficulty_id_like_cpp(legacy_raid_difficulty_id);

        self.represented_dungeon_difficulty_id_like_cpp = dungeon_difficulty_id;
        self.represented_raid_difficulty_id_like_cpp = raid_difficulty_id;
        self.represented_legacy_raid_difficulty_id_like_cpp = legacy_raid_difficulty_id;
    }

    /// C++ `Player::_LoadGroup` overwrites the loaded player difficulties with
    /// the current group values because the leader may change them while the
    /// member is offline.
    pub(crate) fn load_represented_group_difficulties_like_cpp(&mut self) -> bool {
        let (Some(group_guid), Some(group_registry)) =
            (self.group_guid, self.group_registry.as_ref())
        else {
            return false;
        };

        let Some(group) = group_registry.get(&group_guid) else {
            return false;
        };

        self.represented_dungeon_difficulty_id_like_cpp = group.dungeon_difficulty_id;
        self.represented_raid_difficulty_id_like_cpp = group.raid_difficulty_id;
        self.represented_legacy_raid_difficulty_id_like_cpp = group.legacy_raid_difficulty_id;
        true
    }

    /// C++ `Player::SetGroup(group, subgroup)` stores the subgroup on the
    /// player's `GroupReference`; `Player::GetSubGroup()` reads it from there.
    pub(crate) fn load_represented_group_subgroup_like_cpp(&mut self) -> bool {
        let (Some(group_guid), Some(player_guid), Some(group_registry)) = (
            self.group_guid,
            self.player_guid(),
            self.group_registry.as_ref(),
        ) else {
            self.represented_subgroup_like_cpp = None;
            return false;
        };

        let Some(group) = group_registry.get(&group_guid) else {
            self.represented_subgroup_like_cpp = None;
            return false;
        };
        let Some(slot) = group.member_slot_like_cpp(player_guid) else {
            self.represented_subgroup_like_cpp = None;
            return false;
        };

        self.represented_subgroup_like_cpp = Some(slot.subgroup);
        true
    }

    pub(crate) fn apply_group_subgroup_like_cpp(&mut self, group_guid: u64, subgroup: u8) {
        if self.group_guid == Some(group_guid) {
            self.represented_subgroup_like_cpp = Some(subgroup);
            self.sync_player_registry_state_like_cpp();
        }
    }

    pub(crate) fn apply_group_join_like_cpp(&mut self, group_guid: u64, subgroup: u8) {
        self.group_guid = Some(group_guid);
        self.represented_subgroup_like_cpp = Some(subgroup);
        self.sync_player_registry_party_member_party_type_like_cpp();
    }

    pub(crate) fn sync_player_registry_party_member_party_type_like_cpp(&self) {
        let (Some(guid), Some(registry)) = (self.player_guid(), &self.player_registry) else {
            return;
        };
        let party_type = self.party_member_party_type_like_cpp();
        if let Some(mut info) = registry.get_mut(&guid) {
            info.party_member_party_type = party_type;
        }
    }

    pub(crate) fn clear_represented_group_subgroup_like_cpp(&mut self) {
        self.represented_subgroup_like_cpp = None;
    }

