    /// C++ `Player::_LoadGroup` resolves `CHAR_SEL_GROUP_MEMBER.guid` through
    /// `sGroupMgr->GetGroupByDbStoreId` before attaching the player to the
    /// already-loaded group.
    pub(crate) fn load_represented_group_by_db_store_id_like_cpp(
        &mut self,
        db_store_id: u32,
    ) -> bool {
        let Some(group_registry) = self.group_registry.as_ref() else {
            self.group_guid = None;
            self.represented_subgroup_like_cpp = None;
            return false;
        };
        let Some(group_guid) = group_guid_by_db_store_id_like_cpp(db_store_id) else {
            self.group_guid = None;
            self.represented_subgroup_like_cpp = None;
            return false;
        };
        if !group_registry.contains_key(&group_guid) {
            self.group_guid = None;
            self.represented_subgroup_like_cpp = None;
            return false;
        }

        self.group_guid = Some(group_guid);
        let _ = self.load_represented_group_subgroup_like_cpp();
        self.load_represented_group_difficulties_like_cpp()
    }

    /// C++ `Player::ResetGroupUpdateSequenceIfNeeded` resets the per-player
    /// sequence for a group category only when the loaded group guid changed.
    pub(crate) fn reset_group_update_sequence_if_needed_like_cpp(&mut self) -> bool {
        let (Some(group_guid), Some(group_registry)) =
            (self.group_guid, self.group_registry.as_ref())
        else {
            return false;
        };

        let Some(group) = group_registry.get(&group_guid) else {
            return false;
        };
        let category = group.group_category_like_cpp();
        if category >= wow_network::group_registry::MAX_GROUP_CATEGORY_LIKE_CPP {
            return false;
        }

        let sequence = &mut self.represented_group_update_sequences_like_cpp[usize::from(category)];
        if sequence.group_guid == Some(group_guid) {
            return false;
        }

        sequence.group_guid = Some(group_guid);
        sequence.update_sequence_number = 1;
        true
    }

    /// C++ `Player::NextGroupUpdateSequenceNumber` returns the current
    /// per-player category sequence and then increments it.
    pub(crate) fn next_group_update_sequence_number_like_cpp(&mut self, category: u8) -> i32 {
        if category >= wow_network::group_registry::MAX_GROUP_CATEGORY_LIKE_CPP {
            return 0;
        }

        let sequence = &mut self.represented_group_update_sequences_like_cpp[usize::from(category)];
        let current = sequence.update_sequence_number;
        sequence.update_sequence_number = sequence.update_sequence_number.saturating_add(1);
        current
    }

    /// C++ `Player::_LoadGroup` sets `PLAYER_FLAGS_GROUP_LEADER` when the
    /// loaded group leader matches the player, and removes it otherwise.
    pub(crate) fn apply_represented_group_leader_flag_like_cpp(&mut self) -> bool {
        let Some(player_guid) = self.player_guid() else {
            return false;
        };

        let is_group_leader = self
            .group_guid
            .and_then(|group_guid| {
                self.group_registry
                    .as_ref()
                    .and_then(|registry| registry.get(&group_guid).map(|group| group.leader_guid))
            })
            .is_some_and(|leader_guid| leader_guid == player_guid);

        let updated = self
            .mutate_canonical_player_like_cpp(|player| {
                if is_group_leader {
                    player.set_player_flag(PLAYER_FLAGS_GROUP_LEADER_LIKE_CPP);
                } else {
                    player.remove_player_flag(PLAYER_FLAGS_GROUP_LEADER_LIKE_CPP);
                }
            })
            .is_some();

        if updated {
            self.sync_player_registry_state_like_cpp();
        }

        updated
    }

    pub(crate) fn represented_dungeon_difficulty_packet_like_cpp(&self) -> DungeonDifficultySet {
        DungeonDifficultySet {
            difficulty_id: i32::try_from(self.represented_dungeon_difficulty_id_like_cpp)
                .unwrap_or(i32::MAX),
        }
    }

    pub(crate) fn apply_group_difficulty_like_cpp(
        &mut self,
        group_guid: u64,
        difficulty_id: u32,
        kind: wow_network::player_registry::GroupDifficultyKindLikeCpp,
    ) {
        if self.group_guid != Some(group_guid) {
            return;
        }

        match kind {
            wow_network::player_registry::GroupDifficultyKindLikeCpp::Dungeon => {
                self.represented_dungeon_difficulty_id_like_cpp = difficulty_id;
                self.send_packet(&DungeonDifficultySet {
                    difficulty_id: i32::try_from(difficulty_id).unwrap_or(i32::MAX),
                });
            }
            wow_network::player_registry::GroupDifficultyKindLikeCpp::Raid => {
                self.represented_raid_difficulty_id_like_cpp = difficulty_id;
                self.send_packet(&RaidDifficultySet {
                    difficulty_id: i32::try_from(difficulty_id).unwrap_or(i32::MAX),
                    legacy: false,
                });
            }
            wow_network::player_registry::GroupDifficultyKindLikeCpp::LegacyRaid => {
                self.represented_legacy_raid_difficulty_id_like_cpp = difficulty_id;
                self.send_packet(&RaidDifficultySet {
                    difficulty_id: i32::try_from(difficulty_id).unwrap_or(i32::MAX),
                    legacy: true,
                });
            }
        }
    }

    fn current_map_instanceable_like_cpp(&self) -> bool {
        let map_id = u32::from(self.player_map_id_like_cpp());
        self.map_store()
            .and_then(|store| store.get(map_id))
            .is_some_and(|entry| {
                matches!(
                    entry.instance_type,
                    wow_data::map::MAP_INSTANCE
                        | wow_data::map::MAP_RAID
                        | wow_data::map::MAP_BATTLEGROUND
                        | wow_data::map::MAP_ARENA
                        | wow_data::map::MAP_SCENARIO
                )
            })
    }

    pub(crate) fn represented_set_difficulty_id_like_cpp(
        &mut self,
        difficulty_id: u32,
    ) -> Vec<PreparedStatement> {
        let Some(entry) = self
            .difficulty_store()
            .and_then(|store| store.get(difficulty_id))
            .copied()
        else {
            return Vec::new();
        };

        let flags = DifficultyFlags::from_bits_truncate(entry.flags);
        if !flags.contains(DifficultyFlags::CAN_SELECT) {
            return Vec::new();
        }

        if self.current_map_instanceable_like_cpp() {
            return Vec::new();
        }

        if entry.instance_type == MAP_INSTANCE_LIKE_CPP {
            if let Some(statement) = self.set_represented_group_difficulty_like_cpp(
                difficulty_id,
                wow_network::player_registry::GroupDifficultyKindLikeCpp::Dungeon,
            ) {
                return vec![statement];
            }
            if self.group_guid.is_some()
                || difficulty_id == self.represented_dungeon_difficulty_id_like_cpp
            {
                return Vec::new();
            }

            self.represented_dungeon_difficulty_id_like_cpp = difficulty_id;
            self.send_packet(&DungeonDifficultySet {
                difficulty_id: i32::try_from(difficulty_id).unwrap_or(i32::MAX),
            });
            Vec::new()
        } else if entry.instance_type == MAP_RAID_LIKE_CPP {
            let legacy = flags.contains(DifficultyFlags::LEGACY);
            let kind = if legacy {
                wow_network::player_registry::GroupDifficultyKindLikeCpp::LegacyRaid
            } else {
                wow_network::player_registry::GroupDifficultyKindLikeCpp::Raid
            };
            if let Some(statement) =
                self.set_represented_group_difficulty_like_cpp(difficulty_id, kind)
            {
                return vec![statement];
            }
            if self.group_guid.is_some() {
                return Vec::new();
            }
            let current = if legacy {
                self.represented_legacy_raid_difficulty_id_like_cpp
            } else {
                self.represented_raid_difficulty_id_like_cpp
            };
            if difficulty_id == current {
                return Vec::new();
            }

            if legacy {
                self.represented_legacy_raid_difficulty_id_like_cpp = difficulty_id;
            } else {
                self.represented_raid_difficulty_id_like_cpp = difficulty_id;
            }

            self.send_packet(&RaidDifficultySet {
                difficulty_id: i32::try_from(difficulty_id).unwrap_or(i32::MAX),
                legacy,
            });
            Vec::new()
        } else {
            Vec::new()
        }
    }

    pub(crate) fn represented_raid_difficulty_request_like_cpp(
        &self,
        difficulty_id: i32,
        legacy: bool,
    ) -> Option<u32> {
        let difficulty_id = u32::try_from(difficulty_id).ok()?;
        let entry = self
            .difficulty_store()
            .and_then(|store| store.get(difficulty_id))
            .copied()?;
        if entry.instance_type != MAP_RAID_LIKE_CPP {
            return None;
        }

        let flags = DifficultyFlags::from_bits_truncate(entry.flags);
        if !flags.contains(DifficultyFlags::CAN_SELECT) {
            return None;
        }

        (flags.contains(DifficultyFlags::LEGACY) == legacy).then_some(difficulty_id)
    }

    fn set_represented_group_difficulty_like_cpp(
        &mut self,
        difficulty_id: u32,
        kind: wow_network::player_registry::GroupDifficultyKindLikeCpp,
    ) -> Option<PreparedStatement> {
        let group_guid = self.group_guid?;
        let player_guid = self.player_guid()?;
        let registry = self.group_registry.as_ref()?;
        let mut group = registry.get_mut(&group_guid)?;
        if !group.is_leader_like_cpp(player_guid) || group.is_lfg_group_like_cpp() {
            return None;
        }

        let changed = match kind {
            wow_network::player_registry::GroupDifficultyKindLikeCpp::Dungeon => {
                group.set_dungeon_difficulty_id_like_cpp(difficulty_id)
            }
            wow_network::player_registry::GroupDifficultyKindLikeCpp::Raid => {
                group.set_raid_difficulty_id_like_cpp(difficulty_id)
            }
            wow_network::player_registry::GroupDifficultyKindLikeCpp::LegacyRaid => {
                group.set_legacy_raid_difficulty_id_like_cpp(difficulty_id)
            }
        };
        if !changed {
            return None;
        }

        let db_store_id = group.db_store_id;
        let members = group.members.clone();
        drop(group);

        for member_guid in members {
            if member_guid == player_guid {
                self.apply_group_difficulty_like_cpp(group_guid, difficulty_id, kind);
                continue;
            }
            let Some(player_registry) = self.player_registry.as_ref() else {
                continue;
            };
            if let Some(member) = player_registry.get(&member_guid) {
                let _ = member
                    .command_tx
                    .try_send(SessionCommand::ApplyGroupDifficultyLikeCpp(
                        wow_network::player_registry::ApplyGroupDifficultyLikeCppCommand {
                            group_guid,
                            difficulty_id,
                            kind,
                        },
                    ));
            }
        }

        let statement = match kind {
            wow_network::player_registry::GroupDifficultyKindLikeCpp::Dungeon => {
                CharStatements::UPD_GROUP_DIFFICULTY
            }
            wow_network::player_registry::GroupDifficultyKindLikeCpp::Raid => {
                CharStatements::UPD_GROUP_RAID_DIFFICULTY
            }
            wow_network::player_registry::GroupDifficultyKindLikeCpp::LegacyRaid => {
                CharStatements::UPD_GROUP_LEGACY_RAID_DIFFICULTY
            }
        };
        let mut stmt = PreparedStatement::new(statement.sql());
        stmt.set_u32(0, difficulty_id);
        stmt.set_u32(1, db_store_id);
        Some(stmt)
    }

    pub(crate) fn represented_set_difficulty_reset_owner_like_cpp(
        &self,
        difficulty_id: u32,
    ) -> Option<ObjectGuid> {
        let entry = self
            .difficulty_store()
            .and_then(|store| store.get(difficulty_id))
            .copied()?;

        let flags = DifficultyFlags::from_bits_truncate(entry.flags);
        if !flags.contains(DifficultyFlags::CAN_SELECT) || self.current_map_instanceable_like_cpp()
        {
            return None;
        }

        let player_guid = self.player_guid()?;
        if let Some(group_guid) = self.group_guid {
            let group = self.group_registry.as_ref()?.get(&group_guid)?;
            if !group.is_leader_like_cpp(player_guid) || group.is_lfg_group_like_cpp() {
                return None;
            }

            let current = if entry.instance_type == MAP_INSTANCE_LIKE_CPP {
                group.dungeon_difficulty_id
            } else if entry.instance_type == MAP_RAID_LIKE_CPP {
                if flags.contains(DifficultyFlags::LEGACY) {
                    group.legacy_raid_difficulty_id
                } else {
                    group.raid_difficulty_id
                }
            } else {
                return None;
            };

            return (current != difficulty_id).then_some(group.leader_guid);
        }

        let current = if entry.instance_type == MAP_INSTANCE_LIKE_CPP {
            self.represented_dungeon_difficulty_id_like_cpp
        } else if entry.instance_type == MAP_RAID_LIKE_CPP {
            if flags.contains(DifficultyFlags::LEGACY) {
                self.represented_legacy_raid_difficulty_id_like_cpp
            } else {
                self.represented_raid_difficulty_id_like_cpp
            }
        } else {
            return None;
        };

        (current != difficulty_id).then_some(player_guid)
    }

