    pub(crate) fn enqueue_represented_quest_objective_progress_like_cpp(
        &mut self,
        event: RepresentedQuestObjectiveProgressEventLikeCpp,
    ) {
        self.represented_quest_objective_progress_events_like_cpp
            .push_back(event);
    }

    pub(crate) async fn drain_represented_quest_objective_progress_like_cpp(&mut self) {
        if self.represented_quest_objective_progress_draining_like_cpp {
            return;
        }

        self.represented_quest_objective_progress_draining_like_cpp = true;
        while let Some(event) = self
            .represented_quest_objective_progress_events_like_cpp
            .pop_front()
        {
            match event {
                RepresentedQuestObjectiveProgressEventLikeCpp::MoneyChanged {
                    old_money,
                    new_money,
                } => {
                    self.update_represented_money_quest_objective_progress_like_cpp(
                        old_money, new_money,
                    )
                    .await;
                }
                RepresentedQuestObjectiveProgressEventLikeCpp::CurrencyChanged {
                    currency_id,
                    change,
                } => {
                    let object_id = i32::try_from(currency_id).unwrap_or(i32::MAX);
                    self.update_represented_currency_quest_objective_progress_like_cpp(
                        currency_id,
                        change,
                    )
                    .await;
                    self.update_represented_storing_value_quest_objective_progress_like_cpp(
                        QUEST_OBJECTIVE_HAVE_CURRENCY_LIKE_CPP,
                        object_id,
                        change,
                        wow_core::ObjectGuid::new(0, 0),
                    )
                    .await;
                    self.update_represented_storing_value_quest_objective_progress_like_cpp(
                        QUEST_OBJECTIVE_OBTAIN_CURRENCY_LIKE_CPP,
                        object_id,
                        change,
                        wow_core::ObjectGuid::new(0, 0),
                    )
                    .await;
                }
                RepresentedQuestObjectiveProgressEventLikeCpp::ReputationChanged {
                    faction_id,
                    change,
                } => {
                    let object_id = i32::try_from(faction_id).unwrap_or(i32::MAX);
                    self.update_represented_reputation_quest_objective_progress_like_cpp(
                        QUEST_OBJECTIVE_MIN_REPUTATION_LIKE_CPP,
                        faction_id,
                        change,
                    )
                    .await;
                    self.update_represented_reputation_quest_objective_progress_like_cpp(
                        QUEST_OBJECTIVE_MAX_REPUTATION_LIKE_CPP,
                        faction_id,
                        change,
                    )
                    .await;
                    self.update_represented_storing_value_quest_objective_progress_like_cpp(
                        QUEST_OBJECTIVE_INCREASE_REPUTATION_LIKE_CPP,
                        object_id,
                        change,
                        wow_core::ObjectGuid::new(0, 0),
                    )
                    .await;
                }
            }
        }
        self.represented_quest_objective_progress_draining_like_cpp = false;
    }

    pub(crate) async fn money_changed_like_cpp(&mut self, new_money: u64) {
        self.enqueue_represented_quest_objective_progress_like_cpp(
            RepresentedQuestObjectiveProgressEventLikeCpp::MoneyChanged {
                old_money: self.player_gold_like_cpp(),
                new_money,
            },
        );
        self.drain_represented_quest_objective_progress_like_cpp()
            .await;
    }

    pub(crate) async fn apply_player_money_change_like_cpp(
        &mut self,
        old_money: u64,
        new_money: u64,
    ) {
        if old_money != new_money {
            self.enqueue_represented_quest_objective_progress_like_cpp(
                RepresentedQuestObjectiveProgressEventLikeCpp::MoneyChanged {
                    old_money,
                    new_money,
                },
            );
        }
        self.set_player_gold_like_cpp(new_money);
        self.drain_represented_quest_objective_progress_like_cpp()
            .await;
    }

    pub(crate) fn represented_next_reset_talents_cost_like_cpp(&self, now_secs: u64) -> u32 {
        Self::next_reset_talents_cost_like_cpp(
            self.represented_talent_reset_cost_like_cpp,
            self.represented_talent_reset_time_secs_like_cpp,
            now_secs,
        )
    }

    pub(crate) async fn apply_represented_talent_reset_cost_like_cpp(&mut self) -> bool {
        let now_secs = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();
        self.apply_represented_talent_reset_cost_at_like_cpp(now_secs)
            .await
    }

    pub(crate) async fn apply_represented_talent_reset_cost_at_like_cpp(
        &mut self,
        now_secs: u64,
    ) -> bool {
        let cost = if self.no_reset_talent_cost_like_cpp {
            0
        } else {
            u64::from(self.represented_next_reset_talents_cost_like_cpp(now_secs))
        };
        let old_money = self.player_gold_like_cpp();
        if !self.no_reset_talent_cost_like_cpp && old_money < cost {
            self.send_buy_error(BuyResult::NotEnoughtMoney, None, 0);
            return false;
        }

        self.apply_player_money_change_like_cpp(old_money, old_money - cost)
            .await;
        self.record_represented_talent_respec_criteria_like_cpp(cost as u32);
        self.represented_talent_reset_cost_like_cpp = cost as u32;
        self.represented_talent_reset_time_secs_like_cpp = now_secs;
        true
    }

    fn record_represented_talent_respec_criteria_like_cpp(&mut self, cost: u32) {
        self.represented_talent_respec_criteria_events_like_cpp
            .push(
                RepresentedTalentRespecCriteriaEventLikeCpp::MoneySpentOnRespecs { amount: cost },
            );
        self.represented_talent_respec_criteria_events_like_cpp
            .push(RepresentedTalentRespecCriteriaEventLikeCpp::TotalRespecs { quantity: 1 });
    }

    fn next_reset_talents_cost_like_cpp(
        reset_cost: u32,
        reset_time_secs: u64,
        now_secs: u64,
    ) -> u32 {
        let gold = COPPER_PER_GOLD_LIKE_CPP;
        if reset_cost < gold {
            return gold;
        }
        if reset_cost < 5 * gold {
            return 5 * gold;
        }
        if reset_cost < 10 * gold {
            return 10 * gold;
        }

        let months = now_secs.saturating_sub(reset_time_secs) / TALENT_RESET_MONTH_SECS_LIKE_CPP;
        if months > 0 {
            let reduced = i64::from(reset_cost)
                - i64::try_from(5 * u64::from(gold) * months).unwrap_or(i64::MAX);
            return reduced.max(i64::from(10 * gold)) as u32;
        }

        reset_cost.saturating_add(5 * gold).min(50 * gold)
    }

    pub(crate) async fn currency_changed_like_cpp(&mut self, currency_id: u32, change: i32) {
        self.enqueue_represented_quest_objective_progress_like_cpp(
            RepresentedQuestObjectiveProgressEventLikeCpp::CurrencyChanged {
                currency_id,
                change,
            },
        );
        self.drain_represented_quest_objective_progress_like_cpp()
            .await;
    }

    pub(crate) async fn reputation_changed_like_cpp(&mut self, faction_id: u32, change: i32) {
        self.enqueue_represented_quest_objective_progress_like_cpp(
            RepresentedQuestObjectiveProgressEventLikeCpp::ReputationChanged { faction_id, change },
        );
        self.drain_represented_quest_objective_progress_like_cpp()
            .await;
    }

    /// Set the QuestXP store (loaded from QuestXP.db2).
    pub fn set_quest_xp_store(&mut self, store: Arc<wow_data::quest_xp::QuestXpStore>) {
        self.quest_xp_store = Some(store);
    }

    /// Set the QuestMoneyReward store (loaded from QuestMoneyReward.db2).
    pub fn set_quest_money_reward_store(&mut self, store: Arc<QuestMoneyRewardStore>) {
        self.quest_money_reward_store = Some(store);
    }

    fn set_loaded_quest_completed_bit_like_cpp(&mut self, quest_bit: u32) -> bool {
        if quest_bit == 0 {
            return false;
        }

        let field_offset = (quest_bit - 1) / QUESTS_COMPLETED_BITS_PER_BLOCK;
        if field_offset as usize >= QUESTS_COMPLETED_BITS_SIZE {
            return false;
        }

        let canonical_changed = self
            .mutate_canonical_player_like_cpp(|player| {
                player.set_quest_completed_bit_like_cpp(quest_bit, true)
            })
            .unwrap_or(false);
        let bridge_changed = self
            .represented_quest_completed_bits_like_cpp
            .insert(quest_bit);
        canonical_changed || bridge_changed
    }

    fn clear_loaded_quest_completed_bit_like_cpp(&mut self, quest_bit: u32) -> bool {
        if quest_bit == 0 {
            return false;
        }

        let field_offset = (quest_bit - 1) / QUESTS_COMPLETED_BITS_PER_BLOCK;
        if field_offset as usize >= QUESTS_COMPLETED_BITS_SIZE {
            return false;
        }

        let canonical_changed = self
            .mutate_canonical_player_like_cpp(|player| {
                player.set_quest_completed_bit_like_cpp(quest_bit, false)
            })
            .unwrap_or(false);
        let bridge_changed = self
            .represented_quest_completed_bits_like_cpp
            .remove(&quest_bit);
        canonical_changed || bridge_changed
    }

    /// Set the player XP table (xp required per level).
    pub fn set_player_xp_table(&mut self, table: Arc<Vec<u32>>) {
        self.player_xp_table = Some(table);
        self.refresh_next_level_xp();
    }

    pub fn set_exploration_base_xp_store_like_cpp(
        &mut self,
        store: Arc<ExplorationBaseXpStoreLikeCpp>,
    ) {
        self.exploration_base_xp_store = Some(store);
    }

    pub fn set_exploration_xp_rate_like_cpp(&mut self, rate: f32) {
        self.exploration_xp_rate_like_cpp = rate.max(0.0);
    }

    pub fn set_min_quest_scaled_xp_ratio_like_cpp(&mut self, ratio: u32) {
        self.min_quest_scaled_xp_ratio_like_cpp = if ratio > 100 { 0 } else { ratio };
    }

    pub fn set_min_discovered_scaled_xp_ratio_like_cpp(&mut self, ratio: u32) {
        self.min_discovered_scaled_xp_ratio_like_cpp = ratio.min(100);
    }

    /// Update player_next_level_xp from the table based on current level.
    pub(crate) fn refresh_next_level_xp(&mut self) {
        if let Some(table) = &self.player_xp_table {
            let lvl = self.player_level_like_cpp() as usize;
            self.set_player_next_level_xp_like_cpp(table.get(lvl).copied().unwrap_or(u32::MAX));
        }
    }

    /// C++ `Player::GetQuestLevel`.
    pub(crate) fn player_quest_level_like_cpp(
        &self,
        quest: &wow_data::quest::QuestTemplate,
    ) -> i32 {
        if quest.quest_level > 0 {
            quest.quest_level
        } else {
            i32::from(self.player_level_like_cpp()).min(quest.quest_max_scaling_level)
        }
    }

    /// Calculate XP reward for a quest.
    /// C++ `Quest::XPValue(player, questLevel, xpDifficulty, xpMultiplier)`.
    pub(crate) fn calculate_quest_xp(
        &self,
        difficulty: u32,
        quest_level: i32,
        xp_multiplier: f32,
    ) -> u32 {
        if let Some(store) = &self.quest_xp_store {
            store.calculate_xp(
                quest_level,
                self.player_level_like_cpp(),
                difficulty,
                xp_multiplier,
                self.min_quest_scaled_xp_ratio_like_cpp,
            )
        } else {
            // Fallback if DB2 not loaded
            const XP_TABLE: [u32; 10] = [0, 50, 100, 200, 400, 650, 1000, 1500, 2500, 4000];
            XP_TABLE[difficulty.min(9) as usize]
        }
    }

    /// C++ `Player::GetQuestXPReward`.
    pub(crate) fn quest_xp_reward_like_cpp(&self, quest: &wow_data::quest::QuestTemplate) -> u32 {
        if self.rewarded_quests.contains(&quest.id) && !quest.is_df_quest_like_cpp() {
            return 0;
        }

        self.calculate_quest_xp(
            quest.reward_xp_difficulty,
            self.player_quest_level_like_cpp(quest),
            quest.reward_xp_multiplier,
        )
    }

    /// C++ `Player::GetQuestMoneyReward` -> `Quest::MoneyValue`.
    pub(crate) fn quest_money_reward_like_cpp(
        &self,
        quest: &wow_data::quest::QuestTemplate,
    ) -> u32 {
        let Some(store) = &self.quest_money_reward_store else {
            return 0;
        };
        let quest_level = self.player_quest_level_like_cpp(quest).max(0) as u32;
        let Some(row) = store.get(quest_level) else {
            return 0;
        };
        let difficulty = quest.reward_money_difficulty as usize;
        let Some(base) = row.difficulty.get(difficulty).copied() else {
            return 0;
        };
        ((base as f32) * quest.reward_money_multiplier).round() as u32
    }

    /// Check if a spell is on cooldown (global or per-spell).
    ///
    /// Returns true if either the global cooldown (1500ms) or the spell-specific
    /// cooldown from SpellStore is still active.
    pub fn is_spell_on_cooldown(&self, spell_id: i32) -> bool {
        let Some(last_cast) = self.last_spell_cast_time else {
            return false; // Never casted
        };

        let elapsed_ms = last_cast.elapsed().as_millis() as u32;

        // Global cooldown: 1500ms
        if elapsed_ms < 1500 {
            return true;
        }

        // Per-spell cooldown (if exists in SpellStore)
        if let Some(store) = &self.spell_store {
            if let Some(spell_info) = store.get(spell_id) {
                if elapsed_ms < spell_info.cooldown_ms {
                    return true;
                }
            }
        }

        false
    }

    /// Set the shared player registry (used for broadcast).
    pub fn set_player_registry(&mut self, registry: Arc<PlayerRegistry>) {
        self.player_registry = Some(registry);
    }

    /// Set the shared ObjectAccessor used for C++-style object lookup.
    pub fn set_object_accessor(&mut self, accessor: SharedObjectAccessor) {
        self.object_accessor = Some(accessor);
    }

    /// Get a reference to the shared ObjectAccessor.
    pub fn object_accessor(&self) -> Option<&SharedObjectAccessor> {
        self.object_accessor.as_ref()
    }

