    /// Check if the handler's required status matches the current session state.
    ///
    /// Matches C++ `WorldSession::Update` status gates:
    /// - `Authed` → allowed in ANY state (authenticated, in-world, or transferring)
    /// - `LoggedIn` → only when player is in-world
    /// - `Transfer` → only during map transfers
    /// - `LoggedInOrRecentlyLogout` → in-world or recently disconnected
    fn is_status_allowed(&self, required: SessionStatus) -> bool {
        match required {
            SessionStatus::Authed => true, // C++ STATUS_AUTHED
            SessionStatus::LoggedIn => self.state == SessionState::LoggedIn,
            SessionStatus::Transfer => self.state == SessionState::Transfer,
            SessionStatus::LoggedInOrRecentlyLogout => {
                self.state == SessionState::LoggedIn || self.state == SessionState::Disconnecting
            }
        }
    }

    /// Check for area triggers at the player's current position.
    ///
    /// This is called after movement updates to handle:
    /// - Teleportation triggers (e.g., dungeon exits)
    /// - Spell effects (e.g., silencing fields)
    /// - Custom trigger actions
    ///
    /// Manages trigger state to prevent retriggering:
    /// - Entry: when player enters a trigger (was not in one)
    /// - Exit: when player leaves a trigger (was in one, no longer is)
    pub async fn check_area_triggers(&mut self) {
        let (Some(pos), Some(store)) = (
            self.player_position_like_cpp(),
            self.area_trigger_store.as_ref(),
        ) else {
            return;
        };

        // Get all triggers at the current position on the player's current map
        let triggers = store.get_triggers_at_position(self.player_map_id_like_cpp(), &pos);

        // Check if we've exited the previous trigger
        if let Some(prev_trigger_id) = self.active_area_trigger {
            if !triggers.iter().any(|t| t.trigger_id == prev_trigger_id) {
                info!(
                    account = self.account_id,
                    trigger_id = prev_trigger_id,
                    "Exited area trigger"
                );
                self.active_area_trigger = None;
            }
        }

        // Check if we've entered a new trigger
        if let Some(trigger) = triggers.first() {
            let trigger_id = trigger.trigger_id;

            // Only trigger if this is a NEW trigger (wasn't active before)
            if self.active_area_trigger != Some(trigger_id) {
                info!(
                    account = self.account_id,
                    trigger_id = trigger.trigger_id,
                    "Entered area trigger"
                );
                self.active_area_trigger = Some(trigger_id);

                // Handle teleportation if present
                if let Some(ref teleport) = trigger.teleport {
                    info!(
                        account = self.account_id,
                        trigger_id = trigger.trigger_id,
                        target_map = teleport.target_map,
                        target_x = teleport.target_position.x,
                        target_y = teleport.target_position.y,
                        target_z = teleport.target_position.z,
                        "Teleporting player via area trigger"
                    );
                    self.teleport_to(teleport.target_map, teleport.target_position)
                        .await;
                }
            }
        }
    }

    /// Teleport the player to a new map and position.
    ///
    /// Sends SMSG_TRANSFER_PENDING (0x25cd) to initiate the transfer.
    /// The client will respond with CMSG_WORLD_PORT_ACK when ready.
    ///
    /// C++ `Player::TeleportTo` → `SendTransferPending`.
    pub async fn teleport_to(&mut self, new_map: u32, new_pos: wow_core::Position) {
        self.teleport_to_with_options(new_map, new_pos, TELE_TO_NONE_LIKE_CPP)
            .await;
    }

    pub(crate) async fn teleport_to_with_options(
        &mut self,
        new_map: u32,
        new_pos: wow_core::Position,
        mut options: TeleportToOptionsLikeCpp,
    ) {
        // Validate inputs
        if new_map as u16 > 0xFFF {
            warn!(
                "Invalid map ID {} for teleport from account {}",
                new_map, self.account_id
            );
            return;
        }

        if self.is_map_disabled_for_player_like_cpp(new_map) {
            warn!(
                account = self.account_id,
                map_id = new_map,
                "Teleport blocked by C++ DisableMgr map gate"
            );
            self.send_transfer_aborted_like_cpp(new_map, TRANSFER_ABORT_MAP_NOT_ALLOWED_LIKE_CPP);
            return;
        }

        if let Some(target_map) = self
            .map_store
            .as_ref()
            .and_then(|store| store.get(new_map).copied())
            && target_map.is_battleground_or_arena()
            && !self.player_in_represented_battleground_like_cpp()
        {
            warn!(
                account = self.account_id,
                map_id = new_map,
                "Teleport silently blocked by C++ battleground assignment gate"
            );
            return;
        }

        if let Some(target_map) = self
            .map_store
            .as_ref()
            .and_then(|store| store.get(new_map).copied())
            && self.expansion < target_map.expansion_like_cpp()
        {
            warn!(
                account = self.account_id,
                map_id = new_map,
                session_expansion = self.expansion,
                required_expansion = target_map.expansion_like_cpp(),
                "Teleport blocked by C++ client expansion gate"
            );
            self.send_transfer_aborted_with_params_like_cpp(
                new_map,
                TRANSFER_ABORT_INSUF_EXPAN_LVL_LIKE_CPP,
                target_map.expansion_like_cpp(),
                0,
            );
            return;
        }

        let Some(current_pos) = self.player_position_like_cpp() else {
            warn!(
                "Cannot teleport account {}: no current position",
                self.account_id
            );
            return;
        };

        self.exit_represented_vehicle_for_teleport_like_cpp();
        self.reset_teleport_movement_state_like_cpp();

        if self.player_class_like_cpp() == CLASS_DEATH_KNIGHT_LIKE_CPP
            && self.player_map_id_like_cpp() == DEATH_KNIGHT_START_MAP_LIKE_CPP
            && u32::from(self.player_map_id_like_cpp()) != new_map
            && !self.player_is_game_master_like_cpp()
            && !self
                .known_spells_like_cpp()
                .contains(&DEATH_KNIGHT_ESCAPE_SPELL_LIKE_CPP)
        {
            self.send_transfer_aborted_with_params_like_cpp(
                new_map,
                TRANSFER_ABORT_UNIQUE_MESSAGE_LIKE_CPP,
                1,
                0,
            );
            return;
        }

        let same_map_near_teleport = u32::from(self.player_map_id_like_cpp()) == new_map;
        if same_map_near_teleport {
            self.represented_far_teleport_pending_like_cpp = false;
            self.initiate_same_map_near_teleport_like_cpp(new_map, new_pos, options);
            return;
        }

        if let Some((transfer_abort, arg, map_difficulty_x_condition_id)) =
            self.player_cannot_enter_target_map_like_cpp(new_map)
        {
            self.send_transfer_aborted_with_params_like_cpp(
                new_map,
                transfer_abort,
                arg,
                map_difficulty_x_condition_id,
            );
            return;
        }

        if u32::from(self.player_map_id_like_cpp()) != new_map {
            options = self.teleport_options_after_seamless_gate_like_cpp(new_map, options);
        }

        if u32::from(self.player_map_id_like_cpp()) != new_map {
            self.represented_has_delayed_teleport_like_cpp =
                self.represented_can_delay_teleport_like_cpp;
            if self.represented_has_delayed_teleport_like_cpp {
                self.near_teleport_pending_like_cpp = false;
                self.near_teleport_destination_like_cpp = None;
                self.near_teleport_destination_zone_area_like_cpp = None;
                self.represented_far_teleport_pending_like_cpp = true;
                self.represented_delayed_teleport_like_cpp = Some((new_map, new_pos, options));
                return;
            }

            self.set_selection_guid_like_cpp(None);
            self.combat_stop_like_cpp();
            self.reset_contested_pvp_like_cpp();
            self.maybe_leave_represented_battleground_on_far_teleport_like_cpp(new_map);
            self.unsummon_represented_pet_temporary_if_any_like_cpp();
            let _ = self.remove_all_dynamic_objects_for_current_player_like_cpp();
            let _ = self.remove_all_area_triggers_for_current_player_like_cpp();
            if options & TELE_TO_SPELL_LIKE_CPP == 0 {
                let _ = self.interrupt_non_melee_spells_for_far_teleport_like_cpp();
            }
            let _ = self.remove_moving_or_turning_interrupt_auras_for_far_teleport_like_cpp();
        }

        info!(
            account = self.account_id,
            old_map = self.player_map_id_like_cpp(),
            new_map = new_map,
            old_pos = format!(
                "({:.2}, {:.2}, {:.2})",
                current_pos.x, current_pos.y, current_pos.z
            ),
            new_pos = format!("({:.2}, {:.2}, {:.2})", new_pos.x, new_pos.y, new_pos.z),
            "Player teleporting to new map"
        );

        use wow_packet::packets::misc::{SuspendToken, TransferPending};

        // 1. SMSG_TRANSFER_PENDING — tell client to start loading screen
        if !self.player_logout_like_cpp && options & TELE_TO_SEAMLESS_LIKE_CPP == 0 {
            let transfer_pending = TransferPending {
                map_id: new_map,
                old_map_position: current_pos,
                ship: None,
                transfer_spell_id: None,
            };
            self.send_packet(&transfer_pending);
            self.clear_active_player_transport_server_time_override_for_far_teleport_like_cpp();
        }

        let _ = self.remove_current_player_from_canonical_current_map_like_cpp();

        // 2. Store pending destination — completed in handle_world_port_response
        self.pending_teleport = Some((new_map, new_pos));
        self.active_area_trigger = None;

        // 3. SMSG_SUSPEND_TOKEN — pause movement processing on client. C++
        // Player::TeleportTo sets SequenceIndex = m_movementCounter WITHOUT incrementing
        // (Player.cpp:1466), and HandleMoveWorldportAck's ResumeToken uses the SAME counter
        // (the before-add reset happens only after ResumeToken). The client pairs suspend and
        // resume by this index, so they MUST match — a hardcoded 1 here vs the real counter in
        // ResumeToken left the client stuck on the loading screen. #NEXT.R8.ENTITIES.1229.
        if !self.player_logout_like_cpp {
            let suspend_seq = self.movement_counter_like_cpp();
            self.send_packet(&SuspendToken {
                sequence_index: suspend_seq,
                reason: if options & TELE_TO_SEAMLESS_LIKE_CPP != 0 {
                    2
                } else {
                    1
                },
            });
        }

        // 4. Transition to Transfer state — only WorldPortResponse accepted now
        self.represented_far_teleport_pending_like_cpp = true;
        self.state = SessionState::Transfer;

        info!(
            account = self.account_id,
            "Teleport initiated: map {} → {} dest ({:.2}, {:.2}, {:.2}); awaiting WorldPortResponse",
            self.player_map_id_like_cpp(),
            new_map,
            new_pos.x,
            new_pos.y,
            new_pos.z
        );
    }

    fn exit_represented_vehicle_for_teleport_like_cpp(&mut self) -> bool {
        if self.player_vehicle_seat_flags_like_cpp.is_none() {
            return false;
        }

        self.player_vehicle_seat_flags_like_cpp = None;
        self.player_vehicle_seat_id_like_cpp = None;
        self.sync_player_registry_state_like_cpp();
        true
    }

    fn reset_teleport_movement_state_like_cpp(&mut self) {
        let movement_flags =
            self.player_movement_flags_like_cpp & MovementFlag::MASK_HAS_PLAYER_STATUS_OPCODE;
        self.set_player_movement_flags_like_cpp(movement_flags);
        self.player_movement_jump_like_cpp = wow_packet::packets::movement::JumpInfo::default();
        let _ = self.mutate_canonical_player_like_cpp(|player| {
            let motion = &mut player.unit_mut().subsystems_mut().motion;
            motion.interrupt_spline();
            let _ =
                motion.remove_generator_kind(MovementGeneratorKind::Effect, MovementSlot::Active);
        });
    }

    fn teleport_options_after_seamless_gate_like_cpp(
        &self,
        new_map: u32,
        mut options: TeleportToOptionsLikeCpp,
    ) -> TeleportToOptionsLikeCpp {
        if options & TELE_TO_SEAMLESS_LIKE_CPP == 0 {
            return options;
        }

        let Some(map_store) = self.map_store.as_ref() else {
            return options & !TELE_TO_SEAMLESS_LIKE_CPP;
        };
        let Some(old_map_entry) = map_store
            .get(u32::from(self.player_map_id_like_cpp()))
            .copied()
        else {
            return options & !TELE_TO_SEAMLESS_LIKE_CPP;
        };
        let Some(new_map_entry) = map_store.get(new_map).copied() else {
            return options & !TELE_TO_SEAMLESS_LIKE_CPP;
        };

        let old_cosmetic_parent = i32::from(old_map_entry.cosmetic_parent_map_id);
        let new_cosmetic_parent = i32::from(new_map_entry.cosmetic_parent_map_id);
        let current_map_id = i32::from(self.player_map_id_like_cpp());
        let new_map_id = i32::try_from(new_map).unwrap_or(i32::MAX);
        if old_cosmetic_parent != new_map_id
            && current_map_id != new_cosmetic_parent
            && !((old_cosmetic_parent != -1) ^ (old_cosmetic_parent != new_cosmetic_parent))
        {
            options &= !TELE_TO_SEAMLESS_LIKE_CPP;
        }

        options
    }

    fn initiate_same_map_near_teleport_like_cpp(
        &mut self,
        map_id: u32,
        destination: wow_core::Position,
        options: TeleportToOptionsLikeCpp,
    ) {
        self.represented_has_delayed_teleport_like_cpp =
            self.represented_can_delay_teleport_like_cpp;
        if self.represented_has_delayed_teleport_like_cpp {
            let map_id_u16 = u16::try_from(map_id).unwrap_or(self.player_map_id_like_cpp());
            self.near_teleport_pending_like_cpp = true;
            self.near_teleport_destination_like_cpp = Some((map_id_u16, destination));
            self.near_teleport_destination_zone_area_like_cpp = None;
            self.represented_delayed_teleport_like_cpp = Some((map_id, destination, options));
            return;
        }

        self.unsummon_represented_pet_for_same_map_teleport_if_out_of_range_like_cpp(
            destination,
            options,
        );

        if !self.player_is_alive_like_cpp() && options & TELE_REVIVE_AT_TELEPORT_LIKE_CPP != 0 {
            self.resurrect_player_percent_for_teleport_like_cpp(0.5);
        }

        if options & TELE_TO_NOT_LEAVE_COMBAT_LIKE_CPP == 0 {
            self.combat_stop_like_cpp();
        }

        let map_id = u16::try_from(map_id).unwrap_or(self.player_map_id_like_cpp());
        self.pending_teleport = None;
        self.near_teleport_pending_like_cpp = true;
        self.near_teleport_destination_like_cpp = Some((map_id, destination));
        self.near_teleport_destination_zone_area_like_cpp = None;
        if let Some(current_pos) = self.player_position_like_cpp() {
            self.set_fall_information_like_cpp(0, current_pos.z);
        }

        if !self.player_logout_like_cpp {
            let sequence_index = self.next_movement_counter_like_cpp();
            if let Some(mover_guid) = self.player_guid() {
                self.send_same_map_move_update_teleport_to_visible_set_like_cpp(mover_guid);
                self.send_packet(&wow_packet::packets::movement::MoveTeleport {
                    mover_guid,
                    position: destination,
                    facing: destination.orientation,
                    sequence_index,
                    preload_world: 0,
                    transport_guid: None,
                });
            }
        }

        info!(
            account = self.account_id,
            map_id,
            new_pos = format!(
                "({:.2}, {:.2}, {:.2})",
                destination.x, destination.y, destination.z
            ),
            "Player same-map near teleport initiated; awaiting MoveTeleportAck"
        );
    }

    fn process_represented_delayed_teleport_after_update_like_cpp(&mut self) -> bool {
        if !self.represented_has_delayed_teleport_like_cpp || !self.player_is_alive_like_cpp() {
            return false;
        }

        let Some((map_id, destination, options)) =
            self.represented_delayed_teleport_like_cpp.take()
        else {
            self.represented_has_delayed_teleport_like_cpp = false;
            return false;
        };

        self.represented_can_delay_teleport_like_cpp = false;
        self.represented_has_delayed_teleport_like_cpp = false;
        if u32::from(self.player_map_id_like_cpp()) == map_id {
            self.initiate_same_map_near_teleport_like_cpp(map_id, destination, options);
        } else {
            self.initiate_far_teleport_after_delay_like_cpp(map_id, destination, options);
        }
        true
    }

    fn initiate_far_teleport_after_delay_like_cpp(
        &mut self,
        map_id: u32,
        destination: wow_core::Position,
        options: TeleportToOptionsLikeCpp,
    ) {
        self.set_selection_guid_like_cpp(None);
        self.combat_stop_like_cpp();
        self.reset_contested_pvp_like_cpp();
        self.maybe_leave_represented_battleground_on_far_teleport_like_cpp(map_id);
        self.unsummon_represented_pet_temporary_if_any_like_cpp();
        let _ = self.remove_all_dynamic_objects_for_current_player_like_cpp();
        let _ = self.remove_all_area_triggers_for_current_player_like_cpp();
        if options & TELE_TO_SPELL_LIKE_CPP == 0 {
            let _ = self.interrupt_non_melee_spells_for_far_teleport_like_cpp();
        }
        let _ = self.remove_moving_or_turning_interrupt_auras_for_far_teleport_like_cpp();

        let Some(current_pos) = self.player_position_like_cpp() else {
            return;
        };

        use wow_packet::packets::misc::{SuspendToken, TransferPending};

        if !self.player_logout_like_cpp && options & TELE_TO_SEAMLESS_LIKE_CPP == 0 {
            let transfer_pending = TransferPending {
                map_id,
                old_map_position: current_pos,
                ship: None,
                transfer_spell_id: None,
            };
            self.send_packet(&transfer_pending);
            self.clear_active_player_transport_server_time_override_for_far_teleport_like_cpp();
        }

        let _ = self.remove_current_player_from_canonical_current_map_like_cpp();

        self.pending_teleport = Some((map_id, destination));
        self.active_area_trigger = None;

        if !self.player_logout_like_cpp {
            // C++ SuspendToken.SequenceIndex = m_movementCounter (Player.cpp:1466); must match
            // the ResumeToken sent later so the client resumes. #NEXT.R8.ENTITIES.1229.
            let suspend_seq = self.movement_counter_like_cpp();
            self.send_packet(&SuspendToken {
                sequence_index: suspend_seq,
                reason: if options & TELE_TO_SEAMLESS_LIKE_CPP != 0 {
                    2
                } else {
                    1
                },
            });
        }

        self.represented_far_teleport_pending_like_cpp = true;
        self.state = SessionState::Transfer;
    }

    fn unsummon_represented_pet_for_same_map_teleport_if_out_of_range_like_cpp(
        &mut self,
        destination: wow_core::Position,
        options: TeleportToOptionsLikeCpp,
    ) {
        if options & TELE_TO_NOT_UNSUMMON_PET_LIKE_CPP != 0 {
            return;
        }
        let Some(pet_guid) = self.represented_pet_guid_like_cpp else {
            return;
        };
        let map_id = u32::from(self.player_map_id_like_cpp());
        let instance_id = self
            .current_canonical_player_map_key_like_cpp()
            .map(|key| key.instance_id)
            .unwrap_or(0);

        let should_unsummon = {
            let Some(manager) = self.canonical_map_manager.as_ref().cloned() else {
                return;
            };
            let Ok(manager) = manager.lock() else {
                return;
            };
            let Some(managed) = manager.find_map(map_id, instance_id) else {
                return;
            };
            let visibility_range = managed.map().visibility_range();
            managed
                .map()
                .get_pet(pet_guid)
                .is_some_and(|pet| pet.distance_to_position(destination) > visibility_range)
        };

        if should_unsummon {
            self.unsummon_represented_pet_temporary_if_any_like_cpp();
        }
    }

    fn resurrect_player_percent_for_teleport_like_cpp(&mut self, restore_percent: f32) {
        let max_health = self.player_max_health_like_cpp.max(1);
        let health = ((max_health as f32) * restore_percent)
            .max(0.0)
            .min(max_health as f32) as u32;
        self.player_health_like_cpp = health;
        self.player_alive_like_cpp = true;
        let _ = self.mutate_canonical_player_like_cpp(|player| {
            player.unit_mut().set_max_health(u64::from(max_health));
            player.unit_mut().set_health(u64::from(health));
            let mana = ((player.get_max_power(PowerType::Mana).max(0) as f32) * restore_percent)
                .max(0.0) as i32;
            let energy = ((player.get_max_power(PowerType::Energy).max(0) as f32) * restore_percent)
                .max(0.0) as i32;
            let focus = ((player.get_max_power(PowerType::Focus).max(0) as f32) * restore_percent)
                .max(0.0) as i32;
            player.unit_mut().set_power(PowerType::Mana, mana);
            player.unit_mut().set_power(PowerType::Rage, 0);
            player.unit_mut().set_power(PowerType::Energy, energy);
            player.unit_mut().set_power(PowerType::Focus, focus);
        });
        self.sync_player_registry_state_like_cpp();
    }

    fn send_same_map_move_update_teleport_to_visible_set_like_cpp(&self, source_guid: ObjectGuid) {
        use wow_packet::ServerPacket;

        let Some(registry) = self.player_registry() else {
            return;
        };
        let Some(source_position) = self.player_position_like_cpp() else {
            return;
        };
        let map_id = self.player_map_id_like_cpp();
        let instance_id = self
            .current_canonical_player_map_key_like_cpp()
            .map(|key| key.instance_id)
            .unwrap_or(0);
        let range_sq =
            crate::map_manager::VISIBILITY_RADIUS * crate::map_manager::VISIBILITY_RADIUS;

        let mut status = self.current_player_movement_info_like_cpp(source_guid);
        status.time = self.player_movement_time_like_cpp();
        let packet_bytes = wow_packet::packets::movement::MoveUpdateTeleport { status }.to_bytes();

        let candidates: Vec<_> = registry
            .iter()
            .filter_map(|entry| {
                let (target_guid, info) = entry.pair();
                if *target_guid == source_guid {
                    return None;
                }
                if !info.is_in_world || info.map_id != map_id || info.instance_id != instance_id {
                    return None;
                }
                let dx = info.position.x - source_position.x;
                let dy = info.position.y - source_position.y;
                if dx * dx + dy * dy > range_sq {
                    return None;
                }
                Some(info.command_tx.clone())
            })
            .collect();

        for command_tx in candidates {
            let _ = command_tx.try_send(wow_network::SessionCommand::SendIfVisibleLikeCpp(
                wow_network::player_registry::SendIfVisibleLikeCppCommand {
                    queued_at: Instant::now(),
                    source_guid,
                    map_id,
                    instance_id,
                    packet_bytes: packet_bytes.clone(),
                },
            ));
        }
    }

    fn remove_all_dynamic_objects_for_current_player_like_cpp(
        &self,
    ) -> Option<wow_map::map::RemoveAllDynamicObjectsForCasterOutcomeLikeCpp> {
        let player_guid = self.player_guid()?;
        let map_key = self.current_canonical_player_map_key_like_cpp()?;
        let canonical = self.canonical_map_manager.as_ref()?;
        let mut manager = canonical.lock().ok()?;
        let managed = manager.find_map_mut(map_key.map_id, map_key.instance_id)?;
        Some(
            managed
                .map_mut()
                .remove_all_dynamic_objects_for_caster_like_cpp(player_guid),
        )
    }

    fn remove_all_area_triggers_for_current_player_like_cpp(
        &self,
    ) -> Option<wow_map::map::RemoveAllAreaTriggersForCasterOutcomeLikeCpp> {
        let player_guid = self.player_guid()?;
        let map_key = self.current_canonical_player_map_key_like_cpp()?;
        let canonical = self.canonical_map_manager.as_ref()?;
        let mut manager = canonical.lock().ok()?;
        let managed = manager.find_map_mut(map_key.map_id, map_key.instance_id)?;
        Some(
            managed
                .map_mut()
                .remove_all_area_triggers_for_caster_like_cpp(player_guid),
        )
    }

    fn player_cannot_enter_target_map_like_cpp(&self, map_id: u32) -> Option<(u32, u8, i32)> {
        let Some(map_store) = self.map_store.as_ref() else {
            return None;
        };
        let Some(map_entry) = map_store.get(map_id).copied() else {
            return Some((TRANSFER_ABORT_MAP_NOT_ALLOWED_LIKE_CPP, 0, 0));
        };
        if !map_entry.is_dungeon() {
            return None;
        }

        let player_guid = self.player_guid?;
        let player = self.create_map_player_context_like_cpp(map_id, map_entry, player_guid);
        let requested_difficulty = player
            .group
            .map(|group| group.difficulty_id)
            .unwrap_or(player.player_difficulty_id);

        if self
            .create_map_db2_entries_like_cpp(map_id, requested_difficulty)
            .is_none()
        {
            return Some((TRANSFER_ABORT_DIFFICULTY_LIKE_CPP, 0, 0));
        }

        if self.player_is_game_master_like_cpp() {
            return None;
        }

        if let Some(abort) =
            self.access_requirement_abort_like_cpp(map_id, requested_difficulty as u8)
        {
            return Some(abort);
        }

        if map_entry.instance_type == wow_data::map::MAP_RAID
            && map_entry.expansion_like_cpp() >= self.server_expansion_like_cpp
            && !self.instance_ignore_raid_like_cpp
            && !self.current_player_is_in_raid_group_like_cpp()
        {
            return Some((TRANSFER_ABORT_NEED_GROUP_LIKE_CPP, 0, 0));
        }

        let Some(canonical_map_manager) = self.canonical_map_manager.as_ref() else {
            return None;
        };
        let entry = wow_map::CreateMapEntryContext {
            map_id,
            kind: wow_map::CreateMapEntryKind::Dungeon,
            split_by_faction: map_entry.is_split_by_faction(),
            flex_locking: map_entry.is_flex_locking(),
        };
        let active_instance_lock =
            self.create_map_active_instance_lock_context_like_cpp(map_id, requested_difficulty);
        let mut manager = canonical_map_manager.lock().ok()?;
        let decision = manager.create_map_decision_like_cpp(
            Some(entry),
            Some(player),
            |candidate_map_id, difficulty_id| {
                self.create_map_difficulty_context_like_cpp(candidate_map_id, difficulty_id)
            },
            active_instance_lock,
            |_, _| None,
        );

        let existing_instance_lock_context = match &decision {
            wow_map::CreateMapDecision::Existing { key, .. } => manager
                .find_map(key.map_id, key.instance_id)
                .and_then(|map| map.instance_lock_context()),
            _ => None,
        };
        let existing_instance_player_count = match &decision {
            wow_map::CreateMapDecision::Existing { key, .. } => manager
                .find_map(key.map_id, key.instance_id)
                .map(|map| map.players_count_except_gms_like_cpp()),
            _ => None,
        };
        let existing_instance_encounter_in_progress = match &decision {
            wow_map::CreateMapDecision::Existing { key, .. } => manager
                .find_map(key.map_id, key.instance_id)
                .map(|map| map.instance_encounter_in_progress_like_cpp()),
            _ => None,
        };
        let decision_key = create_map_decision_key_like_cpp(&decision);
        drop(manager);

        if let wow_map::CreateMapDecision::Existing {
            key, difficulty_id, ..
        } = &decision
        {
            if let Some(player_count) = existing_instance_player_count
                && let Some(entries) =
                    self.create_map_db2_entries_like_cpp(key.map_id, *difficulty_id)
                && player_count >= entries.max_players
            {
                return Some((TRANSFER_ABORT_MAX_PLAYERS_LIKE_CPP, 0, 0));
            }

            if map_entry.instance_type == wow_data::map::MAP_RAID
                && self.player_loading() != Some(player_guid)
                && existing_instance_encounter_in_progress == Some(true)
            {
                return Some((TRANSFER_ABORT_ZONE_IN_COMBAT_LIKE_CPP, 0, 0));
            }

            if let Some(lock_context) = existing_instance_lock_context {
                let deny_reason = self
                    .cannot_enter_existing_instance_lock_like_cpp(
                        key.map_id,
                        *difficulty_id,
                        lock_context,
                    )
                    .unwrap_or(wow_instances::TransferAbortReason::None);
                if deny_reason != wow_instances::TransferAbortReason::None {
                    return Some((deny_reason as u32, 0, 0));
                }
            }
        }

        if !map_entry.ignores_instance_farm_limit_like_cpp()
            && let Some(key) = decision_key
            && !self.check_instance_count_probe_like_cpp(key.instance_id)
            && self.player_is_alive_like_cpp()
        {
            return Some((TRANSFER_ABORT_TOO_MANY_INSTANCES_LIKE_CPP, 0, 0));
        }

        None
    }

    pub(crate) fn is_disabled_map_type_for_player_like_cpp(
        &self,
        disable_type: u32,
        map_id: u32,
    ) -> bool {
        let Some(disable_mgr) = self.disable_mgr() else {
            return false;
        };
        let Some(map_store) = self.map_store() else {
            return false;
        };

        let current_map_id = u32::from(self.player_map_id_like_cpp());
        let (_, area_id) = self.player_zone_area_like_cpp();
        let current_map_instance_type = map_store
            .get(current_map_id)
            .map(|entry| entry.instance_type);

        disable_mgr.is_disabled_for_like_cpp(
            disable_type,
            map_id,
            Some(DisableWorldObjectRefLikeCpp {
                type_id: TypeId::Player,
                map_id: current_map_id,
                area_id,
                is_pet: false,
                is_battle_arena: current_map_instance_type == Some(MAP_ARENA_LIKE_CPP),
                is_battleground: current_map_instance_type == Some(MAP_BATTLEGROUND_LIKE_CPP),
                player_map_difficulty: None,
            }),
            0,
            Some(map_store.as_ref()),
        )
    }

    fn is_map_disabled_for_player_like_cpp(&self, map_id: u32) -> bool {
        self.is_disabled_map_type_for_player_like_cpp(DISABLE_TYPE_MAP, map_id)
    }

    /// Send a server packet back to the client via the instance (default) channel.
    pub fn send_packet<P: wow_packet::ServerPacket>(&self, pkt: &P) {
        let data = pkt.to_bytes();
        if std::env::var_os("RUSTYCORE_LOGIN_TRACE").is_some() {
            info!(
                account = self.account_id,
                opcode = ?P::OPCODE,
                bytes = data.len(),
                "RUST_LOGIN_TRACE send_packet"
            );
        }
        if self.send_tx.send(data).is_err() {
            warn!("Send channel closed for account {}", self.account_id);
        }
    }

    fn send_system_message_like_cpp(&self, text: &str) {
        for line in text.split('\n') {
            self.send_packet(&ChatPkt {
                msg_type: ChatMsg::System,
                language: 0,
                sender_guid: ObjectGuid::EMPTY,
                sender_name: String::new(),
                target_guid: ObjectGuid::EMPTY,
                target_name: String::new(),
                prefix: String::new(),
                channel: String::new(),
                text: line.to_string(),
                virtual_realm: self.virtual_realm_address(),
            });
        }
    }

    fn send_notification_like_cpp(&self, text: String) {
        self.send_packet(&PrintNotification { notify_text: text });
    }

    fn reset_talents_notification_text_like_cpp(&self) -> String {
        let text = self.trinity_string_like_cpp(LANG_RESET_TALENTS_LIKE_CPP);
        if text == "<error>" {
            LANG_RESET_TALENTS_TEXT_LIKE_CPP.to_string()
        } else {
            text.to_string()
        }
    }

    fn reset_spells_notification_text_like_cpp(&self) -> String {
        let text = self.trinity_string_like_cpp(LANG_RESET_SPELLS_LIKE_CPP);
        if text == "<error>" {
            LANG_RESET_SPELLS_TEXT_LIKE_CPP.to_string()
        } else {
            text.to_string()
        }
    }

    fn trinity_string_like_cpp(&self, entry: u32) -> &str {
        self.trinity_string_store
            .as_ref()
            .map(|store| store.get_like_cpp(entry, &self.locale))
            .unwrap_or("<error>")
    }

    fn item_template_name_like_cpp(&self, item_id: u32) -> &str {
        self.item_search_name_store
            .as_ref()
            .and_then(|store| store.get(item_id))
            .map(|entry| entry.display.as_str())
            .filter(|name| !name.is_empty())
            .unwrap_or("<error>")
    }

    /// C++ `Player::SendUpdateWorldState(variable, value, hidden)` direct-session send.
    ///
    /// Mirrors `SendDirectMessage(worldstate.Write())`: constructs one
    /// `SMSG_UPDATE_WORLD_STATE` packet and sends it only through this session's
    /// outbound channel. GameEvent fanout, login initialization, and global
    /// `WorldStateMgr` ownership are intentionally out of scope for this seam.
    pub fn send_update_world_state_like_cpp(&self, variable_id: u32, value: i32, hidden: bool) {
        let packet = wow_packet::packets::misc::UpdateWorldState {
            variable_id,
            value,
            hidden,
        };
        self.send_packet(&packet);
    }

    /// Send a server packet on the **realm** connection.
    ///
    /// Some packets (e.g. `QueryPlayerNamesResponse`) must travel on the
    /// realm socket, not the instance socket.  Falls back to `send_tx` if
    /// no realm channel exists (pre-ConnectTo or single-connection mode).
    pub fn send_packet_realm(&self, pkt: &impl wow_packet::ServerPacket) {
        let data = pkt.to_bytes();
        let tx = self.realm_send_tx.as_ref().unwrap_or(&self.send_tx);
        if tx.send(data).is_err() {
            warn!("Realm send channel closed for account {}", self.account_id);
        }
    }

    #[cfg(test)]
    pub(crate) fn install_realm_send_channel_for_test(&mut self, tx: flume::Sender<Vec<u8>>) {
        self.realm_send_tx = Some(tx);
    }

    /// Send pre-serialized packet bytes to the client.
    ///
    /// Used for packets with dynamic opcodes (e.g. `SetSpellModifier`
    /// which uses the same struct for Flat and Pct variants).
    pub fn send_raw_packet(&self, data: &[u8]) {
        if std::env::var_os("RUSTYCORE_LOGIN_TRACE").is_some() {
            let opcode_text = data
                .get(0..2)
                .map(|bytes| format!("0x{:04X}", u16::from_le_bytes([bytes[0], bytes[1]])))
                .unwrap_or_else(|| "<short>".to_string());
            info!(
                account = self.account_id,
                opcode = opcode_text.as_str(),
                bytes = data.len(),
                "RUST_LOGIN_TRACE send_raw_packet"
            );
        }
        if self.send_tx.send(data.to_vec()).is_err() {
            warn!("Send channel closed for account {}", self.account_id);
        }
    }

    pub fn send_equip_error(
        &self,
        result: InventoryResult,
        item1: Option<ObjectGuid>,
        item2: Option<ObjectGuid>,
        required_level: u32,
        limit_category: u32,
    ) {
        let mut packet = InventoryChangeFailure::new(
            result,
            item1.unwrap_or(ObjectGuid::EMPTY),
            item2.unwrap_or(ObjectGuid::EMPTY),
        );

        if result != InventoryResult::Ok {
            packet.container_b_slot = 0;
            match result {
                InventoryResult::CantEquipLevelI | InventoryResult::PurchaseLevelTooLow => {
                    packet.level = required_level;
                }
                InventoryResult::ItemMaxLimitCategoryCountExceededIs
                | InventoryResult::ItemMaxLimitCategorySocketedExceededIs
                | InventoryResult::ItemMaxLimitCategoryEquippedExceededIs => {
                    packet.limit_category = limit_category;
                }
                _ => {}
            }
        }

        self.send_packet(&packet);
    }

    pub fn send_buy_error(&self, result: BuyResult, creature_guid: Option<ObjectGuid>, item: u32) {
        self.send_packet(&BuyFailed {
            vendor_guid: creature_guid.unwrap_or(ObjectGuid::EMPTY),
            muid: item as i32,
            reason: result,
        });
    }

    pub fn send_sell_error(
        &self,
        result: SellResult,
        creature_guid: Option<ObjectGuid>,
        item_guid: ObjectGuid,
    ) {
        self.send_packet(&SellResponse::error(
            creature_guid.unwrap_or(ObjectGuid::EMPTY),
            item_guid,
            result,
        ));
    }

    fn item_push_result_from_send_new_item_plan(plan: &SendNewItemPlan) -> ItemPushResult {
        ItemPushResult {
            player_guid: plan.player_guid,
            slot: plan.slot,
            slot_in_bag: i32::from(plan.slot_in_bag),
            item: ItemInstance {
                item_id: plan.item_instance.item_id as i32,
                random_properties_seed: plan.item_instance.random_properties_seed,
                random_properties_id: plan.item_instance.random_properties_id,
                item_bonus: None,
                modifications: ItemModList {
                    values: plan
                        .item_instance
                        .modifications
                        .iter()
                        .map(|modifier| ItemMod::new(modifier.value, modifier.modifier_type))
                        .collect(),
                },
            },
            quest_log_item_id: plan.quest_log_item_id as i32,
            quantity: plan.quantity as i32,
            quantity_in_inventory: plan.quantity_in_inventory as i32,
            dungeon_encounter_id: plan.dungeon_encounter_id as i32,
            battle_pet_species_id: plan.battle_pet_species_id as i32,
            battle_pet_breed_id: plan.battle_pet_breed_id as i32,
            battle_pet_breed_quality: u32::from(plan.battle_pet_breed_quality),
            battle_pet_level: plan.battle_pet_level as i32,
            item_guid: plan.item_guid,
            pushed: plan.pushed,
            display_text: match plan.display_text {
                SendNewItemDisplayText::Normal => ItemPushResultDisplayType::Normal,
                SendNewItemDisplayText::EncounterLoot => ItemPushResultDisplayType::EncounterLoot,
                SendNewItemDisplayText::QuestUpdateAddItem => {
                    ItemPushResultDisplayType::QuestUpdateAddItem
                }
            },
            created: plan.created,
            is_bonus_roll: false,
            is_encounter_loot: plan.is_encounter_loot,
        }
    }

    pub fn send_new_item_plan(&self, plan: &SendNewItemPlan) {
        let packet = Self::item_push_result_from_send_new_item_plan(plan);
        if plan.delivery == SendNewItemDelivery::GroupBroadcast {
            use wow_packet::ServerPacket;

            if self.broadcast_item_push_result_to_group(packet.to_bytes()) {
                return;
            }
        }

        self.send_packet(&packet);
    }

    fn broadcast_item_push_result_to_group(&self, bytes: Vec<u8>) -> bool {
        let (Some(group_guid), Some(group_registry), Some(player_registry)) =
            (self.group_guid, &self.group_registry, &self.player_registry)
        else {
            return false;
        };

        let Some(group) = group_registry.get(&group_guid) else {
            return false;
        };

        let mut delivered = false;
        for member_guid in &group.members {
            if let Some(member) = player_registry.get(member_guid) {
                delivered |= member.send_tx.send(bytes.clone()).is_ok();
            }
        }

        delivered
    }

