    pub(crate) fn account_data_like_cpp(&self, data_type: u8) -> Option<&AccountDataLikeCpp> {
        self.account_data_like_cpp.get(usize::from(data_type))
    }

    pub(crate) fn account_data_times_like_cpp(
        &self,
        player_guid: ObjectGuid,
        mask: u32,
    ) -> wow_packet::packets::misc::AccountDataTimes {
        let mut times = [0i64; NUM_ACCOUNT_DATA_TYPES];
        for (index, account_data) in self.account_data_like_cpp.iter().enumerate() {
            if mask & (1u32 << index) != 0 {
                times[index] = account_data.time;
            }
        }

        wow_packet::packets::misc::AccountDataTimes::for_times(player_guid, times)
    }

    pub(crate) fn set_account_data_like_cpp(
        &mut self,
        data_type: u8,
        time: i64,
        data: String,
    ) -> bool {
        let Some(account_data) = self.account_data_like_cpp.get_mut(usize::from(data_type)) else {
            return false;
        };

        account_data.time = time;
        account_data.data = data;
        true
    }

    pub(crate) fn tutorial_flags_packet_like_cpp(
        &self,
    ) -> wow_packet::packets::misc::TutorialFlags {
        wow_packet::packets::misc::TutorialFlags {
            tutorial_data: self.tutorials_like_cpp,
        }
    }

    pub(crate) fn load_tutorials_data_values_like_cpp(&mut self, values: Option<[u32; 8]>) {
        self.tutorials_like_cpp = values.unwrap_or([0; 8]);
        self.tutorials_loaded_from_db_like_cpp = values.is_some();
        self.tutorials_loaded_coherently_like_cpp = true;
        self.tutorials_changed_like_cpp = false;
    }

    pub async fn load_tutorials_data_like_cpp(&mut self) {
        self.tutorials_like_cpp = [0; 8];
        self.tutorials_loaded_from_db_like_cpp = false;
        self.tutorials_loaded_coherently_like_cpp = false;
        self.tutorials_changed_like_cpp = false;

        let Some(char_db) = self.char_db().map(Arc::clone) else {
            warn!(
                account = self.account_id,
                "LoadTutorialsData skipped: character database unavailable"
            );
            return;
        };

        let mut stmt = char_db.prepare(CharStatements::SEL_TUTORIALS);
        stmt.set_u32(0, self.account_id);
        let result = match char_db.query(&stmt).await {
            Ok(result) => result,
            Err(error) => {
                warn!(
                    account = self.account_id,
                    "LoadTutorialsData query failed: {error}"
                );
                return;
            }
        };

        if result.is_empty() {
            self.load_tutorials_data_values_like_cpp(None);
            return;
        }

        let mut tutorials = [0u32; 8];
        for (index, tutorial) in tutorials.iter_mut().enumerate() {
            *tutorial = result.try_read::<u32>(index).unwrap_or(0);
        }
        self.load_tutorials_data_values_like_cpp(Some(tutorials));
    }

    pub(crate) fn set_tutorial_int_like_cpp(&mut self, index: usize, value: u32) -> bool {
        let Some(current) = self.tutorials_like_cpp.get_mut(index) else {
            return false;
        };

        if *current != value {
            *current = value;
            self.tutorials_changed_like_cpp = true;
        }
        true
    }

    pub(crate) fn apply_tutorial_action_like_cpp(
        &mut self,
        action: u8,
        tutorial_bit: Option<u32>,
    ) -> bool {
        match action {
            wow_packet::packets::misc::TUTORIAL_ACTION_UPDATE_LIKE_CPP => {
                let Some(tutorial_bit) = tutorial_bit else {
                    return false;
                };
                let index = (tutorial_bit >> 5) as usize;
                if index >= self.tutorials_like_cpp.len() {
                    return false;
                }
                let flag = self.tutorials_like_cpp[index] | (1u32 << (tutorial_bit & 0x1F));
                self.set_tutorial_int_like_cpp(index, flag)
            }
            wow_packet::packets::misc::TUTORIAL_ACTION_CLEAR_LIKE_CPP => {
                for index in 0..self.tutorials_like_cpp.len() {
                    self.set_tutorial_int_like_cpp(index, u32::MAX);
                }
                true
            }
            wow_packet::packets::misc::TUTORIAL_ACTION_RESET_LIKE_CPP => {
                for index in 0..self.tutorials_like_cpp.len() {
                    self.set_tutorial_int_like_cpp(index, 0);
                }
                true
            }
            _ => false,
        }
    }

    pub(crate) fn tutorial_save_statement_like_cpp(
        &self,
        account_id: u32,
    ) -> Option<PreparedStatement> {
        if !self.tutorials_changed_like_cpp || !self.tutorials_loaded_coherently_like_cpp {
            return None;
        }

        let mut stmt = PreparedStatement::new(if self.tutorials_loaded_from_db_like_cpp {
            CharStatements::UPD_TUTORIALS.sql()
        } else {
            CharStatements::INS_TUTORIALS.sql()
        });
        for (index, value) in self.tutorials_like_cpp.iter().copied().enumerate() {
            stmt.set_u32(index, value);
        }
        stmt.set_u32(self.tutorials_like_cpp.len(), account_id);
        Some(stmt)
    }

    async fn save_tutorials_data_like_cpp(&mut self) {
        if !self.tutorials_changed_like_cpp {
            return;
        }

        let Some(char_db) = self.char_db().map(Arc::clone) else {
            warn!(
                account = self.account_id,
                "Skipping SaveTutorialsData because character database is unavailable"
            );
            return;
        };

        let Some(stmt) = self.tutorial_save_statement_like_cpp(self.account_id) else {
            warn!(
                account = self.account_id,
                "Skipping SaveTutorialsData because tutorial data was not loaded coherently"
            );
            return;
        };

        let was_insert = !self.tutorials_loaded_from_db_like_cpp;
        let mut tx = SqlTransaction::new();
        tx.append(stmt);
        match char_db.commit_transaction(tx).await {
            Ok(()) => {
                if was_insert {
                    self.tutorials_loaded_from_db_like_cpp = true;
                }
                self.tutorials_changed_like_cpp = false;
            }
            Err(error) => warn!(
                account = self.account_id,
                "SaveTutorialsData failed: {error}"
            ),
        }
    }

    pub async fn load_global_account_data_like_cpp(&mut self) {
        self.load_account_data_like_cpp(ObjectGuid::EMPTY, GLOBAL_CACHE_MASK_LIKE_CPP)
            .await;
    }

    pub async fn load_player_account_data_like_cpp(&mut self, guid: ObjectGuid) {
        self.load_account_data_like_cpp(guid, PER_CHARACTER_CACHE_MASK_LIKE_CPP)
            .await;
    }

    async fn load_account_data_like_cpp(&mut self, guid: ObjectGuid, mask: u32) {
        debug_assert_eq!(
            GLOBAL_CACHE_MASK_LIKE_CPP | PER_CHARACTER_CACHE_MASK_LIKE_CPP,
            ALL_ACCOUNT_DATA_CACHE_MASK_LIKE_CPP
        );

        for index in 0..NUM_ACCOUNT_DATA_TYPES {
            if mask & (1u32 << index) != 0 {
                self.account_data_like_cpp[index] = AccountDataLikeCpp::default();
            }
        }

        let Some(char_db) = self.char_db().map(Arc::clone) else {
            warn!(
                account = self.account_id,
                mask, "LoadAccountData skipped: character database unavailable"
            );
            return;
        };

        let stmt = if mask == GLOBAL_CACHE_MASK_LIKE_CPP {
            let mut stmt = char_db.prepare(CharStatements::SEL_ACCOUNT_DATA);
            stmt.set_u32(0, self.account_id);
            stmt
        } else {
            let mut stmt = char_db.prepare(CharStatements::SEL_PLAYER_ACCOUNT_DATA);
            stmt.set_u64(0, guid.counter() as u64);
            stmt
        };

        let result = match char_db.query(&stmt).await {
            Ok(result) => result,
            Err(error) => {
                warn!(
                    account = self.account_id,
                    mask, "LoadAccountData query failed: {error}"
                );
                return;
            }
        };

        if result.is_empty() {
            return;
        }

        let table_name = if mask == GLOBAL_CACHE_MASK_LIKE_CPP {
            "account_data"
        } else {
            "character_account_data"
        };
        let mut result = result;
        loop {
            let data_type = result
                .try_read::<u8>(0)
                .unwrap_or(NUM_ACCOUNT_DATA_TYPES as u8);
            if usize::from(data_type) >= NUM_ACCOUNT_DATA_TYPES {
                warn!(
                    table = table_name,
                    data_type, "LoadAccountData ignored invalid account data type like C++"
                );
            } else if mask & (1u32 << data_type) == 0 {
                warn!(
                    table = table_name,
                    data_type,
                    "LoadAccountData ignored account data type inappropriate for table like C++"
                );
            } else {
                self.account_data_like_cpp[usize::from(data_type)].time =
                    result.try_read::<i64>(1).unwrap_or(0);
                self.account_data_like_cpp[usize::from(data_type)].data = result.read_string(2);
            }

            if !result.next_row() {
                break;
            }
        }
    }

    pub async fn set_account_data_persisted_like_cpp(
        &mut self,
        data_type: u8,
        time: i64,
        data: String,
    ) -> bool {
        if usize::from(data_type) >= NUM_ACCOUNT_DATA_TYPES {
            return false;
        }

        let is_global = (1u32 << data_type) & GLOBAL_CACHE_MASK_LIKE_CPP != 0;
        let player_guid_low = self.recent_player_guid_low_like_cpp;

        if !is_global && player_guid_low == 0 {
            return false;
        }

        let Some(char_db) = self.char_db().map(Arc::clone) else {
            warn!(
                account = self.account_id,
                data_type, "SetAccountData persisted fallback: character database unavailable"
            );
            return self.set_account_data_like_cpp(data_type, time, data);
        };

        let stmt = if is_global {
            let mut stmt = char_db.prepare(CharStatements::REP_ACCOUNT_DATA);
            stmt.set_u32(0, self.account_id);
            stmt.set_u8(1, data_type);
            stmt.set_i64(2, time);
            stmt.set_string(3, data.clone());
            stmt
        } else {
            let mut stmt = char_db.prepare(CharStatements::REP_PLAYER_ACCOUNT_DATA);
            stmt.set_u64(0, player_guid_low);
            stmt.set_u8(1, data_type);
            stmt.set_i64(2, time);
            stmt.set_string(3, data.clone());
            stmt
        };

        if let Err(error) = char_db.execute(&stmt).await {
            warn!(
                account = self.account_id,
                data_type, "SetAccountData persistence failed: {error}"
            );
            return false;
        }

        self.set_account_data_like_cpp(data_type, time, data)
    }

