    /// Persist the login snapshot of the player's spell history + charge packets so the
    /// before-add init helper can re-send them (e.g. on far teleport). Mirrors C++
    /// `Player::SendInitialPacketsBeforeAddToMap` reading `GetSpellHistory()`.
    pub(crate) fn record_login_spell_history_packets_like_cpp(
        &mut self,
        history: Vec<SpellHistoryEntry>,
        charges: Vec<SpellChargeEntry>,
    ) {
        self.represented_spell_history_packets_like_cpp = (history, charges);
    }

    /// Login snapshot of spell-history + charge packet entries
    /// (see `record_login_spell_history_packets_like_cpp`).
    pub(crate) fn spell_history_packets_like_cpp(
        &self,
    ) -> (Vec<SpellHistoryEntry>, Vec<SpellChargeEntry>) {
        self.represented_spell_history_packets_like_cpp.clone()
    }

    /// C++ `Unit::m_movementCounter` post-increment: returns the current value and advances
    /// it. Used as the SequenceIndex of movement-control packets (vehicle-rec, collision,
    /// near-teleport, speed/flag) and read for `SMSG_RESUME_TOKEN` on far teleport.
    pub(crate) fn next_movement_counter_like_cpp(&mut self) -> u32 {
        let sequence_index = self.movement_counter_like_cpp;
        self.movement_counter_like_cpp = self.movement_counter_like_cpp.wrapping_add(1);
        sequence_index
    }

    /// C++ `Player::SendInitialPacketsBeforeAddToMap` resets `m_movementCounter` to 0 for a
    /// non-seamless add (login / far teleport). Player.cpp:23483.
    pub(crate) fn reset_movement_counter_like_cpp(&mut self) {
        self.movement_counter_like_cpp = 0;
    }

    /// Current `Unit::m_movementCounter` value (read without advancing). C++ reads this for
    /// `SMSG_RESUME_TOKEN.SequenceIndex` on far teleport (MovementHandler.cpp:109), before
    /// `SendInitialPacketsBeforeAddToMap` resets it.
    pub(crate) fn movement_counter_like_cpp(&self) -> u32 {
        self.movement_counter_like_cpp
    }

    /// C++ `CollectionMgr::SaveAccountMounts`.
    pub(crate) fn account_mount_save_rows_like_cpp(&self) -> Vec<AccountMountSaveRowLikeCpp> {
        let bnet_account_id = self.battlenet_account_id();
        self.account_mount_rows_like_cpp()
            .into_iter()
            .filter_map(|mount| {
                Some(AccountMountSaveRowLikeCpp {
                    bnet_account_id,
                    mount_spell_id: u32::try_from(mount.spell_id).ok()?,
                    flags: mount.flags,
                })
            })
            .collect()
    }

    pub(crate) fn mount_set_favorite_like_cpp(
        &mut self,
        mount_spell_id: u32,
        is_favorite: bool,
    ) -> bool {
        let Ok(spell_id) = i32::try_from(mount_spell_id) else {
            return false;
        };
        let Some(flags) = self.account_mounts_like_cpp.get_mut(&spell_id) else {
            return false;
        };

        if is_favorite {
            *flags |= 0x01;
        } else {
            *flags &= !0x01;
        }
        let updated_flags = *flags;

        self.send_packet(&AccountMountUpdate::partial(vec![AccountMount {
            spell_id,
            flags: updated_flags,
        }]));
        true
    }

