    pub(crate) fn cancel_represented_trade_like_cpp(&mut self, status: u8, sendback: bool) {
        use wow_packet::ServerPacket;

        let Some(partner_guid) = self.represented_active_trade_partner_like_cpp else {
            return;
        };

        let packet_bytes = TradeStatus::cancel_like_cpp(status).to_bytes();
        self.record_represented_trade_cancel_like_cpp(status);
        self.clear_represented_active_trade_partner_like_cpp();
        self.represented_trade_accepted_like_cpp = false;

        if sendback {
            self.send_raw_packet(&packet_bytes);
        }

        if let Some(registry) = self.player_registry()
            && let Some(partner) = registry.get(&partner_guid)
        {
            let _ = partner
                .command_tx
                .try_send(SessionCommand::CancelRepresentedTradeLikeCpp(
                    wow_network::player_registry::CancelRepresentedTradeLikeCppCommand {
                        status,
                        packet_bytes,
                    },
                ));
        }
    }

    pub(crate) fn clear_represented_trade_item_like_cpp(&mut self, trade_slot: u8) {
        use wow_packet::ServerPacket;

        let Some(partner_guid) = self.represented_active_trade_partner_like_cpp else {
            return;
        };

        self.represented_trade_client_state_index_like_cpp = self
            .represented_trade_client_state_index_like_cpp
            .wrapping_add(1);

        if trade_slot >= TRADE_SLOT_COUNT_LIKE_CPP {
            return;
        }

        let slot = trade_slot as usize;
        if self.represented_trade_items_like_cpp[slot].is_none() {
            return;
        }

        self.represented_trade_items_like_cpp[slot] = None;
        self.represented_trade_accepted_like_cpp = false;
        self.represented_trade_server_state_index_like_cpp = self
            .represented_trade_server_state_index_like_cpp
            .wrapping_add(1);

        let packet_bytes =
            TradeStatus::status_only_like_cpp(TRADE_STATUS_UNACCEPTED_LIKE_CPP).to_bytes();
        self.send_raw_packet(&packet_bytes);

        if let Some(registry) = self.player_registry()
            && let Some(partner) = registry.get(&partner_guid)
        {
            let _ = partner
                .command_tx
                .try_send(SessionCommand::UnacceptRepresentedTradeLikeCpp(
                    wow_network::player_registry::UnacceptRepresentedTradeLikeCppCommand {
                        packet_bytes,
                    },
                ));
        }
    }

    pub(crate) fn set_represented_trade_item_like_cpp(
        &mut self,
        trade_slot: u8,
        pack_slot: u8,
        item_slot_in_pack: u8,
    ) {
        use wow_packet::ServerPacket;

        let Some(partner_guid) = self.represented_active_trade_partner_like_cpp else {
            return;
        };

        if trade_slot >= TRADE_SLOT_COUNT_LIKE_CPP {
            let packet_bytes =
                TradeStatus::cancel_like_cpp(TRADE_STATUS_CANCELLED_LIKE_CPP).to_bytes();
            self.send_raw_packet(&packet_bytes);
            return;
        }

        let Some(item) = self.get_inventory_item_by_pos(pack_slot, item_slot_in_pack) else {
            let packet_bytes =
                TradeStatus::cancel_like_cpp(TRADE_STATUS_CANCELLED_LIKE_CPP).to_bytes();
            self.send_raw_packet(&packet_bytes);
            return;
        };

        if self
            .represented_trade_items_like_cpp
            .iter()
            .any(|trade_item| *trade_item == Some(item.guid))
        {
            let packet_bytes =
                TradeStatus::cancel_like_cpp(TRADE_STATUS_CANCELLED_LIKE_CPP).to_bytes();
            self.send_raw_packet(&packet_bytes);
            return;
        }

        self.represented_trade_client_state_index_like_cpp = self
            .represented_trade_client_state_index_like_cpp
            .wrapping_add(1);
        self.represented_trade_items_like_cpp[trade_slot as usize] = Some(item.guid);
        self.represented_trade_accepted_like_cpp = false;
        self.represented_trade_server_state_index_like_cpp = self
            .represented_trade_server_state_index_like_cpp
            .wrapping_add(1);

        let packet_bytes =
            TradeStatus::status_only_like_cpp(TRADE_STATUS_UNACCEPTED_LIKE_CPP).to_bytes();
        self.send_raw_packet(&packet_bytes);

        if let Some(registry) = self.player_registry()
            && let Some(partner) = registry.get(&partner_guid)
        {
            let _ = partner
                .command_tx
                .try_send(SessionCommand::UnacceptRepresentedTradeLikeCpp(
                    wow_network::player_registry::UnacceptRepresentedTradeLikeCppCommand {
                        packet_bytes,
                    },
                ));
        }
    }

    pub(crate) fn set_represented_trade_gold_like_cpp(&mut self, coinage: u64) {
        use wow_packet::ServerPacket;

        let Some(partner_guid) = self.represented_active_trade_partner_like_cpp else {
            return;
        };

        self.represented_trade_client_state_index_like_cpp = self
            .represented_trade_client_state_index_like_cpp
            .wrapping_add(1);

        if self.represented_trade_money_like_cpp == coinage {
            return;
        }

        if self.player_gold_like_cpp() < coinage {
            let packet_bytes =
                TradeStatus::failed_like_cpp(EQUIP_ERR_NOT_ENOUGH_MONEY_LIKE_CPP, 0).to_bytes();
            self.send_raw_packet(&packet_bytes);
            return;
        }

        self.represented_trade_money_like_cpp = coinage;
        self.represented_trade_accepted_like_cpp = false;
        self.represented_trade_server_state_index_like_cpp = self
            .represented_trade_server_state_index_like_cpp
            .wrapping_add(1);

        let packet_bytes =
            TradeStatus::status_only_like_cpp(TRADE_STATUS_UNACCEPTED_LIKE_CPP).to_bytes();
        self.send_raw_packet(&packet_bytes);

        if let Some(registry) = self.player_registry()
            && let Some(partner) = registry.get(&partner_guid)
        {
            let _ = partner
                .command_tx
                .try_send(SessionCommand::UnacceptRepresentedTradeLikeCpp(
                    wow_network::player_registry::UnacceptRepresentedTradeLikeCppCommand {
                        packet_bytes,
                    },
                ));
        }
    }

    pub(crate) fn set_represented_trade_spell_like_cpp(
        &mut self,
        spell_id: u32,
        pack_slot: u8,
        item_slot_in_pack: u8,
    ) {
        let Some(partner_guid) = self.represented_active_trade_partner_like_cpp else {
            return;
        };

        if spell_id == 0 {
            self.set_represented_trade_spell_state_like_cpp(partner_guid, 0, None);
            return;
        }

        let cast_item_guid = if pack_slot != NULL_BAG || item_slot_in_pack != NULL_SLOT {
            self.get_inventory_item_by_pos(pack_slot, item_slot_in_pack)
                .map(|item| item.guid)
        } else {
            None
        };

        let Ok(spell_id_i32) = i32::try_from(spell_id) else {
            self.set_represented_trade_spell_state_like_cpp(partner_guid, 0, None);
            return;
        };

        let Some(spell_store) = self.spell_store() else {
            self.set_represented_trade_spell_state_like_cpp(partner_guid, 0, None);
            return;
        };

        if spell_store.get(spell_id_i32).is_none() {
            self.set_represented_trade_spell_state_like_cpp(partner_guid, 0, None);
            return;
        }

        if !self.known_spells_like_cpp().contains(&spell_id_i32) {
            self.set_represented_trade_spell_state_like_cpp(partner_guid, 0, None);
            return;
        }

        self.set_represented_trade_spell_state_like_cpp(partner_guid, spell_id, cast_item_guid);
    }

    fn set_represented_trade_spell_state_like_cpp(
        &mut self,
        partner_guid: ObjectGuid,
        spell_id: u32,
        cast_item_guid: Option<ObjectGuid>,
    ) {
        use wow_packet::ServerPacket;

        if self.represented_trade_spell_like_cpp == spell_id
            && self.represented_trade_spell_cast_item_like_cpp == cast_item_guid
        {
            return;
        }

        self.represented_trade_spell_like_cpp = spell_id;
        self.represented_trade_spell_cast_item_like_cpp = cast_item_guid;
        self.represented_trade_accepted_like_cpp = false;
        self.represented_trade_server_state_index_like_cpp = self
            .represented_trade_server_state_index_like_cpp
            .wrapping_add(1);

        let packet_bytes =
            TradeStatus::status_only_like_cpp(TRADE_STATUS_UNACCEPTED_LIKE_CPP).to_bytes();
        self.send_raw_packet(&packet_bytes);

        if let Some(registry) = self.player_registry()
            && let Some(partner) = registry.get(&partner_guid)
        {
            let _ = partner
                .command_tx
                .try_send(SessionCommand::UnacceptRepresentedTradeLikeCpp(
                    wow_network::player_registry::UnacceptRepresentedTradeLikeCppCommand {
                        packet_bytes,
                    },
                ));
        }
    }

    pub(crate) fn accept_represented_trade_like_cpp(&mut self, state_index: u32) {
        use wow_packet::ServerPacket;

        let Some(partner_guid) = self.represented_active_trade_partner_like_cpp else {
            return;
        };

        self.represented_trade_accepted_like_cpp = true;

        if self.represented_partner_trade_server_state_index_like_cpp != state_index {
            self.represented_trade_accepted_like_cpp = false;
            let packet_bytes =
                TradeStatus::status_only_like_cpp(TRADE_STATUS_STATE_CHANGED_LIKE_CPP).to_bytes();
            self.send_raw_packet(&packet_bytes);
            return;
        }

        let packet_bytes =
            TradeStatus::status_only_like_cpp(TRADE_STATUS_ACCEPTED_LIKE_CPP).to_bytes();
        if let Some(registry) = self.player_registry()
            && let Some(partner) = registry.get(&partner_guid)
        {
            let _ = partner
                .command_tx
                .try_send(SessionCommand::SendRepresentedTradeStatusLikeCpp(
                    wow_network::player_registry::SendRepresentedTradeStatusLikeCppCommand {
                        packet_bytes,
                    },
                ));
        }
    }

