    pub(crate) fn use_represented_gameobject_flagdrop_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        gameobject_entry: u32,
        source: wow_entities::FlagDropUseSource,
    ) -> bool {
        if !self
            .represented_player_can_use_battleground_object_like_cpp(gameobject_guid, player_guid)
        {
            return false;
        }
        let Some(bg_type_id) = self.represented_player_battleground_type_id_or_reject_like_cpp(
            gameobject_guid,
            player_guid,
        ) else {
            return false;
        };
        if self.represented_player_reject_battleground_object_vehicle_like_cpp(
            gameobject_guid,
            player_guid,
        ) {
            return false;
        }

        let click_target = match gameobject_entry {
            179785 | 179786 if bg_type_id == BATTLEGROUND_WS_LIKE_CPP => {
                BattlegroundFlagDropClickTarget::WarsongGulch
            }
            184142 if bg_type_id == BATTLEGROUND_EY_LIKE_CPP => {
                BattlegroundFlagDropClickTarget::EyeOfTheStorm
            }
            _ => BattlegroundFlagDropClickTarget::None,
        };

        self.remove_represented_stealth_or_invisibility_auras_by_type_like_cpp();
        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::RemoveStealthOrInvisibilityAuras {
                gameobject_guid,
                player_guid,
            },
        );
        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::BattlegroundFlagDropClicked {
                gameobject_guid,
                player_guid,
                gameobject_entry,
                click_target,
                event_id: source.event_id,
                pickup_spell_id: source.pickup_spell_id,
                expire_duration_ms: source.expire_duration_ms,
            },
        );
        if source.event_id != 0 {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::TriggerGameEvent {
                    gameobject_guid,
                    player_guid,
                    event_id: source.event_id,
                },
            );
        }
        self.send_represented_gameobject_delete_packets_like_cpp(gameobject_guid);
        self.represented_gameobject_use_effects
            .push(RepresentedGameObjectUseEffect::GameObjectDeleted { gameobject_guid });

        true
    }

    pub(crate) fn apply_represented_new_flag_state_command_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: Option<ObjectGuid>,
        new_state: RepresentedNewFlagStateRequest,
        respawn_time_ms: u32,
    ) -> bool {
        let state = self
            .represented_gameobject_use_states
            .entry(gameobject_guid)
            .or_default();
        let old_state = state
            .new_flag_state
            .unwrap_or(RepresentedNewFlagStateRequest::InBase);
        if old_state == new_state {
            return false;
        }

        state.new_flag_state = Some(new_state);
        state.new_flag_carrier_guid = if new_state == RepresentedNewFlagStateRequest::Taken {
            player_guid
        } else {
            None
        };

        if new_state == RepresentedNewFlagStateRequest::Taken
            && old_state == RepresentedNewFlagStateRequest::InBase
        {
            state.new_flag_taken_from_base_game_time_ms = Some(Self::game_time_ms_like_cpp());
        } else if matches!(
            new_state,
            RepresentedNewFlagStateRequest::InBase | RepresentedNewFlagStateRequest::Respawning
        ) {
            state.new_flag_taken_from_base_game_time_ms = None;
        }

        state.new_flag_respawn_until = (new_state == RepresentedNewFlagStateRequest::Respawning)
            .then(|| Instant::now() + Duration::from_millis(u64::from(respawn_time_ms)));

        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::NewFlagOwnerStateRequested {
                gameobject_guid,
                player_guid: player_guid.unwrap_or(ObjectGuid::EMPTY),
                state: new_state,
            },
        );
        true
    }

    pub(crate) fn use_represented_gameobject_new_flag_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        gameobject_entry: u32,
        source: wow_entities::NewFlagUseSource,
    ) -> bool {
        if !self
            .represented_player_can_use_battleground_object_like_cpp(gameobject_guid, player_guid)
        {
            return false;
        }
        let current_state = self
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .and_then(|state| state.new_flag_state)
            .unwrap_or(RepresentedNewFlagStateRequest::InBase);
        if current_state != RepresentedNewFlagStateRequest::InBase {
            return false;
        }
        {
            let state = self
                .represented_gameobject_use_states
                .entry(gameobject_guid)
                .or_default();
            state.new_flag_return_on_defender_interact = Some(source.return_on_defender_interact);
            state.new_flag_pickup_spell_id = Some(source.pickup_spell_id);
            state.new_flag_entry = Some(gameobject_entry);
        }

        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::NewFlagPickupRequested {
                gameobject_guid,
                player_guid,
                pickup_spell_id: source.pickup_spell_id,
                expire_duration_ms: source.expire_duration_ms,
                respawn_time_ms: source.respawn_time_ms,
                flag_drop_entry: source.flag_drop_entry,
                exclusive_category: source.exclusive_category,
                world_state_id: source.world_state_id,
                return_on_defender_interact: source.return_on_defender_interact,
            },
        );

        self.apply_represented_gameobject_post_use_spell_like_cpp(
            gameobject_guid,
            player_guid,
            gameobject_entry,
            wow_entities::GAMEOBJECT_TYPE_NEW_FLAG,
            source.pickup_spell_id,
            false,
            RepresentedGameObjectSpellCaster::GameObject,
            gameobject_guid,
        );

        true
    }

    pub(crate) fn use_represented_gameobject_new_flag_drop_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        source: wow_entities::NewFlagDropUseSource,
    ) -> bool {
        if !self
            .represented_player_can_use_battleground_object_like_cpp(gameobject_guid, player_guid)
        {
            return false;
        }

        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::NewFlagDropInteracted {
                gameobject_guid,
                player_guid,
                spawn_vignette_id: source.spawn_vignette_id,
            },
        );

        let owner_guid = self
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .and_then(|state| state.owner_guid);
        if let Some(owner_guid) = owner_guid {
            let Some(owner_state) = self.represented_gameobject_use_states.get(&owner_guid) else {
                self.send_represented_gameobject_delete_packets_like_cpp(gameobject_guid);
                self.represented_gameobject_use_effects
                    .push(RepresentedGameObjectUseEffect::GameObjectDeleted { gameobject_guid });
                return true;
            };
            if owner_state.go_type != Some(wow_entities::GAMEOBJECT_TYPE_NEW_FLAG as u8) {
                return false;
            }
            if owner_state.new_flag_state != Some(RepresentedNewFlagStateRequest::Dropped) {
                return false;
            }
            let return_on_defender_interact = owner_state
                .new_flag_return_on_defender_interact
                .unwrap_or(false);
            let owner_pickup_spell_id = owner_state.new_flag_pickup_spell_id.unwrap_or(0);
            let owner_entry = owner_state.new_flag_entry.unwrap_or(0);
            let defender_interact = self
                .represented_gameobject_is_friendly_to_player_like_cpp(owner_guid)
                .map(|friendly| !friendly)
                .unwrap_or(false);
            if defender_interact && return_on_defender_interact {
                self.send_represented_gameobject_delete_packets_like_cpp(gameobject_guid);
                self.represented_gameobject_use_effects
                    .push(RepresentedGameObjectUseEffect::GameObjectDeleted { gameobject_guid });
                self.apply_represented_new_flag_state_command_like_cpp(
                    owner_guid,
                    Some(player_guid),
                    RepresentedNewFlagStateRequest::InBase,
                    0,
                );
                return true;
            }

            if self.apply_represented_gameobject_post_use_spell_like_cpp_internal(
                owner_guid,
                player_guid,
                owner_entry,
                wow_entities::GAMEOBJECT_TYPE_NEW_FLAG,
                owner_pickup_spell_id,
                true,
                RepresentedGameObjectSpellCaster::GameObject,
                owner_guid,
                false,
            ) {
                self.send_represented_gameobject_delete_packets_like_cpp(gameobject_guid);
                self.represented_gameobject_use_effects
                    .push(RepresentedGameObjectUseEffect::GameObjectDeleted { gameobject_guid });
                self.apply_represented_new_flag_state_command_like_cpp(
                    owner_guid,
                    Some(player_guid),
                    RepresentedNewFlagStateRequest::Taken,
                    0,
                );
                return true;
            }
        }

        self.send_represented_gameobject_delete_packets_like_cpp(gameobject_guid);
        self.represented_gameobject_use_effects
            .push(RepresentedGameObjectUseEffect::GameObjectDeleted { gameobject_guid });

        true
    }

    pub(crate) fn use_represented_gameobject_ritual_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        source: wow_entities::RitualUseSource,
    ) -> bool {
        let (owner_guid, ritual_owner_guid, owner_current_channeled_spell_active) = {
            let state = self.represented_gameobject_use_states.get(&gameobject_guid);
            (
                state.and_then(|state| state.owner_guid),
                state.and_then(|state| state.ritual_owner_guid),
                state.and_then(|state| state.owner_current_channeled_spell_active),
            )
        };

        let ritual_spell_caster_guid = if let Some(owner_guid) = owner_guid {
            if owner_guid == player_guid {
                return false;
            }
            if source.casters_grouped
                && !self.represented_player_is_same_raid_with_like_cpp(player_guid, owner_guid)
            {
                return false;
            }
            if owner_current_channeled_spell_active == Some(false) {
                return false;
            }
            owner_guid
        } else {
            let ritual_owner_guid = ritual_owner_guid.unwrap_or_else(|| {
                self.represented_gameobject_use_states
                    .get(&gameobject_guid)
                    .and_then(|state| state.unique_users.first().copied())
                    .unwrap_or(player_guid)
            });
            if player_guid != ritual_owner_guid
                && source.casters_grouped
                && !self
                    .represented_player_is_same_raid_with_like_cpp(player_guid, ritual_owner_guid)
            {
                return false;
            }
            self.represented_gameobject_use_states
                .entry(gameobject_guid)
                .or_default()
                .ritual_owner_guid
                .get_or_insert(ritual_owner_guid);
            ritual_owner_guid
        };

        let unique_user_count = {
            let state = self
                .represented_gameobject_use_states
                .entry(gameobject_guid)
                .or_default();
            if !state.unique_users.contains(&player_guid) {
                state.unique_users.push(player_guid);
            }
            state.unique_users.len() as u32
        };

        if source.anim_spell_id != 0 {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::CastSpell {
                    gameobject_guid,
                    player_guid,
                    spell_id: source.anim_spell_id,
                },
            );
        }

        if unique_user_count != source.casters_required {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::RitualWaitingForParticipants {
                    gameobject_guid,
                    player_guid,
                    unique_user_count,
                    casters_required: source.casters_required,
                },
            );
            return false;
        }

        let mut final_spell_id = source.spell_id;
        let mut triggered = source.anim_spell_id != 0;
        if final_spell_id == 62330 {
            final_spell_id = 61993;
            triggered = true;
        }

        if source.caster_target_spell_id != 0 && source.caster_target_spell_id != 1 {
            let unique_users = self
                .represented_gameobject_use_states
                .get(&gameobject_guid)
                .map(|state| state.unique_users.clone())
                .unwrap_or_default();
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::RitualCasterTargetSpellRequested {
                    gameobject_guid,
                    player_guid,
                    spell_id: source.caster_target_spell_id,
                    target_count: source.caster_target_spell_targets,
                },
            );
            for _ in 0..source.caster_target_spell_targets {
                let Some(target_guid) = unique_users
                    .choose(&mut self.represented_runtime_rng_like_cpp)
                    .copied()
                else {
                    continue;
                };
                if !self
                    .player_registry
                    .as_ref()
                    .is_some_and(|registry| registry.contains_key(&target_guid))
                {
                    continue;
                }
                self.represented_gameobject_use_effects.push(
                    RepresentedGameObjectUseEffect::RitualCasterTargetSpellCast {
                        gameobject_guid,
                        caster_guid: ritual_spell_caster_guid,
                        target_guid,
                        spell_id: source.caster_target_spell_id,
                        triggered: true,
                    },
                );
            }
        }

        if let Some(owner_guid) = owner_guid {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::FinishChanneledSpell {
                    player_guid: owner_guid,
                },
            );
        }

        if source.persistent {
            let state = self
                .represented_gameobject_use_states
                .entry(gameobject_guid)
                .or_default();
            state.ritual_owner_guid = None;
            state.unique_users.clear();
            state.use_count = 0;
        } else {
            self.represented_gameobject_use_states
                .entry(gameobject_guid)
                .or_default()
                .loot_state = Some(wow_entities::LootState::JustDeactivated);
        }

        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::RitualCompleted {
                gameobject_guid,
                player_guid,
                final_spell_id,
                triggered,
                persistent: source.persistent,
                unique_user_count,
            },
        );
        self.apply_represented_gameobject_post_use_spell_like_cpp(
            gameobject_guid,
            player_guid,
            gameobject_guid.entry(),
            wow_entities::GAMEOBJECT_TYPE_RITUAL,
            final_spell_id,
            triggered,
            RepresentedGameObjectSpellCaster::User,
            ritual_spell_caster_guid,
        );

        true
    }

    pub(crate) fn use_represented_gameobject_meeting_stone_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        gameobject_entry: u32,
        source: wow_entities::MeetingStoneUseSource,
    ) -> bool {
        let target_guid = self.selection_guid_like_cpp();
        if !target_guid.is_some_and(|target_guid| {
            target_guid != player_guid
                && self.represented_player_is_same_raid_with_like_cpp(player_guid, target_guid)
                && self
                    .player_registry
                    .as_ref()
                    .is_some_and(|registry| registry.contains_key(&target_guid))
        }) {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::MeetingStoneTargetRejected {
                    gameobject_guid,
                    player_guid,
                    target_guid,
                },
            );
            return false;
        }
        let target_guid = target_guid.expect("checked above");
        if let Some(content_tuning) = self
            .content_tuning_store
            .as_ref()
            .and_then(|store| store.get(source.content_tuning_id))
        {
            let player_level = self.player_level_like_cpp();
            let target_level = self
                .player_registry
                .as_ref()
                .and_then(|registry| registry.get(&target_guid).map(|target| target.level))
                .unwrap_or(0);
            if i32::from(player_level) < content_tuning.max_level
                || i32::from(target_level) < content_tuning.max_level
            {
                self.represented_gameobject_use_effects.push(
                    RepresentedGameObjectUseEffect::MeetingStoneLevelRejected {
                        gameobject_guid,
                        player_guid,
                        target_guid,
                        player_level,
                        target_level,
                        required_level: content_tuning.max_level,
                    },
                );
                return false;
            }
        }
        let spell_id = if gameobject_entry == 194097 {
            61994
        } else {
            59782
        };

        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::MeetingStoneSummonRequested {
                gameobject_guid,
                player_guid,
                target_guid,
                gameobject_entry,
                spell_id,
                area_id: source.area_id,
                prevent_unfriendly_outside_instances: source.prevent_unfriendly_outside_instances,
            },
        );

        self.apply_represented_gameobject_post_use_spell_like_cpp(
            gameobject_guid,
            player_guid,
            gameobject_entry,
            wow_entities::GAMEOBJECT_TYPE_MEETINGSTONE,
            spell_id,
            false,
            RepresentedGameObjectSpellCaster::User,
            player_guid,
        );

        true
    }

    pub(crate) fn apply_represented_gameobject_post_use_spell_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        gameobject_entry: u32,
        go_type: u32,
        spell_id: u32,
        triggered: bool,
        caster: RepresentedGameObjectSpellCaster,
        caster_guid: ObjectGuid,
    ) -> bool {
        self.apply_represented_gameobject_post_use_spell_like_cpp_internal(
            gameobject_guid,
            player_guid,
            gameobject_entry,
            go_type,
            spell_id,
            triggered,
            caster,
            caster_guid,
            true,
        )
    }

    fn apply_represented_gameobject_post_use_spell_like_cpp_internal(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        gameobject_entry: u32,
        go_type: u32,
        spell_id: u32,
        triggered: bool,
        caster: RepresentedGameObjectSpellCaster,
        caster_guid: ObjectGuid,
        apply_new_flag_taken_state: bool,
    ) -> bool {
        if spell_id == 0 {
            return false;
        }

        let spell_lookup_difficulty_id =
            self.represented_gameobject_spell_lookup_difficulty_id_like_cpp();
        let spell_info_missing = self
            .spell_store()
            .is_some_and(|store| store.get(spell_id as i32).is_none());

        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::OutdoorPvpCustomSpellRequested {
                gameobject_guid,
                player_guid,
                gameobject_entry,
                spell_id,
                go_type,
                spell_lookup_difficulty_id,
                spell_info_missing,
            },
        );

        if spell_info_missing {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::GameObjectPostUseSpellMissing {
                    gameobject_guid,
                    player_guid,
                    gameobject_entry,
                    spell_id,
                    go_type,
                    spell_lookup_difficulty_id,
                },
            );
            return false;
        }

        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::GameObjectPostUseSpellCast {
                gameobject_guid,
                target_guid: player_guid,
                caster_guid,
                spell_id,
                triggered,
                caster,
                spell_lookup_difficulty_id,
            },
        );

        if apply_new_flag_taken_state
            && go_type == wow_entities::GAMEOBJECT_TYPE_NEW_FLAG
            && caster == RepresentedGameObjectSpellCaster::GameObject
        {
            self.apply_represented_new_flag_state_command_like_cpp(
                gameobject_guid,
                Some(player_guid),
                RepresentedNewFlagStateRequest::Taken,
                0,
            );
        }
        true
    }

    pub(crate) fn use_represented_gameobject_fishing_node_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
    ) -> bool {
        let known_owner = self
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .and_then(|state| state.owner_guid);
        if let Some(owner_guid) = known_owner {
            if owner_guid != player_guid {
                self.represented_gameobject_use_effects.push(
                    RepresentedGameObjectUseEffect::FishingNodeOwnerRejected {
                        gameobject_guid,
                        player_guid,
                        owner_guid,
                    },
                );
                return false;
            }
        }

        let current_loot_state = self
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .and_then(|state| state.loot_state)
            .unwrap_or(wow_entities::LootState::Ready);

        match current_loot_state {
            wow_entities::LootState::Ready => {
                let (
                    area_fishing_level,
                    player_fishing_level,
                    fishing_roll,
                    explicit_fishing_hole_guid,
                ) = {
                    let represented_area_fishing_level =
                        self.represented_fishing_base_skill_level_like_cpp(gameobject_guid);
                    let represented_player_fishing_level = self
                        .player_profession_skill_value_for_exp_like_cpp(SKILL_FISHING_LIKE_CPP, 0);
                    let state = self
                        .represented_gameobject_use_states
                        .entry(gameobject_guid)
                        .or_default();
                    state.loot_state = Some(wow_entities::LootState::Activated);
                    state.loot_state_unit_guid = player_guid;
                    state.go_state = Some(wow_entities::GoState::Active);
                    state.gameobject_flags = wow_entities::GO_FLAG_IN_MULTI_USE;
                    (
                        state.fishing_area_level.or(represented_area_fishing_level),
                        state
                            .player_fishing_level
                            .or(Some(represented_player_fishing_level)),
                        state.fishing_roll,
                        state.nearby_fishing_hole_guid,
                    )
                };
                let fishing_hole_guid = explicit_fishing_hole_guid.or_else(|| {
                    self.lookup_represented_fishing_hole_around_like_cpp(gameobject_guid)
                });
                self.represented_gameobject_use_effects.push(
                    RepresentedGameObjectUseEffect::FishingNodeActivated {
                        gameobject_guid,
                        player_guid,
                    },
                );
                if let Some(area_fishing_level) = area_fishing_level {
                    self.represented_gameobject_use_effects.push(
                        RepresentedGameObjectUseEffect::FishingSkillUpdated {
                            gameobject_guid,
                            player_guid,
                        },
                    );
                    let player_fishing_level = player_fishing_level.unwrap_or(0);
                    let roll = fishing_roll.unwrap_or(100).clamp(1, 100);
                    let chance =
                        if area_fishing_level > 0 && player_fishing_level < area_fishing_level {
                            (((player_fishing_level as f64 / area_fishing_level as f64).powi(2)
                                * 100.0) as i32)
                                .max(1)
                        } else {
                            100
                        };
                    self.represented_gameobject_use_effects.push(
                        RepresentedGameObjectUseEffect::FishingLootRoll {
                            gameobject_guid,
                            player_guid,
                            player_fishing_level,
                            area_fishing_level,
                            chance,
                            roll,
                        },
                    );

                    let fishing_success = chance >= roll || fishing_hole_guid.is_some();
                    if fishing_success {
                        self.record_represented_gameobject_owner_guid_like_cpp(
                            gameobject_guid,
                            player_guid,
                        );
                        self.set_canonical_gameobject_spell_id_like_cpp(gameobject_guid, 0);
                    }

                    if let Some(fishing_hole_guid) = fishing_hole_guid {
                        self.represented_gameobject_use_states
                            .entry(gameobject_guid)
                            .or_default()
                            .loot_state = Some(wow_entities::LootState::JustDeactivated);
                        self.represented_gameobject_use_effects.push(
                            RepresentedGameObjectUseEffect::FishingHoleDelegated {
                                gameobject_guid,
                                player_guid,
                                fishing_hole_guid,
                            },
                        );
                    } else {
                        let loot_type = if chance >= roll {
                            wow_packet::packets::loot::LOOT_TYPE_FISHING_LIKE_CPP
                        } else {
                            wow_packet::packets::loot::LOOT_TYPE_FISHING_JUNK_LIKE_CPP
                        };
                        self.represented_gameobject_use_effects.push(
                            RepresentedGameObjectUseEffect::FishingLootRequested {
                                gameobject_guid,
                                player_guid,
                                loot_type,
                            },
                        );
                    }
                }
            }
            wow_entities::LootState::JustDeactivated => {}
            _ => {
                self.represented_gameobject_use_states
                    .entry(gameobject_guid)
                    .or_default()
                    .loot_state = Some(wow_entities::LootState::JustDeactivated);
                self.represented_gameobject_use_effects.push(
                    RepresentedGameObjectUseEffect::FishNotHooked {
                        gameobject_guid,
                        player_guid,
                    },
                );
                self.send_packet(&wow_packet::packets::misc::FishNotHooked);
            }
        }

        self.represented_gameobject_use_effects
            .push(RepresentedGameObjectUseEffect::FinishChanneledSpell { player_guid });

        true
    }

    fn lookup_represented_fishing_hole_around_like_cpp(
        &self,
        gameobject_guid: ObjectGuid,
    ) -> Option<ObjectGuid> {
        const FISHING_HOLE_SEARCH_RANGE_LIKE_CPP: f32 =
            20.0 + wow_movement::CONTACT_DISTANCE_LIKE_CPP;

        let source = self
            .represented_gameobject_use_states
            .get(&gameobject_guid)?;
        let source_position = source.position?;
        let source_map_id = source.map_id;
        let now = Instant::now();
        let mut nearest: Option<(ObjectGuid, f32)> = None;

        for (candidate_guid, candidate) in &self.represented_gameobject_use_states {
            if *candidate_guid == gameobject_guid {
                continue;
            }
            if candidate.go_type != Some(wow_entities::GAMEOBJECT_TYPE_FISHING_HOLE as u8) {
                continue;
            }
            if source_map_id.is_some() && candidate.map_id != source_map_id {
                continue;
            }
            if candidate
                .per_player_despawn_until
                .is_some_and(|until| until > now)
            {
                continue;
            }
            let Some(candidate_position) = candidate.position else {
                continue;
            };
            let Some(fishing_hole_radius) = candidate.fishing_hole_radius else {
                continue;
            };
            if !source_position
                .is_within_dist(&candidate_position, FISHING_HOLE_SEARCH_RANGE_LIKE_CPP)
                || !source_position.is_within_dist(&candidate_position, fishing_hole_radius)
            {
                continue;
            }
            let distance = source_position.distance(&candidate_position);
            if nearest.is_none_or(|(_, nearest_distance)| distance < nearest_distance) {
                nearest = Some((*candidate_guid, distance));
            }
        }

        nearest.map(|(guid, _)| guid)
    }

    pub(crate) fn represented_gameobject_area_id_like_cpp(
        &self,
        gameobject_guid: ObjectGuid,
    ) -> u32 {
        self.represented_gameobject_use_states
            .get(&gameobject_guid)
            .and_then(|state| state.area_id)
            .unwrap_or_else(|| self.player_zone_area_like_cpp().1)
    }

    fn represented_fishing_base_skill_level_like_cpp(
        &self,
        gameobject_guid: ObjectGuid,
    ) -> Option<i32> {
        let area_id = self
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .and_then(|state| state.area_id)?;
        let area_store = self.area_table_store()?;
        let fishing_store = self.fishing_base_skill_store()?;
        Some(fishing_store.base_skill_level_like_cpp(area_store, area_id))
    }

    fn player_profession_skill_value_for_exp_like_cpp(
        &self,
        parent_skill_id: u16,
        expansion: i32,
    ) -> i32 {
        let Some(skill_line_store) = self.skill_line_store() else {
            return 0;
        };
        let resolved_skill_id = skill_line_store
            .profession_skill_for_exp_like_cpp(u32::from(parent_skill_id), expansion);
        if resolved_skill_id == 0 {
            return 0;
        }
        u16::try_from(resolved_skill_id)
            .ok()
            .map(|skill_id| i32::from(self.player_skill_value_like_cpp(skill_id)))
            .unwrap_or(0)
    }

    fn represented_gameobject_spell_lookup_difficulty_id_like_cpp(&self) -> u8 {
        self.current_map_difficulty_id_like_cpp()
    }

    pub(crate) fn use_represented_creature_questgiver_like_cpp(
        &mut self,
        creature_guid: ObjectGuid,
        creature_entry: u32,
    ) -> bool {
        let Some(quest_store) = self.quest_store.as_ref().map(Arc::clone) else {
            return false;
        };

        let menu_items =
            self.represented_creature_quest_menu_items_like_cpp(&quest_store, creature_entry);
        let ender_candidates = quest_store
            .quests_for_ender(creature_entry)
            .iter()
            .map(|quest| {
                (
                    quest.id,
                    quest.log_title.clone(),
                    quest.allowable_races,
                    quest.allowable_classes,
                    quest.min_level,
                    quest.max_level,
                    self.player_quests
                        .get(&quest.id)
                        .map(|status| status.status),
                    self.rewarded_quests.contains(&quest.id),
                )
            })
            .collect::<Vec<_>>();
        let starter_candidates = quest_store
            .quests_for_starter(creature_entry)
            .iter()
            .map(|quest| {
                (
                    quest.id,
                    quest.log_title.clone(),
                    quest.allowable_races,
                    quest.allowable_classes,
                    quest.min_level,
                    quest.max_level,
                    quest.is_available_for(
                        self.player_race_like_cpp(),
                        self.player_class_like_cpp(),
                        self.player_level_like_cpp(),
                    ),
                    self.can_take_quest(quest),
                    self.player_quests
                        .get(&quest.id)
                        .map(|status| status.status),
                    self.rewarded_quests.contains(&quest.id),
                )
            })
            .collect::<Vec<_>>();
        info!(
            creature_entry,
            race = self.player_race_like_cpp(),
            class = self.player_class_like_cpp(),
            level = self.player_level_like_cpp(),
            ender_candidates = ?ender_candidates,
            starter_candidates = ?starter_candidates,
            menu_items = ?self.represented_quest_menu_item_log_rows_like_cpp(&menu_items),
            "Prepared creature questgiver fallback menu like C++"
        );
        if menu_items.is_empty() {
            return false;
        }

        self.send_represented_prepared_quest_like_cpp(creature_guid, menu_items);
        true
    }

    pub(crate) fn use_represented_gameobject_questgiver_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        gameobject_entry: u32,
        source: wow_entities::QuestgiverUseSource,
    ) -> bool {
        self.represented_gameobject_use_effects
            .push(RepresentedGameObjectUseEffect::SendGossip {
                gameobject_guid,
                player_guid,
                gossip_id: source.gossip_id,
            });

        let Some(quest_store) = self.quest_store.as_ref().map(Arc::clone) else {
            return true;
        };

        let menu_items =
            self.represented_gameobject_quest_menu_items_like_cpp(&quest_store, gameobject_entry);
        if !menu_items.is_empty() {
            self.send_represented_prepared_quest_like_cpp(gameobject_guid, menu_items);
        }

        true
    }

    pub(crate) fn represented_quest_giver_involved_source_allows_quest_like_cpp(
        &self,
        source_guid: ObjectGuid,
        quest_id: u32,
        quest_store: &wow_data::quest::QuestStore,
    ) -> bool {
        if source_guid.is_any_type_creature() {
            let Some(access) = self.represented_npc_can_interact_with_like_cpp(
                source_guid,
                NPCFlags1::QUEST_GIVER.bits(),
                0,
            ) else {
                debug!(
                    account = self.account_id,
                    ?source_guid,
                    quest_id,
                    "QuestGiverCompleteReward: represented Creature source missing or not interactable"
                );
                return false;
            };

            return quest_store.creature_has_ender_relation_like_cpp(access.entry, quest_id);
        }

        if source_guid.is_game_object() {
            let Some(access) =
                self.represented_gameobject_questgiver_can_interact_with_like_cpp(source_guid)
            else {
                debug!(
                    account = self.account_id,
                    ?source_guid,
                    quest_id,
                    "QuestGiverCompleteReward: represented GameObject source missing or not interactable"
                );
                return false;
            };

            return quest_store.gameobject_has_ender_relation_like_cpp(access.entry, quest_id);
        }

        // Player and Item questgiver branches are not involved-quest sources in this represented slice.
        // Match the C++ early-return shape by failing closed with no packet and no mutation.
        debug!(
            account = self.account_id,
            ?source_guid,
            quest_id,
            "QuestGiverCompleteReward: unsupported represented source type"
        );
        false
    }

    pub(crate) fn represented_quest_giver_accept_source_allows_quest_like_cpp(
        &self,
        source_guid: ObjectGuid,
        quest_id: u32,
        quest_store: &wow_data::quest::QuestStore,
    ) -> bool {
        if source_guid.is_any_type_creature() {
            let Some(access) = self.represented_npc_can_interact_with_like_cpp(
                source_guid,
                NPCFlags1::QUEST_GIVER.bits(),
                0,
            ) else {
                debug!(
                    account = self.account_id,
                    ?source_guid,
                    quest_id,
                    "QuestGiverAcceptQuest: represented Creature source missing or not interactable"
                );
                return false;
            };

            return quest_store.creature_has_starter_relation_like_cpp(access.entry, quest_id);
        }

        if source_guid.is_game_object() {
            let Some(access) =
                self.represented_gameobject_questgiver_can_interact_with_like_cpp(source_guid)
            else {
                debug!(
                    account = self.account_id,
                    ?source_guid,
                    quest_id,
                    "QuestGiverAcceptQuest: represented GameObject source missing or not interactable"
                );
                return false;
            };

            return quest_store.gameobject_has_starter_relation_like_cpp(access.entry, quest_id);
        }

        // Player quest sharing and Item questgiver branches are not represented in this slice.
        // Match the C++ early-return shape by failing closed with no packet and no mutation.
        debug!(
            account = self.account_id,
            ?source_guid,
            quest_id,
            "QuestGiverAcceptQuest: unsupported represented source type"
        );
        false
    }

    pub(crate) fn send_represented_quest_giver_query_quest_like_cpp(
        &mut self,
        source_guid: ObjectGuid,
        quest_id: u32,
    ) -> bool {
        let Some(quest_store) = self.quest_store.as_ref().map(Arc::clone) else {
            debug!(
                account = self.account_id,
                ?source_guid,
                quest_id,
                "QuestGiverQueryQuest: missing quest store"
            );
            return false;
        };
        let Some(quest) = quest_store.get(quest_id).cloned() else {
            warn!(
                account = self.account_id,
                ?source_guid,
                quest_id,
                "QuestGiverQueryQuest: unknown quest"
            );
            return false;
        };

        let menu_item = if source_guid.is_any_type_creature() {
            let Some(access) = self.represented_npc_can_interact_with_like_cpp(
                source_guid,
                NPCFlags1::QUEST_GIVER.bits(),
                0,
            ) else {
                debug!(
                    account = self.account_id,
                    ?source_guid,
                    quest_id,
                    "QuestGiverQueryQuest: represented Creature source missing or not interactable"
                );
                return false;
            };

            self.represented_quest_giver_query_creature_menu_item_like_cpp(
                &quest_store,
                access.entry,
                &quest,
            )
        } else if source_guid.is_game_object() {
            let Some(access) =
                self.represented_gameobject_questgiver_can_interact_with_like_cpp(source_guid)
            else {
                debug!(
                    account = self.account_id,
                    ?source_guid,
                    quest_id,
                    "QuestGiverQueryQuest: represented GameObject source missing or not interactable"
                );
                return false;
            };

            self.represented_quest_giver_query_gameobject_menu_item_like_cpp(
                &quest_store,
                access.entry,
                &quest,
            )
        } else {
            debug!(
                account = self.account_id,
                ?source_guid,
                quest_id,
                "QuestGiverQueryQuest: unsupported represented source type"
            );
            return false;
        };

        let Some(menu_item) = menu_item else {
            debug!(
                account = self.account_id,
                ?source_guid,
                quest_id,
                "QuestGiverQueryQuest: source has no represented starter/involved relation for quest"
            );
            return false;
        };

        self.send_represented_prepared_single_quest_like_cpp(source_guid, &menu_item, false);
        true
    }

    fn represented_quest_giver_query_creature_menu_item_like_cpp(
        &self,
        quest_store: &wow_data::quest::QuestStore,
        creature_entry: u32,
        quest: &wow_data::quest::QuestTemplate,
    ) -> Option<RepresentedPreparedQuestMenuItemLikeCpp> {
        if quest_store.creature_has_ender_relation_like_cpp(creature_entry, quest.id) {
            if self.represented_player_quest_status_is_complete_or_incomplete_like_cpp(quest.id) {
                return Some(RepresentedPreparedQuestMenuItemLikeCpp {
                    quest: quest.clone(),
                    quest_icon: QUEST_MENU_ICON_COMPLETE_LIKE_CPP,
                    has_starter_relation: false,
                    has_involved_relation: true,
                });
            }
            // C++ `HandleQuestgiverQueryQuestOpcode` accepts hasQuest OR
            // hasInvolvedQuest; `PrepareQuestMenu` still checks starters after
            // skipping inactive involved quests on the same source.
        }

        if quest_store.creature_has_starter_relation_like_cpp(creature_entry, quest.id) {
            return self.represented_starter_quest_menu_item_like_cpp(quest);
        }

        None
    }

    fn represented_quest_giver_query_gameobject_menu_item_like_cpp(
        &self,
        quest_store: &wow_data::quest::QuestStore,
        gameobject_entry: u32,
        quest: &wow_data::quest::QuestTemplate,
    ) -> Option<RepresentedPreparedQuestMenuItemLikeCpp> {
        if quest_store.gameobject_has_ender_relation_like_cpp(gameobject_entry, quest.id) {
            if self.represented_player_quest_status_is_complete_or_incomplete_like_cpp(quest.id) {
                return Some(RepresentedPreparedQuestMenuItemLikeCpp {
                    quest: quest.clone(),
                    quest_icon: QUEST_MENU_ICON_COMPLETE_LIKE_CPP,
                    has_starter_relation: false,
                    has_involved_relation: true,
                });
            }
            // C++ `HandleQuestgiverQueryQuestOpcode` accepts hasQuest OR
            // hasInvolvedQuest; `PrepareQuestMenu` still checks starters after
            // skipping inactive involved quests on the same source.
        }

        if quest_store.gameobject_has_starter_relation_like_cpp(gameobject_entry, quest.id) {
            return self.represented_starter_quest_menu_item_like_cpp(quest);
        }

        None
    }

    fn represented_creature_quest_menu_items_like_cpp(
        &self,
        quest_store: &wow_data::quest::QuestStore,
        creature_entry: u32,
    ) -> Vec<RepresentedPreparedQuestMenuItemLikeCpp> {
        let mut menu_items = Vec::new();

        // C++ `Player::PrepareQuestMenu`: involved/ender relations first, icon 4 for
        // represented COMPLETE/INCOMPLETE local quest status.
        for quest in quest_store.quests_for_ender(creature_entry) {
            if self.represented_player_quest_status_is_complete_or_incomplete_like_cpp(quest.id) {
                menu_items.push(RepresentedPreparedQuestMenuItemLikeCpp {
                    quest: quest.clone(),
                    quest_icon: QUEST_MENU_ICON_COMPLETE_LIKE_CPP,
                    has_starter_relation: false,
                    has_involved_relation: true,
                });
            }
        }

        // Starter relations second, preserving C++ quest-icon selection for later
        // `SendPreparedQuest` single-item auto-open.
        for quest in quest_store.quests_for_starter(creature_entry) {
            if let Some(menu_item) = self.represented_starter_quest_menu_item_like_cpp(quest) {
                menu_items.push(menu_item);
            }
        }

        menu_items
    }

    fn represented_gameobject_quest_menu_items_like_cpp(
        &self,
        quest_store: &wow_data::quest::QuestStore,
        gameobject_entry: u32,
    ) -> Vec<RepresentedPreparedQuestMenuItemLikeCpp> {
        let mut menu_items = Vec::new();

        // C++ `Player::PrepareQuestMenu`: GO involved/ender relations first, then
        // starters; do not contaminate GameObject sources with Creature relations.
        for quest in quest_store.quests_for_gameobject_ender(gameobject_entry) {
            if self.represented_player_quest_status_is_complete_or_incomplete_like_cpp(quest.id) {
                menu_items.push(RepresentedPreparedQuestMenuItemLikeCpp {
                    quest: quest.clone(),
                    quest_icon: QUEST_MENU_ICON_COMPLETE_LIKE_CPP,
                    has_starter_relation: false,
                    has_involved_relation: true,
                });
            }
        }

        for quest in quest_store.quests_for_gameobject_starter(gameobject_entry) {
            if let Some(menu_item) = self.represented_starter_quest_menu_item_like_cpp(quest) {
                menu_items.push(menu_item);
            }
        }

        menu_items
    }

    fn represented_starter_quest_menu_item_like_cpp(
        &self,
        quest: &wow_data::quest::QuestTemplate,
    ) -> Option<RepresentedPreparedQuestMenuItemLikeCpp> {
        if !self.can_take_quest(quest) {
            return None;
        }

        let quest_icon = if quest.is_turn_in_like_cpp()
            && (!quest.is_repeatable()
                || quest.is_daily_like_cpp()
                || quest.is_weekly_like_cpp()
                || quest.is_monthly_like_cpp())
        {
            QUEST_MENU_ICON_TURN_IN_LIKE_CPP
        } else if quest.is_turn_in_like_cpp() {
            QUEST_MENU_ICON_COMPLETE_LIKE_CPP
        } else if self.represented_player_quest_status_is_none_like_cpp(quest.id) {
            QUEST_MENU_ICON_AVAILABLE_LIKE_CPP
        } else {
            return None;
        };

        Some(RepresentedPreparedQuestMenuItemLikeCpp {
            quest: quest.clone(),
            quest_icon,
            has_starter_relation: true,
            has_involved_relation: false,
        })
    }

    fn represented_player_quest_status_is_complete_or_incomplete_like_cpp(
        &self,
        quest_id: u32,
    ) -> bool {
        self.player_quests.get(&quest_id).is_some_and(|status| {
            matches!(
                status.status,
                crate::conditions::QUEST_STATUS_COMPLETE_LIKE_CPP
                    | crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP
            )
        })
    }

    fn represented_player_quest_status_is_none_like_cpp(&self, quest_id: u32) -> bool {
        !self.player_quests.contains_key(&quest_id)
    }

    fn send_represented_prepared_quest_like_cpp(
        &mut self,
        source_guid: ObjectGuid,
        menu_items: Vec<RepresentedPreparedQuestMenuItemLikeCpp>,
    ) {
        if let [menu_item] = menu_items.as_slice() {
            info!(
                ?source_guid,
                quest_id = menu_item.quest.id,
                quest_icon = menu_item.quest_icon,
                starter = menu_item.has_starter_relation,
                involved = menu_item.has_involved_relation,
                title = menu_item.quest.log_title.as_str(),
                "Sending represented single prepared quest like C++"
            );
            self.send_represented_prepared_single_quest_like_cpp(source_guid, menu_item, true);
            return;
        }

        info!(
            ?source_guid,
            quests = ?self.represented_quest_menu_item_log_rows_like_cpp(&menu_items),
            "Sending represented QuestGiverQuestList like C++"
        );
        self.send_packet(&QuestGiverQuestList {
            guid: source_guid,
            greeting: String::new(),
            greet_emote_delay: 0,
            greet_emote_type: 0,
            quests: menu_items
                .iter()
                .map(|item| self.quest_list_entry_from_menu_item_like_cpp(item))
                .collect(),
        });
    }

    fn send_represented_prepared_single_quest_like_cpp(
        &mut self,
        source_guid: ObjectGuid,
        menu_item: &RepresentedPreparedQuestMenuItemLikeCpp,
        auto_launched: bool,
    ) {
        let quest = &menu_item.quest;

        if menu_item.quest_icon == QUEST_MENU_ICON_COMPLETE_LIKE_CPP {
            let can_complete = self.can_reward_quest_represented_bounded_like_cpp(quest);
            info!(
                ?source_guid,
                quest_id = quest.id,
                can_complete,
                auto_launched,
                title = quest.log_title.as_str(),
                "Sending represented QuestGiverRequestItems from complete icon like C++"
            );
            self.send_represented_quest_giver_request_items_with_completion_like_cpp(
                source_guid,
                quest,
                can_complete,
                auto_launched,
            );
            return;
        }

        if !menu_item.has_starter_relation && !menu_item.has_involved_relation {
            // C++ would `SendCloseGossip()`. This represented seam has no close-gossip
            // packet helper, and relation-derived menu items should not reach this branch.
            return;
        }

        // C++ may auto-accept here; this represented-partial seam intentionally performs no
        // quest log mutation and only chooses the outbound packet.
        if quest.is_turn_in_like_cpp()
            && quest.is_repeatable()
            && !quest.is_daily_or_weekly_like_cpp()
            && !quest.is_monthly_like_cpp()
        {
            info!(
                ?source_guid,
                quest_id = quest.id,
                auto_launched,
                title = quest.log_title.as_str(),
                "Sending represented QuestGiverRequestItems for repeatable turn-in like C++"
            );
            let can_complete =
                self.can_complete_repeatable_quest_represented_bounded_like_cpp(quest);
            self.send_represented_quest_giver_request_items_with_completion_like_cpp(
                source_guid,
                quest,
                can_complete,
                auto_launched,
            );
        } else if quest.is_turn_in_like_cpp()
            && !quest.is_daily_or_weekly_like_cpp()
            && !quest.is_monthly_like_cpp()
        {
            let can_complete = self.can_reward_quest_represented_bounded_like_cpp(quest);
            info!(
                ?source_guid,
                quest_id = quest.id,
                can_complete,
                auto_launched,
                title = quest.log_title.as_str(),
                "Sending represented QuestGiverRequestItems for turn-in like C++"
            );
            self.send_represented_quest_giver_request_items_with_completion_like_cpp(
                source_guid,
                quest,
                can_complete,
                auto_launched,
            );
        } else {
            info!(
                ?source_guid,
                quest_id = quest.id,
                auto_launched,
                title = quest.log_title.as_str(),
                "Sending represented QuestGiverQuestDetails like C++"
            );
            self.send_represented_quest_giver_quest_details_like_cpp(
                source_guid,
                quest,
                auto_launched,
            );
        }
    }

    fn represented_quest_menu_item_log_rows_like_cpp(
        &self,
        menu_items: &[RepresentedPreparedQuestMenuItemLikeCpp],
    ) -> Vec<(u32, String, u8, bool, bool, u32, u32)> {
        menu_items
            .iter()
            .map(|item| {
                (
                    item.quest.id,
                    item.quest.log_title.clone(),
                    item.quest_icon,
                    item.has_starter_relation,
                    item.has_involved_relation,
                    item.quest.allowable_classes,
                    item.quest.flags,
                )
            })
            .collect()
    }

    pub(crate) fn send_repeatable_turn_in_request_items_like_cpp(
        &mut self,
        sender_guid: ObjectGuid,
        quest: &wow_data::quest::QuestTemplate,
    ) {
        let can_complete = self.can_complete_repeatable_quest_represented_bounded_like_cpp(quest);
        if can_complete && !quest_has_represented_item_objective_like_cpp(quest) {
            self.send_represented_quest_giver_offer_reward_like_cpp(sender_guid, quest, true);
            return;
        }

        self.send_represented_quest_giver_request_items_with_completion_like_cpp(
            sender_guid,
            quest,
            can_complete,
            true,
        );
    }

    pub(crate) fn can_complete_repeatable_quest_represented_bounded_like_cpp(
        &self,
        quest: &wow_data::quest::QuestTemplate,
    ) -> bool {
        // C++ Player::CanCompleteRepeatableQuest is CanTakeQuest(false) && CanRewardQuest(false).
        // The full CanRewardQuest blocker set includes disable checks, quest status, day/week/month/
        // seasonal gates, level/skill/reputation, reward status, item/currency/money checks, etc.
        // This bounded #611 seam must not overclaim completion while those blockers remain open.
        if !self.can_take_quest(quest) {
            return false;
        }

        let inventory_item_counts = self.represented_inventory_item_counts_like_cpp();
        let mut saw_non_bound_item_objective = false;
        for objective in &quest.objectives {
            if objective.obj_type != QUEST_OBJECTIVE_ITEM_LIKE_CPP {
                return false;
            }

            if (objective.flags2 & QUEST_OBJECTIVE_FLAG_2_QUEST_BOUND_ITEM_LIKE_CPP) != 0 {
                continue;
            }

            saw_non_bound_item_objective = true;
            let Ok(item_id) = u32::try_from(objective.object_id) else {
                return false;
            };
            let Ok(required_count) = u32::try_from(objective.amount) else {
                return false;
            };
            if inventory_item_counts.get(&item_id).copied().unwrap_or(0) < required_count {
                return false;
            }
        }

        // Item counts are represented only as partial evidence. Do not return true until the
        // remaining C++ CanRewardQuest blockers are represented in this runtime path.
        let _ = saw_non_bound_item_objective;
        false
    }

    pub(crate) fn can_reward_quest_represented_bounded_like_cpp(
        &self,
        quest: &wow_data::quest::QuestTemplate,
    ) -> bool {
        // C++ `Player::CanRewardQuest(quest, false)` requires the quest to be complete
        // unless it is a DF/turn-in-only quest, then rejects already rewarded
        // non-repeatable quests. This represented seam covers the status/reward gates
        // needed by `SendQuestGiverRequestItems`; inventory-capacity and long-tail
        // reward blockers remain in the reward handler path.
        if self.is_quest_disabled_like_cpp(quest.id) {
            return false;
        }

        if !quest.is_df_quest_like_cpp()
            && !quest.is_turn_in_like_cpp()
            && !self.player_quests.get(&quest.id).is_some_and(|status| {
                status.status == crate::conditions::QUEST_STATUS_COMPLETE_LIKE_CPP
            })
        {
            return false;
        }

        if self.rewarded_quests.contains(&quest.id) && !quest.is_repeatable() {
            return false;
        }

        true
    }

    pub(crate) fn send_represented_quest_giver_request_items_with_completion_like_cpp(
        &mut self,
        source_guid: ObjectGuid,
        quest: &wow_data::quest::QuestTemplate,
        can_complete: bool,
        auto_launched: bool,
    ) {
        let collect = quest
            .objectives
            .iter()
            .filter(|objective| objective.obj_type == QUEST_OBJECTIVE_ITEM_LIKE_CPP)
            .map(|objective| QuestGiverRequestItemsCollect {
                object_id: objective.object_id,
                amount: objective.amount,
                flags: objective.flags,
            })
            .collect::<Vec<_>>();
        let currency = quest
            .objectives
            .iter()
            .filter(|objective| objective.obj_type == QUEST_OBJECTIVE_CURRENCY_LIKE_CPP)
            .map(|objective| QuestGiverRequestItemsCurrency {
                currency_id: objective.object_id,
                amount: objective.amount,
            })
            .collect::<Vec<_>>();
        let money_to_get = quest
            .objectives
            .iter()
            .filter(|objective| objective.obj_type == QUEST_OBJECTIVE_MONEY_LIKE_CPP)
            .map(|objective| objective.amount)
            .sum::<i32>();
        self.send_packet(&QuestGiverRequestItems {
            giver_guid: source_guid,
            giver_creature_id: quest_giver_creature_id_from_source_like_cpp(source_guid),
            quest_id: quest.id,
            comp_emote_delay: 0,
            comp_emote_type: 0,
            quest_flags: [quest.flags, quest.flags_ex, quest.flags_ex2],
            suggested_party_members: quest.suggested_group_num,
            money_to_get,
            collect,
            currency,
            status_flags: if can_complete { 0xFF } else { 0xFD },
            title: quest.log_title.clone(),
            completion_text: quest.area_description.clone(),
            auto_launched,
        });
    }

    pub(crate) fn send_represented_quest_giver_offer_reward_like_cpp(
        &mut self,
        source_guid: ObjectGuid,
        quest: &wow_data::quest::QuestTemplate,
        auto_launched: bool,
    ) {
        self.send_packet(&QuestGiverOfferReward {
            giver_guid: source_guid,
            giver_creature_id: quest_giver_creature_id_from_source_like_cpp(source_guid),
            quest_id: quest.id,
            quest_flags: [quest.flags, quest.flags_ex, quest.flags_ex2],
            suggested_party_members: quest.suggested_group_num,
            rewards: quest_rewards_block_like_cpp(quest),
            title: quest.log_title.clone(),
            reward_text: quest.quest_completion_log.clone(),
            auto_launched,
        });
    }

    pub(crate) fn send_represented_quest_giver_quest_details_like_cpp(
        &mut self,
        source_guid: ObjectGuid,
        quest: &wow_data::quest::QuestTemplate,
        auto_launched: bool,
    ) {
        let objectives: Vec<QuestObjectiveSimple> = quest
            .objectives
            .iter()
            .map(|obj| QuestObjectiveSimple {
                id: obj.id,
                object_id: obj.object_id,
                amount: obj.amount,
                obj_type: obj.obj_type,
            })
            .collect();

        self.send_packet(&QuestGiverQuestDetails {
            giver_guid: source_guid,
            giver_creature_id: quest_giver_creature_id_from_source_like_cpp(source_guid),
            quest_id: quest.id,
            quest_flags: [quest.flags, quest.flags_ex, quest.flags_ex2],
            suggested_party_members: quest.suggested_group_num,
            objectives,
            rewards: quest_rewards_block_like_cpp(quest),
            title: quest.log_title.clone(),
            description: quest.quest_description.clone(),
            log_description: quest.log_description.clone(),
            auto_launched,
        });
    }

    pub(crate) fn represented_creature_gossip_text_like_cpp(
        &self,
        creature_entry: u32,
    ) -> Vec<ClientGossipText> {
        let Some(quest_store) = self.quest_store.as_ref() else {
            return Vec::new();
        };

        let starter_candidates = quest_store
            .quests_for_starter(creature_entry)
            .iter()
            .map(|quest| {
                (
                    quest.id,
                    quest.allowable_races,
                    quest.allowable_classes,
                    quest.min_level,
                    quest.max_level,
                    self.can_take_quest(quest),
                )
            })
            .collect::<Vec<_>>();
        let menu_items =
            self.represented_creature_quest_menu_items_like_cpp(quest_store, creature_entry);
        info!(
            creature_entry,
            race = self.player_race_like_cpp(),
            class = self.player_class_like_cpp(),
            level = self.player_level_like_cpp(),
            starter_candidates = ?starter_candidates,
            quests = ?menu_items.iter().map(|item| item.quest.id).collect::<Vec<_>>(),
            "Prepared creature gossip quest text like C++"
        );

        menu_items
            .iter()
            .map(|item| self.gossip_text_from_menu_item_like_cpp(item))
            .collect()
    }

    fn quest_list_entry_from_menu_item_like_cpp(
        &self,
        menu_item: &RepresentedPreparedQuestMenuItemLikeCpp,
    ) -> QuestListEntry {
        let quest = &menu_item.quest;
        QuestListEntry {
            quest_id: quest.id,
            // C++ `PlayerMenu::SendQuestGiverQuestListMessage` writes
            // `QuestMenuItem::QuestIcon`, not `Quest::GetQuestType`.
            quest_type: menu_item.quest_icon,
            quest_level: 0,
            quest_max_scaling_level: 0,
            quest_flags: quest.flags,
            quest_flags_ex: quest.flags_ex,
            repeatable: quest.is_turn_in_like_cpp()
                && quest.is_repeatable()
                && !quest.is_daily_or_weekly_like_cpp()
                && !quest.is_monthly_like_cpp(),
            important: self.represented_quest_is_important_like_cpp(quest),
            title: quest.log_title.clone(),
        }
    }

    fn gossip_text_from_menu_item_like_cpp(
        &self,
        menu_item: &RepresentedPreparedQuestMenuItemLikeCpp,
    ) -> ClientGossipText {
        let quest = &menu_item.quest;
        ClientGossipText {
            quest_id: quest.id as i32,
            content_tuning_id: 0,
            quest_type: i32::from(menu_item.quest_icon),
            quest_level: quest.quest_level,
            quest_max_scaling_level: quest.quest_max_scaling_level,
            quest_flags: quest.flags,
            quest_flags_ex: quest.flags_ex,
            repeatable: quest.is_turn_in_like_cpp()
                && quest.is_repeatable()
                && !quest.is_daily_or_weekly_like_cpp()
                && !quest.is_monthly_like_cpp(),
            important: self.represented_quest_is_important_like_cpp(quest),
            quest_title: quest.log_title.clone(),
        }
    }

    pub(crate) fn use_represented_gameobject_spellcaster_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        gameobject_entry: u32,
        source: wow_entities::SpellcasterUseSource,
    ) -> bool {
        if source.party_only {
            let owner_guid =
                self.represented_or_canonical_gameobject_owner_guid_like_cpp(gameobject_guid);
            if !owner_guid.is_some_and(|owner_guid| {
                self.represented_player_is_same_raid_with_like_cpp(player_guid, owner_guid)
            }) {
                self.represented_gameobject_use_effects.push(
                    RepresentedGameObjectUseEffect::SpellcasterPartyOnlyRejected {
                        gameobject_guid,
                        player_guid,
                    },
                );
                return false;
            }
        }

        self.remove_represented_mounted_auras_by_type_like_cpp();
        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::RemoveMountedAuras {
                gameobject_guid,
                player_guid,
            },
        );

        let use_count = {
            let state = self
                .represented_gameobject_use_states
                .entry(gameobject_guid)
                .or_default();
            state.go_type = Some(wow_entities::GAMEOBJECT_TYPE_SPELLCASTER as u8);
            if source.charges != 0 {
                state.max_charges = Some(source.charges);
            }
            state.use_count = state.use_count.saturating_add(1);
            state.use_count
        };
        self.represented_gameobject_use_effects.push(
            RepresentedGameObjectUseEffect::GameObjectUseCountIncremented {
                gameobject_guid,
                use_count,
            },
        );

        self.apply_represented_gameobject_post_use_spell_like_cpp(
            gameobject_guid,
            player_guid,
            gameobject_entry,
            wow_entities::GAMEOBJECT_TYPE_SPELLCASTER,
            source.spell_id,
            false,
            RepresentedGameObjectSpellCaster::User,
            player_guid,
        );

        true
    }

    pub(crate) fn use_represented_gameobject_spell_focus_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        linked_trap_entry: u32,
    ) -> bool {
        if linked_trap_entry != 0 {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::TriggerLinkedTrap {
                    gameobject_guid,
                    player_guid,
                    trap_entry: linked_trap_entry,
                },
            );
        }

        true
    }

    pub(crate) fn use_represented_gameobject_camera_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        source: wow_entities::CameraUseSource,
    ) -> bool {
        if source.cinematic_id != 0 {
            self.send_represented_cinematic_start_like_cpp(source.cinematic_id);
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::TriggerCinematic {
                    gameobject_guid,
                    player_guid,
                    cinematic_id: source.cinematic_id,
                },
            );
        }

        if source.event_id != 0 {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::TriggerGameEvent {
                    gameobject_guid,
                    player_guid,
                    event_id: source.event_id,
                },
            );
        }

        true
    }

    pub(crate) async fn use_represented_gameobject_goober_preamble_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        gameobject_entry: u32,
        gameobject_position: Position,
        player_guid: ObjectGuid,
        source: wow_entities::GooberUseSource,
    ) -> bool {
        if source.page_id != 0 {
            self.send_packet(&wow_packet::packets::misc::PageText { gameobject_guid });
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::ShowPageText {
                    gameobject_guid,
                    player_guid,
                    page_id: source.page_id,
                },
            );
        } else if source.gossip_id != 0 {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::SendGossip {
                    gameobject_guid,
                    player_guid,
                    gossip_id: source.gossip_id,
                },
            );
        }

        if source.event_id != 0 {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::TriggerGameEvent {
                    gameobject_guid,
                    player_guid,
                    event_id: source.event_id,
                },
            );
        }

        if source.quest_id != 0
            && self
                .quest_store
                .as_ref()
                .is_some_and(|store| store.get(source.quest_id).is_some())
            && self
                .player_quests
                .get(&source.quest_id)
                .map_or(true, |status| {
                    status.status != crate::conditions::QUEST_STATUS_INCOMPLETE_LIKE_CPP
                })
        {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::GooberQuestGateRejected {
                    gameobject_guid,
                    player_guid,
                    quest_id: source.quest_id,
                },
            );
            return false;
        }

        let mut credit_guids = Vec::new();
        if let (Some(group_guid), Some(group_registry)) = (self.group_guid, &self.group_registry) {
            if let Some(group) = group_registry.get(&group_guid) {
                if group.members.contains(&player_guid) {
                    credit_guids.extend(group.members.iter().copied());
                }
            }
        }
        if credit_guids.is_empty() {
            credit_guids.push(player_guid);
        }

        for credit_guid in credit_guids {
            if self.represented_player_at_group_reward_distance_like_cpp(
                credit_guid,
                self.player_map_id_like_cpp(),
                gameobject_position,
            ) {
                self.represented_gameobject_use_effects.push(
                    RepresentedGameObjectUseEffect::KillCreditGo {
                        gameobject_guid,
                        player_guid: credit_guid,
                        entry: gameobject_entry,
                    },
                );
                if Some(credit_guid) == self.player_guid() {
                    self.kill_credit_gameobject_like_cpp(gameobject_entry, gameobject_guid)
                        .await;
                }
            }
        }

        if source.linked_trap_entry != 0 {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::TriggerLinkedTrap {
                    gameobject_guid,
                    player_guid,
                    trap_entry: source.linked_trap_entry,
                },
            );
        }

        true
    }

    pub(crate) fn use_represented_gameobject_goober_state_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        player_guid: ObjectGuid,
        gameobject_entry: u32,
        source: wow_entities::GooberUseSource,
    ) -> bool {
        if source.allow_multi_interact {
            if source.consumable {
                let default_map_id = self.player_map_id_like_cpp();
                let (despawn_secs, map_id) = {
                    let state = self
                        .represented_gameobject_use_states
                        .entry(gameobject_guid)
                        .or_default();
                    let despawn_secs = state
                        .despawn_delay_secs
                        .unwrap_or(wow_entities::DEFAULT_GAMEOBJECT_RESPAWN_DELAY_SECS);
                    state.per_player_despawn_secs = Some(despawn_secs);
                    state.per_player_despawn_until =
                        Some(Instant::now() + Duration::from_secs(u64::from(despawn_secs)));
                    state.per_player_state_player_guid = Some(player_guid);
                    (despawn_secs, state.map_id.unwrap_or(default_map_id))
                };
                self.represented_gameobject_use_effects.push(
                    RepresentedGameObjectUseEffect::GooberDespawnForPlayer {
                        gameobject_guid,
                        player_guid,
                        despawn_secs,
                    },
                );
                if self.player_guid() == Some(player_guid)
                    && self.client_visible_guids_like_cpp.remove(&gameobject_guid)
                {
                    self.send_represented_gameobject_out_of_range_for_player_like_cpp(
                        gameobject_guid,
                        map_id,
                    );
                }
            } else {
                let state = self
                    .represented_gameobject_use_states
                    .entry(gameobject_guid)
                    .or_default();
                let respawn_secs = state
                    .despawn_delay_secs
                    .unwrap_or(wow_entities::DEFAULT_GAMEOBJECT_RESPAWN_DELAY_SECS);
                state.per_player_state_player_guid = Some(player_guid);
                state.per_player_go_state = Some(wow_entities::GoState::Active);
                state.per_player_go_state_until =
                    Some(Instant::now() + Duration::from_secs(u64::from(respawn_secs)));
                self.represented_gameobject_use_effects.push(
                    RepresentedGameObjectUseEffect::GooberSetGoStateForPlayer {
                        gameobject_guid,
                        player_guid,
                        go_state: wow_entities::GoState::Active,
                    },
                );
                if self.player_guid() == Some(player_guid) {
                    self.send_packet(&wow_packet::packets::misc::GameObjectSetStateLocal {
                        object_guid: gameobject_guid,
                        state: wow_entities::GoState::Active as u8,
                    });
                }
            }
        } else {
            let (go_state, custom_anim_progress) = {
                let state = self
                    .represented_gameobject_use_states
                    .entry(gameobject_guid)
                    .or_default();
                state.gameobject_flags |= wow_entities::GO_FLAG_IN_USE;
                state.loot_state = Some(wow_entities::LootState::Activated);
                state.loot_state_unit_guid = player_guid;
                state.goober_use_source = Some(source);
                state.despawn_at_action = source.consumable;
                let custom_anim_progress = if source.custom_anim != 0 {
                    Some(u32::from(state.go_anim_progress))
                } else {
                    state.go_state = Some(wow_entities::GoState::Active);
                    None
                };
                state.cooldown_until =
                    Some(Instant::now() + Duration::from_millis(u64::from(source.auto_close_ms)));
                (
                    custom_anim_progress
                        .is_none()
                        .then_some(wow_entities::GoState::Active),
                    custom_anim_progress,
                )
            };
            if let Some(custom_anim) = custom_anim_progress {
                use wow_packet::ServerPacket;

                let packet = wow_packet::packets::misc::GameObjectCustomAnim {
                    object_guid: gameobject_guid,
                    custom_anim,
                    play_as_despawn: false,
                };
                self.send_packet(&packet);
                let _ = self.queue_visible_gameobject_packet_for_same_map_like_cpp(
                    gameobject_guid,
                    packet.to_bytes(),
                );
            }
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::GooberUsed {
                    gameobject_guid,
                    user_guid: player_guid,
                    custom_anim: source.custom_anim,
                    auto_close_ms: source.auto_close_ms,
                    go_state,
                },
            );
            let _ =
                self.queue_goober_gameobject_state_refresh_for_same_map_like_cpp(gameobject_guid);
        }

        if source.spell_id != 0 {
            self.apply_represented_gameobject_post_use_spell_like_cpp(
                gameobject_guid,
                player_guid,
                gameobject_entry,
                wow_entities::GAMEOBJECT_TYPE_GOOBER,
                source.spell_id,
                false,
                if source.player_cast {
                    RepresentedGameObjectSpellCaster::User
                } else {
                    RepresentedGameObjectSpellCaster::GameObject
                },
                if source.player_cast {
                    player_guid
                } else {
                    gameobject_guid
                },
            );
        }

        true
    }

    #[allow(dead_code)]
    pub(crate) fn apply_represented_gameobject_goober_just_deactivated_like_cpp(
        &mut self,
        gameobject_guid: ObjectGuid,
        source: wow_entities::GooberUseSource,
    ) -> bool {
        let linked_trap_guid = self
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .and_then(|state| state.linked_trap_guid);
        if source.linked_trap_entry != 0 {
            if let Some(trap_guid) = linked_trap_guid {
                self.despawn_represented_linked_trap_by_guid_like_cpp(trap_guid);
            }
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::GooberLinkedTrapDespawn {
                    gameobject_guid,
                    trap_entry: source.linked_trap_entry,
                },
            );
        }

        let mut unique_users = Vec::new();
        let mut send_despawn_at_action = false;
        {
            let state = self
                .represented_gameobject_use_states
                .entry(gameobject_guid)
                .or_default();
            if source.spell_id != 0 {
                unique_users = std::mem::take(&mut state.unique_users);
            } else {
                state.unique_users.clear();
            }

            state.loot_state_unit_guid = wow_core::ObjectGuid::EMPTY;
            state.gameobject_flags &= !wow_entities::GO_FLAG_IN_USE;
            state.cooldown_until = None;
            state.goober_use_source = None;
            if source.lock_id != 0 || source.auto_close_ms != 0 {
                state.go_state = Some(wow_entities::GoState::Ready);
            }
            state.loot_state = if source.consumable {
                Some(wow_entities::LootState::NotReady)
            } else {
                Some(wow_entities::LootState::Ready)
            };
            let has_represented_owner_or_summon = state.owner_guid.is_some();
            if source.consumable && !has_represented_owner_or_summon {
                send_despawn_at_action = true;
            }
        }

        if send_despawn_at_action {
            self.send_represented_gameobject_despawn_to_visible_set_like_cpp(gameobject_guid);
        }

        if source.spell_id != 0 {
            for player_guid in unique_users {
                self.represented_gameobject_use_effects.push(
                    RepresentedGameObjectUseEffect::GooberUniqueUserSpell {
                        gameobject_guid,
                        player_guid,
                        spell_id: source.spell_id,
                    },
                );
            }
        }

        if let Some(state) = self.represented_gameobject_use_states.get(&gameobject_guid) {
            self.represented_gameobject_use_effects.push(
                RepresentedGameObjectUseEffect::GooberCleared {
                    gameobject_guid,
                    loot_state: state
                        .loot_state
                        .unwrap_or(wow_entities::LootState::NotReady),
                    go_state: state.go_state,
                },
            );
        }

        true
    }

