    /// C++ `Spell::CheckCast` gates for battle-pet unit-target effects.
    fn check_represented_battle_pet_spell_like_cpp(
        &self,
        spell_info: &wow_data::SpellInfo,
        metadata: SpellCastMetadata,
    ) -> Option<SpellCastResult> {
        for effect in spell_info.effects() {
            let is_battle_pet_effect = effect.effect
                == wow_data::spell::spell_effect_types::SPELL_EFFECT_CHANGE_BATTLEPET_QUALITY
                || effect.effect
                    == wow_data::spell::spell_effect_types::SPELL_EFFECT_GRANT_BATTLEPET_LEVEL
                || effect.effect
                    == wow_data::spell::spell_effect_types::SPELL_EFFECT_GRANT_BATTLEPET_EXPERIENCE;
            if !is_battle_pet_effect {
                continue;
            }

            let Some(companion_guid) = metadata.unit_target_battle_pet_companion_guid else {
                return Some(SpellCastResult::BadTargets);
            };

            if !self.has_represented_battle_pet_journal_lock_like_cpp() {
                return Some(SpellCastResult::CantDoThatRightNow);
            }

            let summoned_guid = self.represented_summoned_battle_pet_guid_like_cpp();
            if summoned_guid.is_none() || companion_guid.is_empty() {
                return Some(SpellCastResult::NoPet);
            }

            if summoned_guid != Some(companion_guid) {
                return Some(SpellCastResult::BadTargets);
            }

            let Some(pet) = self.represented_battle_pets_like_cpp.get(&companion_guid) else {
                continue;
            };

            if let Some(species) = self
                .battle_pet_species_store
                .as_ref()
                .and_then(|store| store.get(pet.species))
            {
                let battle_pet_type = effect.effect_misc_value_1 as u32;
                if battle_pet_type != 0 {
                    let type_mask = 1u32
                        .checked_shl(u32::from(species.pet_type_enum))
                        .unwrap_or(0);
                    if battle_pet_type & type_mask == 0 {
                        return Some(SpellCastResult::WrongBattlePetType);
                    }
                }

                if (effect.effect
                    == wow_data::spell::spell_effect_types::SPELL_EFFECT_GRANT_BATTLEPET_LEVEL
                    || effect.effect
                        == wow_data::spell::spell_effect_types::SPELL_EFFECT_GRANT_BATTLEPET_EXPERIENCE)
                    && pet.level >= MAX_BATTLE_PET_LEVEL_LIKE_CPP
                {
                    return Some(SpellCastResult::GrantPetLevelFail);
                }

                if species.has_flag_like_cpp(wow_data::BATTLE_PET_SPECIES_FLAG_CANT_BATTLE_LIKE_CPP)
                {
                    return Some(SpellCastResult::BadTargets);
                }
            }
        }

        None
    }

    /// C++ `SpellInfo::CheckLocation` aura limitation plus
    /// `Spell::CheckCast` per-effect water gate for represented mount spells.
    fn check_represented_mount_spell_like_cpp(
        &self,
        spell_info: &wow_data::SpellInfo,
    ) -> Option<RepresentedMountSpellCheckOutcomeLikeCpp> {
        for effect in spell_info.effects() {
            if effect.is_mod_shapeshift_aura_like_cpp() {
                if let Some(form) = self.spell_shapeshift_form_store.as_ref().and_then(|store| {
                    u32::try_from(effect.effect_misc_value_1)
                        .ok()
                        .and_then(|form_id| store.get(form_id))
                }) {
                    let (is_submerged, is_in_water) =
                        self.represented_player_mount_liquid_state_like_cpp();
                    if form.mount_type_id != 0
                        && let Err(reject_reason) = self
                            .represented_mount_capability_selection_for_type_like_cpp(
                                form.mount_type_id,
                                u32::from(self.player_skill_value_like_cpp(SKILL_RIDING_LIKE_CPP)),
                                None,
                                is_submerged,
                                is_in_water,
                            )
                    {
                        info!(
                            account = self.account_id,
                            spell_id = spell_info.spell_id,
                            form_id = effect.effect_misc_value_1,
                            mount_type_id = form.mount_type_id,
                            riding_skill = self.player_skill_value_like_cpp(SKILL_RIDING_LIKE_CPP),
                            map_id = self.player_map_id_like_cpp(),
                            ?reject_reason,
                            "Rejecting represented shapeshift mount form cast: no mount capability"
                        );
                        return Some(RepresentedMountSpellCheckOutcomeLikeCpp::CastFailed(
                            SpellCastResult::NotHere,
                        ));
                    }
                }
            }

            if !effect.is_mounted_aura_like_cpp() {
                continue;
            }

            let (_, is_in_water) = self.represented_player_mount_liquid_state_like_cpp();
            if is_in_water
                && spell_info.has_aura_like_cpp(
                    wow_data::spell::aura_types::SPELL_AURA_MOD_INCREASE_MOUNTED_FLIGHT_SPEED,
                )
            {
                info!(
                    account = self.account_id,
                    spell_id = spell_info.spell_id,
                    "Rejecting represented flying mount cast while in water"
                );
                return Some(RepresentedMountSpellCheckOutcomeLikeCpp::CastFailed(
                    SpellCastResult::OnlyAbovewater,
                ));
            }

            if let Some(disallowed_source_id) = self.represented_disallowed_mount_form_like_cpp() {
                self.send_packet(&MountResult {
                    result: MOUNT_RESULT_SHAPESHIFTED_LIKE_CPP,
                });
                info!(
                    account = self.account_id,
                    spell_id = spell_info.spell_id,
                    disallowed_source_id,
                    "Rejecting represented mount cast: player is in a disallowed shapeshift form"
                );
                return Some(RepresentedMountSpellCheckOutcomeLikeCpp::DontReport);
            }

            let mut mount_type_id = u16::try_from(effect.effect_misc_value_2).unwrap_or_default();
            if let Some(mount_entry) = self.mount_store.as_ref().and_then(|store| {
                u32::try_from(spell_info.spell_id)
                    .ok()
                    .and_then(|spell_id| store.get_by_source_spell_id_like_cpp(spell_id))
            }) {
                mount_type_id = mount_entry.mount_type_id;
            }

            if mount_type_id != 0 {
                let (is_submerged, is_in_water) =
                    self.represented_player_mount_liquid_state_like_cpp();
                if let Err(reject_reason) = self
                    .represented_mount_capability_selection_for_type_like_cpp(
                        mount_type_id,
                        u32::from(self.player_skill_value_like_cpp(SKILL_RIDING_LIKE_CPP)),
                        None,
                        is_submerged,
                        is_in_water,
                    )
                {
                    info!(
                        account = self.account_id,
                        spell_id = spell_info.spell_id,
                        mount_type_id,
                        riding_skill = self.player_skill_value_like_cpp(SKILL_RIDING_LIKE_CPP),
                        map_id = self.player_map_id_like_cpp(),
                        area_id = self.player_zone_area_like_cpp().1,
                        is_submerged,
                        is_in_water,
                        ?reject_reason,
                        "Rejecting represented mount cast: no mount capability"
                    );
                    return Some(RepresentedMountSpellCheckOutcomeLikeCpp::CastFailed(
                        SpellCastResult::NotHere,
                    ));
                }
                info!(
                    account = self.account_id,
                    spell_id = spell_info.spell_id,
                    mount_type_id,
                    riding_skill = self.player_skill_value_like_cpp(SKILL_RIDING_LIKE_CPP),
                    map_id = self.player_map_id_like_cpp(),
                    area_id = self.player_zone_area_like_cpp().1,
                    is_submerged,
                    is_in_water,
                    "Represented mount cast passed C++ mount capability check"
                );
            }
        }

        None
    }

    fn represented_disallowed_mount_form_like_cpp(&self) -> Option<u32> {
        if self.represented_transform_spell_allows_mount_like_cpp() {
            return None;
        }

        if let (Some(spell_store), Some(shapeshift_form_store)) = (
            self.spell_store(),
            self.spell_shapeshift_form_store.as_ref(),
        ) {
            for aura in self.visible_auras.values() {
                let Some(spell_info) = spell_store.get(aura.spell_id) else {
                    continue;
                };

                for effect in spell_info
                    .effects()
                    .iter()
                    .filter(|effect| effect.is_mod_shapeshift_aura_like_cpp())
                {
                    let Ok(form_id) = u32::try_from(effect.effect_misc_value_1) else {
                        continue;
                    };
                    let Some(form) = shapeshift_form_store.get(form_id) else {
                        return Some(form_id);
                    };
                    if form.flags & SPELL_SHAPESHIFT_FORM_FLAG_STANCE_LIKE_CPP == 0 {
                        return Some(form_id);
                    }
                }
            }
        }

        let (display_id, native_display_id) = self.canonical_player_display_ids_like_cpp()?;
        if display_id == 0 || display_id == native_display_id {
            return None;
        }

        let Some(display_store) = self.creature_display_info_store.as_ref() else {
            return None;
        };
        let Some(display_extra_store) = self.creature_display_info_extra_store.as_ref() else {
            return None;
        };
        let Some(display) = display_store.get(display_id) else {
            return Some(display_id);
        };
        let Ok(display_extra_id) = u32::try_from(display.extended_display_info_id) else {
            return Some(display_id);
        };
        let Some(display_extra) = display_extra_store.get(display_extra_id) else {
            return Some(display_id);
        };

        if let (Some(model_store), Some(chr_races_store)) = (
            self.creature_model_data_store.as_ref(),
            self.chr_races_store.as_ref(),
        ) {
            let model_cannot_mount =
                model_store
                    .get(u32::from(display.model_id))
                    .is_some_and(|model| {
                        model.flags
                            & CREATURE_MODEL_DATA_FLAG_CAN_MOUNT_WHILE_TRANSFORMED_AS_THIS_LIKE_CPP
                            == 0
                    });
            let race_cannot_mount = u32::try_from(display_extra.display_race_id)
                .ok()
                .and_then(|race_id| chr_races_store.get(race_id))
                .is_some_and(|race| race.flags & CHR_RACES_FLAG_CAN_MOUNT_LIKE_CPP == 0);
            if model_cannot_mount && race_cannot_mount {
                return Some(display_id);
            }
        }

        None
    }

    fn represented_transform_spell_allows_mount_like_cpp(&self) -> bool {
        let Some(spell_store) = self.spell_store() else {
            return false;
        };

        self.visible_auras.values().any(|aura| {
            let Some(spell_info) = spell_store.get(aura.spell_id) else {
                return false;
            };
            let is_transform_spell = spell_info.effects().iter().any(|effect| {
                effect.effect == wow_data::spell::spell_effect_types::SPELL_EFFECT_APPLY_AURA
                    && effect.effect_aura == wow_data::spell::aura_types::SPELL_AURA_TRANSFORM
            });
            is_transform_spell
                && spell_store.has_attribute0_like_cpp(
                    aura.spell_id,
                    wow_data::spell::attributes::SPELL_ATTR0_ALLOW_WHILE_MOUNTED,
                )
        })
    }

    async fn apply_effect_teleport_units_like_cpp(
        &mut self,
        effect: &wow_data::SpellEffectInfo,
        target_guid: ObjectGuid,
        target_data: &SpellTargetData,
    ) {
        if effect.effect != wow_data::spell::spell_effect_types::SPELL_EFFECT_TELEPORT_UNITS {
            return;
        }

        let Some(player_guid) = self.player_guid() else {
            return;
        };
        if target_guid != player_guid {
            // C++ also supports same-map creature NearTeleportTo here. Rust's
            // represented spell path only owns the player target today; do not
            // fabricate creature movement until Unit target selection is ported.
            return;
        }

        let Some(destination) = target_data.dst_location.as_ref().map(|dst| dst.position) else {
            debug!(
                account = self.account_id,
                effect_index = effect.effect_index,
                "Spell::EffectTeleportUnits represented no-op: missing destination"
            );
            return;
        };

        let target_map = target_data
            .map_id
            .and_then(|map_id| u32::try_from(map_id).ok())
            .unwrap_or_else(|| u32::from(self.player_map_id_like_cpp()));
        let mut destination = destination;
        if destination.orientation == 0.0 {
            if let Some(player_position) = self.player_position_like_cpp() {
                destination.orientation = player_position.orientation;
            }
        }

        self.teleport_to(target_map, destination).await;
    }

    fn apply_effect_bind_like_cpp(
        &mut self,
        effect: &wow_data::SpellEffectInfo,
        caster_guid: ObjectGuid,
        target_guid: ObjectGuid,
        target_data: &SpellTargetData,
    ) {
        if effect.effect != wow_data::spell::spell_effect_types::SPELL_EFFECT_BIND {
            return;
        }

        let Some(player_guid) = self.player_guid() else {
            return;
        };
        if target_guid != player_guid {
            return;
        }

        let (_, current_area_id) = self.player_zone_area_like_cpp();
        let area_id = if effect.effect_misc_value_1 != 0 {
            u32::try_from(effect.effect_misc_value_1).unwrap_or(current_area_id)
        } else {
            current_area_id
        };

        let Some(current_position) = self.player_position_like_cpp() else {
            return;
        };
        let position = target_data
            .dst_location
            .as_ref()
            .map(|dst| dst.position)
            .unwrap_or(current_position);
        let map_id = target_data
            .map_id
            .and_then(|map_id| u32::try_from(map_id).ok())
            .unwrap_or_else(|| u32::from(self.player_map_id_like_cpp()));

        self.represented_homebind_like_cpp = Some(RepresentedHomebindLikeCpp {
            map_id,
            area_id,
            position,
        });

        self.send_packet(&wow_packet::packets::misc::BindPointUpdate {
            x: position.x,
            y: position.y,
            z: position.z,
            map_id: i32::try_from(map_id).unwrap_or(i32::MAX),
            area_id: i32::try_from(area_id).unwrap_or(i32::MAX),
        });
        self.send_packet(&wow_packet::packets::misc::PlayerBound {
            binder_id: caster_guid,
            area_id,
        });
    }

    pub(crate) fn represented_homebind_like_cpp(&self) -> Option<RepresentedHomebindLikeCpp> {
        self.represented_homebind_like_cpp
    }

    #[cfg(test)]
    pub(crate) fn set_represented_homebind_like_cpp(
        &mut self,
        homebind: RepresentedHomebindLikeCpp,
    ) {
        self.represented_homebind_like_cpp = Some(homebind);
    }

    fn apply_effect_environmental_damage_like_cpp(
        &mut self,
        effect: &wow_data::SpellEffectInfo,
        target_guid: ObjectGuid,
    ) {
        if effect.effect != wow_data::spell::spell_effect_types::SPELL_EFFECT_ENVIRONMENTAL_DAMAGE {
            return;
        }

        let Some(player_guid) = self.player_guid() else {
            return;
        };
        if target_guid != player_guid || !self.player_alive_like_cpp {
            return;
        }
        if self.player_environmental_damage_immune_like_cpp {
            return;
        }

        let damage = u32::try_from(effect.effect_base_points.max(0)).unwrap_or(0);
        let original_health = self.player_health_like_cpp;
        let final_damage = damage.min(original_health);
        self.player_health_like_cpp = self.player_health_like_cpp.saturating_sub(final_damage);
        if self.player_health_like_cpp == 0 {
            self.apply_represented_player_environmental_death_like_cpp();
        } else {
            let _ = self.sync_canonical_player_health_like_cpp(
                self.player_health_like_cpp,
                self.player_max_health_like_cpp,
            );
        }
        if self.player_health_like_cpp != original_health {
            self.send_player_health_update_like_cpp(
                player_guid,
                u64::from(self.player_health_like_cpp),
            );
        }
        self.send_environmental_damage_log_like_cpp(
            player_guid,
            DAMAGE_FIRE_LIKE_CPP,
            damage,
            0,
            0,
        );
    }

    fn represented_focus_destination_target_data_like_cpp(
        &self,
        spell_id: i32,
        effect: &wow_data::SpellEffectInfo,
        target_data: &SpellTargetData,
        focus_object: Option<RepresentedSpellFocusObjectLikeCpp>,
    ) -> Option<SpellTargetData> {
        let focus_object = focus_object?;
        if target_data.dst_location.is_some()
            || !effect.has_focus_destination_implicit_target_like_cpp()
        {
            return None;
        }

        if self.has_implicit_target_conditions_like_cpp(spell_id, effect.effect_index) {
            return None;
        }

        let focus_position = self.apply_spell_destination_facing_override_like_cpp(
            spell_id,
            effect,
            focus_object.position,
        );

        let mut target_data = target_data.clone();
        target_data.dst_location = Some(wow_packet::packets::spell::TargetLocation {
            transport: ObjectGuid::EMPTY,
            position: focus_position,
        });
        Some(target_data)
    }

    fn apply_spell_destination_facing_override_like_cpp(
        &self,
        spell_id: i32,
        effect: &wow_data::SpellEffectInfo,
        mut position: Position,
    ) -> Position {
        if self
            .spell_misc_store
            .as_deref()
            .and_then(|store| store.get_by_spell_id(u32::try_from(spell_id).ok()?))
            .is_some_and(|misc| {
                (misc.attributes[4] as u32
                    & wow_data::spell::attributes::SPELL_ATTR4_USE_FACING_FROM_SPELL)
                    != 0
            })
        {
            position.orientation = effect.position_facing;
        }
        position
    }

    fn represented_object_target_position_like_cpp(
        &self,
        target_data: &SpellTargetData,
    ) -> Option<Position> {
        let target_guid = target_data.unit;
        if target_guid.is_empty() {
            return None;
        }
        let player_map_key = self.current_canonical_player_map_key_like_cpp()?;
        let manager = self.canonical_map_manager.as_ref()?;
        let manager = manager.lock().ok()?;
        let map = manager.find_map(player_map_key.map_id, player_map_key.instance_id)?;
        if let Some(player) = map.map().get_typed_player(target_guid) {
            return Some(player.unit().world().position());
        }
        if let Some(creature) = map.map().get_typed_creature(target_guid) {
            return Some(creature.unit().world().position());
        }
        if let Some(gameobject) = map.map().get_typed_game_object(target_guid) {
            return Some(gameobject.world().position());
        }
        map.map()
            .get_typed_dynamic_object(target_guid)
            .map(|dynamic_object| dynamic_object.world().position())
    }

    fn represented_db_caster_destination_target_data_like_cpp(
        &self,
        spell_info: &wow_data::SpellInfo,
        effect: &wow_data::SpellEffectInfo,
        target_data: &SpellTargetData,
    ) -> Option<SpellTargetData> {
        if target_data.dst_location.is_some()
            || !matches!(
                effect.implicit_target_1,
                wow_data::spell::implicit_targets::TARGET_DEST_DB
            ) && !matches!(
                effect.implicit_target_2,
                wow_data::spell::implicit_targets::TARGET_DEST_DB
            )
        {
            return None;
        }

        let spell_id_u32 = u32::try_from(spell_info.spell_id).ok()?;
        let target_position = self
            .spell_target_position_store
            .as_deref()
            .and_then(|store| store.get(spell_id_u32, effect.effect_index));
        let cross_map_allowed = spell_info.effects().iter().any(|candidate| {
            matches!(
                candidate.effect,
                wow_data::spell::spell_effect_types::SPELL_EFFECT_TELEPORT_UNITS
                    | wow_data::spell::spell_effect_types::SPELL_EFFECT_BIND
            )
        });
        let (position, map_id) = if let Some(target_position) = target_position {
            if cross_map_allowed {
                (
                    target_position.position,
                    Some(i32::from(target_position.target_map_id)),
                )
            } else if target_position.target_map_id == self.player_map_id_like_cpp() {
                (target_position.position, None)
            } else {
                (self.player_position_like_cpp()?, None)
            }
        } else if let Some(target_position) =
            self.represented_object_target_position_like_cpp(target_data)
        {
            (target_position, None)
        } else {
            (self.player_position_like_cpp()?, None)
        };
        let position = self.apply_spell_destination_facing_override_like_cpp(
            spell_info.spell_id,
            effect,
            position,
        );

        let mut target_data = target_data.clone();
        target_data.dst_location = Some(wow_packet::packets::spell::TargetLocation {
            transport: ObjectGuid::EMPTY,
            position,
        });
        target_data.map_id = map_id;
        Some(target_data)
    }

    fn represented_nearby_entry_destination_target_data_like_cpp(
        &mut self,
        spell_id: i32,
        effect: &wow_data::SpellEffectInfo,
        target_data: &SpellTargetData,
    ) -> Option<SpellTargetData> {
        if target_data.dst_location.is_some()
            || !effect.has_focus_destination_implicit_target_like_cpp()
        {
            return None;
        }
        let is_or_db = matches!(
            effect.implicit_target_1,
            wow_data::spell::implicit_targets::TARGET_DEST_NEARBY_ENTRY_OR_DB
        ) || matches!(
            effect.implicit_target_2,
            wow_data::spell::implicit_targets::TARGET_DEST_NEARBY_ENTRY_OR_DB
        );

        let spell_id_u32 = u32::try_from(spell_id).ok()?;
        let implicit_conditions =
            self.implicit_target_conditions_like_cpp(spell_id, effect.effect_index);
        let has_implicit_conditions = implicit_conditions
            .as_ref()
            .is_some_and(|conditions| !conditions.is_empty());
        let target_position = if is_or_db && !has_implicit_conditions {
            self.spell_target_position_store
                .as_deref()
                .and_then(|store| store.get(spell_id_u32, effect.effect_index))
        } else {
            None
        };
        let caster_position = self.player_position_like_cpp()?;
        let range = self
            .spell_misc_store
            .as_deref()
            .and_then(|store| store.get_by_spell_id(spell_id_u32))
            .and_then(|misc| {
                self.spell_range_store
                    .as_deref()
                    .and_then(|store| store.get(u32::from(misc.range_index)))
            })
            .map(|range| range.range_max[0].max(range.range_max[1]))?;
        let radius = spell_effect_radius_like_cpp(
            effect.effect_radius_index_1,
            self.spell_radius_store.as_deref(),
        );
        let position = if let Some(target_position) = target_position {
            if target_position.target_map_id == self.player_map_id_like_cpp()
                && caster_position.distance(&target_position.position) <= range
            {
                target_position.position
            } else if radius == 0.0 {
                caster_position
            } else {
                self.randomized_or_db_caster_fallback_destination_like_cpp(caster_position, radius)
            }
        } else if let Some(position) = self.represented_nearby_entry_destination_like_cpp(
            effect,
            &caster_position,
            range,
            implicit_conditions.as_deref().map(Vec::as_slice),
        ) {
            self.apply_spell_destination_facing_override_like_cpp(spell_id, effect, position)
        } else if !is_or_db {
            return None;
        } else if radius == 0.0 {
            self.apply_spell_destination_facing_override_like_cpp(spell_id, effect, caster_position)
        } else {
            let randomized =
                self.randomized_or_db_caster_fallback_destination_like_cpp(caster_position, radius);
            self.apply_spell_destination_facing_override_like_cpp(spell_id, effect, randomized)
        };
        let mut target_data = target_data.clone();
        target_data.dst_location = Some(wow_packet::packets::spell::TargetLocation {
            transport: ObjectGuid::EMPTY,
            position,
        });
        Some(target_data)
    }

    fn represented_gameobject_summon_missing_nearby_entry_destination_like_cpp(
        &mut self,
        spell_id: i32,
        spell_info: &wow_data::SpellInfo,
        target_data: &SpellTargetData,
        focus_object: Option<RepresentedSpellFocusObjectLikeCpp>,
    ) -> bool {
        if target_data.dst_location.is_some() {
            return false;
        }

        spell_info.effects().iter().any(|effect| {
            if effect.effect != wow_data::spell::spell_effect_types::SPELL_EFFECT_SUMMON_OBJECT_WILD
                && !spell_effect_is_represented_summon_object_slot_like_cpp(effect.effect)
            {
                return false;
            }
            if !spell_effect_has_non_or_db_nearby_entry_destination_like_cpp(effect) {
                return false;
            }
            if self
                .represented_focus_destination_target_data_like_cpp(
                    spell_id,
                    effect,
                    target_data,
                    focus_object,
                )
                .is_some()
            {
                return false;
            }

            self.represented_nearby_entry_destination_target_data_like_cpp(
                spell_id,
                effect,
                target_data,
            )
            .is_none()
        })
    }

    fn randomized_or_db_caster_fallback_destination_like_cpp(
        &mut self,
        caster_position: Position,
        radius: f32,
    ) -> Position {
        if !radius.is_finite() || radius <= 0.0 {
            return caster_position;
        }

        // C++ target 142 is TARGET_DIR_FRONT_RIGHT
        // (`SpellInfo.cpp:385`), so `MovePositionToFirstCollision` uses
        // caster orientation plus -PI/4. The represented seam keeps the
        // radius/direction behavior; terrain raycast/first-collision remains
        // part of the full map/path runtime work.
        let distance = self
            .represented_runtime_rng_like_cpp
            .gen_range(0.0..=radius);
        let angle = caster_position.orientation - std::f32::consts::FRAC_PI_4;
        Position::new(
            caster_position.x + distance * angle.cos(),
            caster_position.y + distance * angle.sin(),
            caster_position.z,
            caster_position.orientation,
        )
    }

    fn represented_nearby_entry_destination_like_cpp(
        &self,
        effect: &wow_data::SpellEffectInfo,
        caster_position: &Position,
        range: f32,
        implicit_conditions: Option<&[wow_data::Condition]>,
    ) -> Option<Position> {
        let Ok(entry) = u32::try_from(effect.effect_misc_value_1) else {
            return None;
        };
        if entry == 0 || !range.is_finite() || range <= 0.0 {
            return None;
        }

        let Some(player_map_key) = self.current_canonical_player_map_key_like_cpp() else {
            return None;
        };
        let has_implicit_conditions =
            implicit_conditions.is_some_and(|conditions| !conditions.is_empty());
        let caster_object = if has_implicit_conditions {
            self.build_condition_player_object_like_cpp()
        } else {
            None
        };
        let player_unit_snapshot = self.condition_player_unit_snapshot_like_cpp();
        let player_snapshot = self.condition_player_snapshot_like_cpp();
        let player_condition_context = if has_implicit_conditions {
            Some(self.represented_player_condition_context_like_cpp())
        } else {
            None
        };
        let player_condition_store = if has_implicit_conditions {
            self.player_condition_store.as_ref().cloned()
        } else {
            None
        };
        let area_table_store = if has_implicit_conditions {
            self.area_table_store.as_ref().cloned()
        } else {
            None
        };
        let Some(manager) = &self.canonical_map_manager else {
            return None;
        };
        let Ok(manager) = manager.lock() else {
            return None;
        };
        let Some(map) = manager.find_map(player_map_key.map_id, player_map_key.instance_id) else {
            return None;
        };
        let nearby =
            map.map()
                .nearby_cell_guids_like_cpp(caster_position.x, caster_position.y, range);
        let mut best: Option<(f32, Position)> = None;

        for guid in nearby
            .world
            .creatures
            .iter()
            .chain(nearby.grid.creatures.iter())
        {
            let Some(creature) = map.map().get_typed_creature(*guid) else {
                continue;
            };
            if creature.unit().world().object().entry() != entry {
                continue;
            }
            let position = creature.unit().world().position();
            let distance = position.distance(caster_position);
            if distance < range
                && best.is_none_or(|(best_distance, _)| distance < best_distance)
                && self.represented_nearby_candidate_meets_implicit_conditions_like_cpp(
                    creature.unit().world(),
                    Some(crate::conditions::ConditionUnitSnapshot {
                        level: u32::from(creature.level()),
                        health: creature.current_health(),
                        max_health: creature.max_health(),
                        class_mask: 0,
                        race: 0,
                        creature_type: None,
                        is_alive: creature.is_alive(),
                        is_charmed: false,
                        in_water: false,
                        unit_state: 0,
                        stand_state: UnitStandStateType::Stand as u32,
                    }),
                    implicit_conditions,
                    caster_object.as_ref(),
                    player_unit_snapshot,
                    player_snapshot,
                    player_condition_store.as_deref(),
                    player_condition_context.as_ref(),
                    area_table_store.as_deref(),
                )
            {
                best = Some((distance, position));
            }
        }

        for guid in nearby.grid.gameobjects.iter() {
            let Some(gameobject) = map.map().get_typed_game_object(*guid) else {
                continue;
            };
            if gameobject.world().object().entry() != entry {
                continue;
            }
            let position = gameobject.world().position();
            let distance = position.distance(caster_position);
            if distance < range
                && best.is_none_or(|(best_distance, _)| distance < best_distance)
                && self.represented_nearby_candidate_meets_implicit_conditions_like_cpp(
                    gameobject.world(),
                    None,
                    implicit_conditions,
                    caster_object.as_ref(),
                    player_unit_snapshot,
                    player_snapshot,
                    player_condition_store.as_deref(),
                    player_condition_context.as_ref(),
                    area_table_store.as_deref(),
                )
            {
                best = Some((distance, position));
            }
        }

        best.map(|(_, position)| position)
    }

    fn represented_nearby_candidate_meets_implicit_conditions_like_cpp(
        &self,
        candidate: &WorldObject,
        candidate_unit_snapshot: Option<crate::conditions::ConditionUnitSnapshot>,
        implicit_conditions: Option<&[wow_data::Condition]>,
        caster_object: Option<&WorldObject>,
        player_unit_snapshot: crate::conditions::ConditionUnitSnapshot,
        player_snapshot: crate::conditions::ConditionPlayerSnapshot,
        player_condition_store: Option<&wow_data::PlayerConditionStore>,
        player_condition_context: Option<&RepresentedPlayerConditionContextLikeCpp>,
        area_table_store: Option<&wow_data::AreaTableStore>,
    ) -> bool {
        let Some(conditions) = implicit_conditions.filter(|conditions| !conditions.is_empty())
        else {
            return true;
        };
        let Some(condition_store) = self.condition_store.as_ref() else {
            return false;
        };

        // C++ `WorldObjectSpellTargetCheck` builds `ConditionSourceInfo(nullptr, caster)`
        // and then assigns the tested target to condition slot 0.
        let mut source_info = crate::conditions::ConditionSourceInfo::from_targets(
            Some(candidate),
            caster_object,
            None,
        );
        if let Some(snapshot) = candidate_unit_snapshot {
            source_info.set_unit_target_snapshot(0, snapshot);
        }
        source_info.set_unit_target_snapshot(1, player_unit_snapshot);
        source_info.set_player_target_snapshot(1, player_snapshot);
        if let (Some(store), Some(context)) = (player_condition_store, player_condition_context) {
            source_info.set_player_condition_store(store);
            source_info.set_player_condition_context(1, context.as_context(self));
        }

        crate::conditions::is_object_meet_to_conditions_like_cpp(
            &mut source_info,
            conditions,
            condition_store.as_ref(),
            |condition, source_info| {
                crate::conditions::condition_meets_basic_like_cpp(
                    condition,
                    source_info,
                    |area_id, required_area_id| {
                        area_table_store.is_some_and(|store| {
                            store.is_in_area_like_cpp(area_id, required_area_id)
                        })
                    },
                )
                .value()
                .unwrap_or(false)
            },
        )
    }

    fn implicit_target_conditions_like_cpp(
        &self,
        spell_id: i32,
        effect_index: u32,
    ) -> Option<Arc<wow_data::ConditionContainer>> {
        self.spell_store
            .as_deref()
            .and_then(|store| store.implicit_target_conditions_like_cpp(spell_id, effect_index))
            .and_then(|conditions| conditions.upgrade())
    }

    fn has_implicit_target_conditions_like_cpp(&self, spell_id: i32, effect_index: u32) -> bool {
        self.implicit_target_conditions_like_cpp(spell_id, effect_index)
            .is_some_and(|conditions| !conditions.is_empty())
    }

    /// Live bounded C++ `Spell::EffectAddFarsight` consumer.
    ///
    /// Source-of-truth: canonical `wow_map::Map::map_objects`; this helper never
    /// creates fallback/session mirror objects. C++ anchors:
    /// `SpellEffects.cpp:2237-2261`, `SpellInfo.cpp:653-692`,
    /// `SpellInfo.cpp:3894-3910`, `Spell.cpp:133-205`.
    pub(crate) fn apply_effect_add_farsight_like_cpp(
        &mut self,
        spell_id: i32,
        effect: &wow_data::SpellEffectInfo,
        target_data: &SpellTargetData,
        spell_visual_id: u32,
        cast_time_ms: u32,
    ) -> Option<wow_map::map::FarsightDynamicObjectCreateOutcomeLikeCpp> {
        if effect.effect != wow_data::spell::spell_effect_types::SPELL_EFFECT_ADD_FARSIGHT {
            return None;
        }
        let dest = target_data.dst_location?.position;
        let player_guid = self.player_guid()?;
        let spell_id_u32 = u32::try_from(spell_id).ok()?;
        let spell_visual_id_i32 = i32::try_from(spell_visual_id).ok()?;
        let duration_index = self
            .spell_misc_store
            .as_deref()
            .and_then(|store| store.get_by_spell_id(spell_id_u32))
            .map(|entry| u32::from(entry.duration_index))
            .unwrap_or(0);
        let duration_ms =
            spell_duration_ms_like_cpp(duration_index, self.spell_duration_store.as_deref());
        let radius = spell_effect_radius_like_cpp(
            effect.effect_radius_index_1,
            self.spell_radius_store.as_deref(),
        );
        let manager = Arc::clone(self.canonical_map_manager.as_ref()?);
        let mut manager = manager.lock().ok()?;
        let map_id = u32::from(self.player_map_id_like_cpp());
        let mut instance_id = None;
        manager.do_for_all_maps_with_map_id(map_id, |managed| {
            if instance_id.is_none() && managed.map().get_typed_player(player_guid).is_some() {
                instance_id = Some(managed.instance_id());
            }
        });
        let managed = manager.find_map_mut(map_id, instance_id.unwrap_or(0))?;
        Some(managed.map_mut().create_farsight_dynamic_object_like_cpp(
            player_guid,
            spell_id_u32,
            spell_visual_id_i32,
            dest,
            radius,
            duration_ms,
            u64::from(cast_time_ms),
            self.realm_id,
            player_guid.server_id(),
        ))
    }

    /// Dormant live resolver for C++ `Spell::EffectSummonObjectWild`.
    ///
    /// C++ anchors: `SpellEffects.cpp:2937-2986` and
    /// `GameObject.cpp:1187-1200`. This resolves the DB-backed template,
    /// spell destination or caster close-point fallback, and spell duration,
    /// then delegates the map-owned body to `wow_map`.
    #[allow(dead_code)]
    pub(crate) fn apply_effect_summon_object_wild_like_cpp(
        &mut self,
        spell_id: i32,
        effect: &wow_data::SpellEffectInfo,
        target_data: &SpellTargetData,
    ) -> Option<ApplyEffectSummonObjectWildSessionOutcomeLikeCpp> {
        self.apply_effect_summon_object_wild_with_focus_like_cpp(
            spell_id,
            effect,
            target_data,
            None,
        )
    }

    pub(crate) fn apply_effect_summon_object_wild_with_focus_like_cpp(
        &mut self,
        spell_id: i32,
        effect: &wow_data::SpellEffectInfo,
        target_data: &SpellTargetData,
        focus_object: Option<RepresentedSpellFocusObjectLikeCpp>,
    ) -> Option<ApplyEffectSummonObjectWildSessionOutcomeLikeCpp> {
        if effect.effect != wow_data::spell::spell_effect_types::SPELL_EFFECT_SUMMON_OBJECT_WILD {
            return None;
        }
        let Ok(template_entry) = u32::try_from(effect.effect_misc_value_1) else {
            return Some(ApplyEffectSummonObjectWildSessionOutcomeLikeCpp {
                status: ApplyEffectSummonObjectWildSessionStatusLikeCpp::InvalidTemplateEntry,
                template_entry: None,
                duration_ms: None,
                explicit_destination_used: false,
                close_point_fallback_represented: false,
                map_outcome: None,
            });
        };
        let Some(template_store) = self.gameobject_template_lifecycle_store.as_deref() else {
            return Some(ApplyEffectSummonObjectWildSessionOutcomeLikeCpp {
                status: ApplyEffectSummonObjectWildSessionStatusLikeCpp::MissingTemplateStore,
                template_entry: Some(template_entry),
                duration_ms: None,
                explicit_destination_used: false,
                close_point_fallback_represented: false,
                map_outcome: None,
            });
        };
        let Some(template) = template_store.get(template_entry) else {
            return Some(ApplyEffectSummonObjectWildSessionOutcomeLikeCpp {
                status: ApplyEffectSummonObjectWildSessionStatusLikeCpp::MissingTemplate,
                template_entry: Some(template_entry),
                duration_ms: None,
                explicit_destination_used: false,
                close_point_fallback_represented: false,
                map_outcome: None,
            });
        };
        let Some(caster_guid) = self.player_guid() else {
            return Some(ApplyEffectSummonObjectWildSessionOutcomeLikeCpp {
                status: ApplyEffectSummonObjectWildSessionStatusLikeCpp::MissingCaster,
                template_entry: Some(template_entry),
                duration_ms: None,
                explicit_destination_used: true,
                close_point_fallback_represented: false,
                map_outcome: None,
            });
        };
        let position_outcome = if let Some(dest) = target_data.dst_location {
            wow_map::map::spell_effect_summon_object_wild_position_like_cpp(
                Position::ZERO,
                0.0,
                0.0,
                Some(dest.position),
            )
        } else {
            let Some(caster_position) = self.player_position_like_cpp() else {
                return Some(ApplyEffectSummonObjectWildSessionOutcomeLikeCpp {
                    status: ApplyEffectSummonObjectWildSessionStatusLikeCpp::MissingCasterPosition,
                    template_entry: Some(template_entry),
                    duration_ms: None,
                    explicit_destination_used: false,
                    close_point_fallback_represented: false,
                    map_outcome: None,
                });
            };
            let close_point_source_position = focus_object
                .map(|focus| focus.position)
                .unwrap_or(caster_position);
            let represented_source_reach = if focus_object.is_some() {
                // C++ calls `target->GetClosePoint`; represented GameObject size
                // is not carried here yet, so focus-backed fallback uses the
                // focus position with no extra object reach instead of the
                // caster combat reach.
                0.0
            } else {
                self.canonical_player_combat_reach_snapshot_like_cpp()
            };
            wow_map::map::spell_effect_summon_object_wild_position_like_cpp(
                close_point_source_position,
                represented_source_reach,
                close_point_source_position.orientation,
                None,
            )
        };
        let Some(manager) = self.canonical_map_manager.as_ref().cloned() else {
            return Some(ApplyEffectSummonObjectWildSessionOutcomeLikeCpp {
                status: ApplyEffectSummonObjectWildSessionStatusLikeCpp::MissingCanonicalMapManager,
                template_entry: Some(template_entry),
                duration_ms: None,
                explicit_destination_used: position_outcome.explicit_destination_used,
                close_point_fallback_represented: position_outcome.close_point_fallback_used,
                map_outcome: None,
            });
        };
        let Some(player_map_key) = focus_object
            .map(|focus| focus.map_key)
            .or_else(|| self.current_canonical_player_map_key_like_cpp())
        else {
            return Some(ApplyEffectSummonObjectWildSessionOutcomeLikeCpp {
                status: ApplyEffectSummonObjectWildSessionStatusLikeCpp::MissingCanonicalPlayerMap,
                template_entry: Some(template_entry),
                duration_ms: None,
                explicit_destination_used: position_outcome.explicit_destination_used,
                close_point_fallback_represented: position_outcome.close_point_fallback_used,
                map_outcome: None,
            });
        };
        let spell_id_u32 = u32::try_from(spell_id).unwrap_or(0);
        let duration_index = self
            .spell_misc_store
            .as_deref()
            .and_then(|store| store.get_by_spell_id(spell_id_u32))
            .map(|entry| u32::from(entry.duration_index))
            .unwrap_or(0);
        let duration_ms =
            spell_duration_ms_like_cpp(duration_index, self.spell_duration_store.as_deref());
        let lifecycle_record = wow_data::gameobject_template_lifecycle_record_like_cpp(template);
        let Ok(mut manager) = manager.lock() else {
            return Some(ApplyEffectSummonObjectWildSessionOutcomeLikeCpp {
                status: ApplyEffectSummonObjectWildSessionStatusLikeCpp::MissingCanonicalMapManager,
                template_entry: Some(template_entry),
                duration_ms: Some(duration_ms),
                explicit_destination_used: position_outcome.explicit_destination_used,
                close_point_fallback_represented: position_outcome.close_point_fallback_used,
                map_outcome: None,
            });
        };
        let Some(managed) = manager.find_map_mut(player_map_key.map_id, player_map_key.instance_id)
        else {
            return Some(ApplyEffectSummonObjectWildSessionOutcomeLikeCpp {
                status: ApplyEffectSummonObjectWildSessionStatusLikeCpp::MissingManagedMap,
                template_entry: Some(template_entry),
                duration_ms: Some(duration_ms),
                explicit_destination_used: position_outcome.explicit_destination_used,
                close_point_fallback_represented: position_outcome.close_point_fallback_used,
                map_outcome: None,
            });
        };
        let map_outcome = managed.map_mut().spell_effect_summon_object_wild_like_cpp(
            caster_guid,
            spell_id_u32,
            lifecycle_record,
            position_outcome.position,
            duration_ms,
        );

        Some(ApplyEffectSummonObjectWildSessionOutcomeLikeCpp {
            status: ApplyEffectSummonObjectWildSessionStatusLikeCpp::MapResolved,
            template_entry: Some(template_entry),
            duration_ms: Some(duration_ms),
            explicit_destination_used: position_outcome.explicit_destination_used,
            close_point_fallback_represented: position_outcome.close_point_fallback_used,
            map_outcome: Some(map_outcome),
        })
    }

