    fn make_session() -> (
        WorldSession,
        flume::Sender<WorldPacket>,
        flume::Receiver<Vec<u8>>,
    ) {
        let (pkt_tx, pkt_rx) = flume::bounded(100);
        let (send_tx, send_rx) = flume::unbounded();

        let mut session = WorldSession::new(
            1,
            "TestAccount".into(),
            0,
            2,
            9, // account_expansion (raw from DB)
            54261,
            vec![0u8; 40],
            "esES".into(),
            pkt_rx,
            send_tx,
        );
        session.set_active_player_local_flags_like_cpp(
            PLAYER_LOCAL_FLAG_OVERRIDE_TRANSPORT_SERVER_TIME_LIKE_CPP,
        );

        (session, pkt_tx, send_rx)
    }

    #[test]
    fn combat_rating_multiplier_uses_gt_table_like_cpp() {
        let (mut session, _, _) = make_session();
        assert_eq!(session.combat_rating_multiplier_like_cpp(80, 8), 1.0);

        let mut columns = [0.0f32; wow_data::CombatRatingsGameTableLikeCpp::VALUE_COLUMN_COUNT];
        columns[wow_data::CombatRatingsEntryLikeCpp::CRIT_MELEE] = 45.905987;
        columns[wow_data::CombatRatingsEntryLikeCpp::DODGE] = 45.250187;
        session.set_combat_ratings_game_table(Arc::new(
            wow_data::CombatRatingsGameTableLikeCpp::from_rows([
                wow_data::CombatRatingsEntryLikeCpp::from_columns(columns),
            ]),
        ));

        assert!(
            (session.combat_rating_multiplier_like_cpp(1, 8) - (1.0 / 45.905987)).abs() < 0.00001
        );
        assert!(
            (session.combat_rating_multiplier_like_cpp(1, 2) - (1.0 / 45.250187)).abs() < 0.00001
        );
        assert_eq!(
            session.combat_rating_multiplier_like_cpp(1, 23),
            1.0,
            "C++ ratings without a CombatRatings column use default multiplier"
        );
    }

    #[test]
    fn chr_classes_store_drives_creature_display_power_else_fallback_like_cpp() {
        use wow_data::character_progression::{ChrClassesEntry, ChrClassesStore};
        let (mut session, _, _) = make_session();

        // [M0.1/#14] Without the ChrClasses store, class display power uses the
        // hardcoded fallback (class 8 = Mage → Mana).
        assert_eq!(
            session.creature_display_power_for_class_like_cpp(8),
            PowerType::Mana as u8
        );

        // With the store loaded, the DB2 `display_power` wins over the fallback.
        // Give class 8 a non-default power (Rage) to prove the store is consulted.
        session.set_chr_classes_store(Arc::new(ChrClassesStore::from_entries([ChrClassesEntry {
            id: 8,
            display_power: PowerType::Rage as u8,
            ..Default::default()
        }])));
        assert_eq!(
            session.creature_display_power_for_class_like_cpp(8),
            PowerType::Rage as u8
        );
        // A class with no DB2 row still falls back (class 4 = Rogue → Energy).
        assert_eq!(
            session.creature_display_power_for_class_like_cpp(4),
            PowerType::Energy as u8
        );
    }

