    fn trinity_string_entry_like_cpp(
        entry: u32,
        content_default: &str,
    ) -> wow_data::TrinityStringEntryLikeCpp {
        wow_data::TrinityStringEntryLikeCpp {
            entry,
            content: std::array::from_fn(|idx| {
                if idx == 0 {
                    content_default.to_string()
                } else {
                    String::new()
                }
            }),
        }
    }

