        quest.objectives.push(wow_data::quest::QuestObjective {
            id: quest_id * 10,
            quest_id,
            obj_type: 0, // C++ QUEST_OBJECTIVE_MONSTER
            order: 0,
            storage_index: 0,
            object_id: creature_entry as i32,
            amount: 1,
            flags: 0,
            flags2: 0,
            progress_bar_weight: 0.0,
            description: String::new(),
        });
