        session
            .apply_represented_aura_modifier_like_cpp(
                20_028,
                caster,
                &vehicle_flight,
                RepresentedAuraEffectLikeCpp::VehicleFlightSpeed,
                30_000,
            )
            .unwrap();
        session.recompute_represented_flight_speed_rate_like_cpp();
