    #[test]
    fn time_sync_response_sets_initial_clock_delta_like_cpp() {
        let (mut session, _pkt_tx, _send_rx) = make_session();
        let _ = WorldSession::game_time_ms_like_cpp();
        std::thread::sleep(std::time::Duration::from_millis(2));
        let sent_time = WorldSession::game_time_ms_like_cpp();
        session.time_sync_pending_requests.insert(7, sent_time);

        session.record_time_sync_response_like_cpp(7, sent_time.saturating_sub(1));

        assert!(session.time_sync_pending_requests.is_empty());
        assert_eq!(session.time_sync_clock_delta_queue.len(), 1);
        assert!(
            session.time_sync_clock_delta >= 1,
            "expected initial fallback delta from first sample"
        );
    }

    #[tokio::test]
    async fn time_sync_response_alias_opcodes_dispatch_to_same_handler_like_cpp() {
        for opcode in [
            ClientOpcodes::TimeSyncResponseDropped,
            ClientOpcodes::TimeSyncResponseFailed,
        ] {
            let (mut session, _pkt_tx, _send_rx) = make_session();
            session.set_state(SessionState::LoggedIn);
            let _ = WorldSession::game_time_ms_like_cpp();
            std::thread::sleep(std::time::Duration::from_millis(2));
            let sent_time = WorldSession::game_time_ms_like_cpp();
            session.time_sync_pending_requests.insert(11, sent_time);

            let mut bytes = Vec::new();
            bytes.extend_from_slice(&(opcode as u16).to_le_bytes());
            bytes.extend_from_slice(&11u32.to_le_bytes());
            bytes.extend_from_slice(&sent_time.saturating_sub(1).to_le_bytes());

            session
                .dispatch_packet(WorldPacket::from_bytes(&bytes))
                .await;

            assert!(
                session.time_sync_pending_requests.is_empty(),
                "{opcode:?} must consume the pending request like C++ HandleTimeSyncResponse"
            );
            assert_eq!(
                session.time_sync_clock_delta_queue.len(),
                1,
                "{opcode:?} must record one clock-delta sample through the shared handler"
            );
        }
    }

    #[tokio::test]
    async fn dispatch_routes_send_text_emote_to_handler_like_cpp() {
        let (mut session, _pkt_tx, send_rx) = make_session();
        let player_guid = ObjectGuid::create_player(1, 101);
        session.set_state(SessionState::LoggedIn);
        session.set_player_guid(Some(player_guid));
        session.player_name = Some("Emoter".to_string());
        session.set_emotes_text_store_like_cpp(Arc::new(wow_data::EmotesTextStore::from_entries(
            [wow_data::EmotesTextEntry {
                id: 101,
                name: "wave".to_string(),
                emote_id: 3,
            }],
        )));

        let mut packet = WorldPacket::new_empty();
        packet.write_uint16(ClientOpcodes::SendTextEmote as u16);
        packet.write_packed_guid(&ObjectGuid::EMPTY);
        packet.write_int32(101);
        packet.write_int32(-1);
        packet.write_uint32(0);
        packet.write_int32(0);
        let bytes = packet.data().to_vec();

        session
            .dispatch_packet(WorldPacket::from_bytes(&bytes))
            .await;

        let mut anim = WorldPacket::from_bytes(&send_rx.try_recv().expect("anim emote"));
        assert_eq!(
            anim.read_uint16().expect("anim opcode"),
            ServerOpcodes::Emote as u16
        );
        assert_eq!(anim.read_packed_guid().expect("anim source"), player_guid);
        assert_eq!(anim.read_int32().expect("anim emote"), 3);

        let mut text = WorldPacket::from_bytes(&send_rx.try_recv().expect("text emote"));
        assert_eq!(
            text.read_uint16().expect("text opcode"),
            ServerOpcodes::TextEmote as u16
        );
        assert_eq!(text.read_packed_guid().expect("text source"), player_guid);
        let _account_guid = text.read_packed_guid().expect("source account");
        assert_eq!(text.read_int32().expect("text emote id"), 101);
        assert_eq!(text.read_int32().expect("text sound index"), -1);
        assert_eq!(
            text.read_packed_guid().expect("text target"),
            ObjectGuid::EMPTY
        );
        assert!(send_rx.try_recv().is_err());
    }

    #[test]
    fn adjust_client_movement_time_uses_clock_delta_or_cpp_fallback() {
        let (mut session, _pkt_tx, _send_rx) = make_session();
        session.time_sync_clock_delta = 250;
        assert_eq!(session.adjust_client_movement_time_like_cpp(1_000), 1_250);

        session.time_sync_clock_delta = 0;
        let adjusted = session.adjust_client_movement_time_like_cpp(1_000);
        assert_ne!(adjusted, 1_000);
    }

    #[test]
    fn send_time_sync_uses_cpp_timer_sequence() {
        let (mut session, _pkt_tx, _send_rx) = make_session();

        session.send_time_sync();
        assert_eq!(session.time_sync_next_counter, 1);
        assert_eq!(session.time_sync_timer_ms, 5_000);
        assert!(session.time_sync_pending_requests.contains_key(&0));

        session.send_time_sync();
        assert_eq!(session.time_sync_next_counter, 2);
        assert_eq!(session.time_sync_timer_ms, 10_000);
        assert!(session.time_sync_pending_requests.contains_key(&1));
    }

