    fn battle_pet_change_quality_applies_cpp_gates_without_side_effects() {
        let (mut session, _, send_rx) = make_session();
        let pet_guid = ObjectGuid::create_global(HighGuid::BattlePet, 0, 0x189);
        let unknown_guid = ObjectGuid::create_global(HighGuid::BattlePet, 0, 0x18a);

        session.add_represented_battle_pet_packet_info_like_cpp(
            pet_guid,
            RepresentedBattlePetDataLikeCpp {
                species: 11,
                quality: 2,
                health: 50,
                max_health: 100,
                save_info: RepresentedBattlePetSaveInfoLikeCpp::Unchanged,
                ..RepresentedBattlePetDataLikeCpp::minimal_like_cpp(
                    0,
                    RepresentedBattlePetSaveInfoLikeCpp::Unchanged,
                )
            },
        );

        assert_eq!(
            session.battle_pet_change_battle_pet_quality_represented_like_cpp(pet_guid, 3),
            RepresentedBattlePetQualityOutcomeLikeCpp::NoJournalLock
        );
        session.send_battle_pet_journal_lock_status_like_cpp();
        let _ = drain_server_packet_bytes(&send_rx);

        assert_eq!(
            session.battle_pet_change_battle_pet_quality_represented_like_cpp(unknown_guid, 3),
            RepresentedBattlePetQualityOutcomeLikeCpp::UnknownPet
        );
        assert_eq!(
            session.battle_pet_change_battle_pet_quality_represented_like_cpp(pet_guid, 4),
            RepresentedBattlePetQualityOutcomeLikeCpp::QualityAboveRare
        );
        install_represented_battle_pet_species_flags_like_cpp(
            &mut session,
            11,
            wow_data::BATTLE_PET_SPECIES_FLAG_CANT_BATTLE_LIKE_CPP,
        );
        assert_eq!(
            session.battle_pet_change_battle_pet_quality_represented_like_cpp(pet_guid, 3),
            RepresentedBattlePetQualityOutcomeLikeCpp::CantBattle
        );
        install_represented_battle_pet_species_flags_like_cpp(&mut session, 11, 0);
        assert_eq!(
            session.battle_pet_change_battle_pet_quality_represented_like_cpp(pet_guid, 2),
            RepresentedBattlePetQualityOutcomeLikeCpp::NotUpgrade
        );

        let pet = session
            .represented_battle_pet_like_cpp(pet_guid)
            .expect("unchanged pet");
        assert_eq!(pet.quality, 2);
        assert_eq!(pet.health, 50);
        assert_eq!(pet.max_health, 100);
        assert_eq!(
            pet.save_info,
            RepresentedBattlePetSaveInfoLikeCpp::Unchanged
        );
        assert!(drain_server_packet_bytes(&send_rx).is_empty());
    }

    fn install_represented_battle_pet_stat_stores_like_cpp(session: &mut WorldSession) {
        session.set_battle_pet_breed_state_store(Arc::new(BattlePetBreedStateStore::from_entries(
            [
                wow_data::BattlePetBreedStateEntry {
                    id: 1,
                    battle_pet_state_id: wow_data::BATTLE_PET_STATE_STAT_STAMINA_LIKE_CPP,
                    value: 500,
                    battle_pet_breed_id: 7,
                },
                wow_data::BattlePetBreedStateEntry {
                    id: 2,
                    battle_pet_state_id: wow_data::BATTLE_PET_STATE_STAT_POWER_LIKE_CPP,
                    value: 300,
                    battle_pet_breed_id: 7,
                },
                wow_data::BattlePetBreedStateEntry {
                    id: 3,
                    battle_pet_state_id: wow_data::BATTLE_PET_STATE_STAT_SPEED_LIKE_CPP,
                    value: 200,
                    battle_pet_breed_id: 7,
                },
            ],
        )));
        session.set_battle_pet_species_state_store(Arc::new(
            BattlePetSpeciesStateStore::from_entries([
                wow_data::BattlePetSpeciesStateEntry {
                    id: 10,
                    battle_pet_state_id: wow_data::BATTLE_PET_STATE_STAT_STAMINA_LIKE_CPP,
                    value: 100,
                    battle_pet_species_id: 11,
                },
                wow_data::BattlePetSpeciesStateEntry {
                    id: 11,
                    battle_pet_state_id: wow_data::BATTLE_PET_STATE_STAT_POWER_LIKE_CPP,
                    value: 50,
                    battle_pet_species_id: 11,
                },
                wow_data::BattlePetSpeciesStateEntry {
                    id: 12,
                    battle_pet_state_id: wow_data::BATTLE_PET_STATE_STAT_SPEED_LIKE_CPP,
                    value: 25,
                    battle_pet_species_id: 11,
                },
            ]),
        ));
        session.set_battle_pet_breed_quality_store(Arc::new(
            BattlePetBreedQualityStore::from_entries([wow_data::BattlePetBreedQualityEntry {
                id: 20,
                state_multiplier: 1.5,
                quality_enum: 3,
            }]),
        ));
    }

    fn install_represented_battle_pet_species_flags_like_cpp(
        session: &mut WorldSession,
        species: u32,
        flags: i32,
    ) {
        install_represented_battle_pet_species_like_cpp(session, species, 0, flags);
    }

    fn install_represented_battle_pet_species_like_cpp(
        session: &mut WorldSession,
        species: u32,
        creature_id: i32,
        flags: i32,
    ) {
        session.set_battle_pet_species_store(Arc::new(
            wow_data::BattlePetSpeciesStore::from_entries([wow_data::BattlePetSpeciesEntry {
                id: species,
                description: String::new(),
                source_text: String::new(),
                creature_id,
                summon_spell_id: 0,
                icon_file_data_id: 0,
                pet_type_enum: 0,
                flags,
                source_type_enum: 0,
                card_ui_model_scene_id: 0,
                loadout_ui_model_scene_id: 0,
            }]),
        ));
    }

