        session.process_pending().await;

        let state = session
            .represented_gameobject_use_states
            .get(&gameobject_guid)
            .unwrap();
        assert_eq!(state.loot_state, Some(wow_entities::LootState::Activated));
        assert!(session.represented_gameobject_use_effects.is_empty());

